fn prefill_liveness_log(args: std::fmt::Arguments<'_>) {
    if prefill_liveness_timing_enabled() {
        let mut stderr = std::io::stderr().lock();
        let _ = writeln!(stderr, "[PREFILL-LIVENESS] {}", args);
        let _ = stderr.flush();
    }
}

macro_rules! prefill_liveness {
    ($($arg:tt)*) => {{
        prefill_liveness_log(format_args!($($arg)*));
    }};
}

