fn prefill_liveness_layer_spec_contains(spec: &str, layer_idx: usize, empty_default: bool) -> bool {
    let spec = spec.trim();
    if spec.is_empty() {
        return empty_default;
    }
    if matches!(spec.to_ascii_lowercase().as_str(), "all" | "*") {
        return true;
    }
    for part in spec.split(',') {
        let part = part.trim();
        if part.is_empty() {
            continue;
        }
        if let Some((lo, hi)) = part.split_once('-') {
            if let (Ok(lo), Ok(hi)) = (lo.trim().parse::<usize>(), hi.trim().parse::<usize>()) {
                if layer_idx >= lo && layer_idx <= hi {
                    return true;
                }
            }
        } else if let Ok(value) = part.parse::<usize>() {
            if value == layer_idx {
                return true;
            }
        }
    }
    false
}

fn expert_hqq_prefill_output_consumption_enabled_for_values(
    layer_idx: usize,
    consume_value: Option<&str>,
    layers_value: Option<&str>,
) -> bool {
    let Some(value) = consume_value else {
        return false;
    };
    if !matches!(
        value.trim().to_ascii_lowercase().as_str(),
        "1" | "true" | "yes" | "on"
    ) {
        return false;
    }
    prefill_liveness_layer_spec_contains(layers_value.unwrap_or(""), layer_idx, true)
}

fn expert_hqq_prefill_consume_boundary_diagnosis_enabled_for_values(
    layer_idx: usize,
    diagnose_value: Option<&str>,
    layers_value: Option<&str>,
) -> bool {
    let Some(value) = diagnose_value else {
        return false;
    };
    if !matches!(
        value.trim().to_ascii_lowercase().as_str(),
        "1" | "true" | "yes" | "on"
    ) {
        return false;
    }
    prefill_liveness_layer_spec_contains(layers_value.unwrap_or(""), layer_idx, true)
}

fn expert_hqq_prefill_consume_boundary_diagnosis_top_n_from_value(value: Option<&str>) -> usize {
    value
        .and_then(|raw| raw.trim().parse::<usize>().ok())
        .filter(|&parsed| parsed > 0)
        .map(|parsed| parsed.min(32))
        .unwrap_or(8)
}

