fn expert_hqq_parse_required_usize_env(value: Option<&str>, name: &str) -> Result<usize, String> {
    let Some(raw) = value else {
        return Err(format!(
            "{name} is required when exact-row expert-HQQ attribution is enabled"
        ));
    };
    raw.trim()
        .parse::<usize>()
        .map_err(|e| format!("{name} must be a non-negative integer: {e}"))
}

fn expert_hqq_parse_optional_usize_env(
    value: Option<&str>,
    name: &str,
) -> Result<Option<usize>, String> {
    let Some(raw) = value else {
        return Ok(None);
    };
    if raw.trim().is_empty() {
        return Ok(None);
    }
    raw.trim()
        .parse::<usize>()
        .map(Some)
        .map_err(|e| format!("{name} must be a non-negative integer when set: {e}"))
}

fn parse_required_usize_env_value(
    value: Option<&str>,
    name: &str,
    context: &str,
) -> Result<usize, String> {
    let Some(raw) = value else {
        return Err(format!("{name} is required when {context} is enabled"));
    };
    raw.trim()
        .parse::<usize>()
        .map_err(|e| format!("{name} must be a non-negative integer: {e}"))
}

fn first_token_margin_projection_top_n_from_value(value: Option<&str>) -> usize {
    value
        .and_then(|raw| raw.trim().parse::<usize>().ok())
        .filter(|&parsed| parsed > 0)
        .map(|parsed| parsed.min(32))
        .unwrap_or(8)
}

fn first_token_margin_projection_target_from_values(
    enabled_value: Option<&str>,
    token_a_value: Option<&str>,
    token_b_value: Option<&str>,
    top_n_value: Option<&str>,
) -> Result<Option<FirstTokenMarginProjectionTarget>, String> {
    if !expert_hqq_truthy_env_value(enabled_value) {
        return Ok(None);
    }
    let token_a = expert_hqq_parse_required_usize_env(
        token_a_value,
        "KRASIS_FIRST_TOKEN_MARGIN_PROJECTION_TOKEN_A",
    )?;
    let token_b = expert_hqq_parse_required_usize_env(
        token_b_value,
        "KRASIS_FIRST_TOKEN_MARGIN_PROJECTION_TOKEN_B",
    )?;
    if token_a == token_b {
        return Err(
            "KRASIS_FIRST_TOKEN_MARGIN_PROJECTION_TOKEN_A and _TOKEN_B must differ".to_string(),
        );
    }
    Ok(Some(FirstTokenMarginProjectionTarget {
        token_a,
        token_b,
        top_n: first_token_margin_projection_top_n_from_value(top_n_value),
    }))
}

fn first_token_margin_projection_target_for_scope(
    request_scope_enabled: bool,
    reference_debug_trace_enabled: bool,
    enabled_value: Option<&str>,
    token_a_value: Option<&str>,
    token_b_value: Option<&str>,
    top_n_value: Option<&str>,
) -> Result<Option<FirstTokenMarginProjectionTarget>, String> {
    if !request_scope_enabled {
        return Ok(None);
    }
    let target = first_token_margin_projection_target_from_values(
        enabled_value,
        token_a_value,
        token_b_value,
        top_n_value,
    )?;
    if target.is_some() && !reference_debug_trace_enabled {
        return Err(
            "KRASIS_FIRST_TOKEN_MARGIN_PROJECTION_DIAG requires debug_reference_trace=true"
                .to_string(),
        );
    }
    Ok(target)
}

fn read_only_checkpoint_config_for_scope(
    request_scope_enabled: bool,
    reference_debug_trace_enabled: bool,
    enabled_value: Option<&str>,
) -> Result<ReadOnlyCheckpointConfig, String> {
    if !request_scope_enabled || !expert_hqq_truthy_env_value(enabled_value) {
        return Ok(ReadOnlyCheckpointConfig { enabled: false });
    }
    if !reference_debug_trace_enabled {
        return Err(
            "KRASIS_READ_ONLY_CHECKPOINT_DIAG requires debug_reference_trace=true".to_string(),
        );
    }
    Ok(ReadOnlyCheckpointConfig { enabled: true })
}

fn expert_hqq_exact_row_attribution_target_from_values(
    enabled_value: Option<&str>,
    layer_value: Option<&str>,
    expert_value: Option<&str>,
    sorted_row_value: Option<&str>,
    col_value: Option<&str>,
    trace_row_value: Option<&str>,
) -> Result<Option<ExpertHqqExactRowAttributionTarget>, String> {
    if !expert_hqq_truthy_env_value(enabled_value) {
        return Ok(None);
    }
    Ok(Some(ExpertHqqExactRowAttributionTarget {
        layer_idx: expert_hqq_parse_required_usize_env(
            layer_value,
            "KRASIS_EXPERT_HQQ_PREFILL_EXACT_ROW_LAYER",
        )?,
        expert_idx: expert_hqq_parse_required_usize_env(
            expert_value,
            "KRASIS_EXPERT_HQQ_PREFILL_EXACT_ROW_EXPERT",
        )?,
        sorted_row: expert_hqq_parse_required_usize_env(
            sorted_row_value,
            "KRASIS_EXPERT_HQQ_PREFILL_EXACT_ROW_SORTED_ROW",
        )?,
        col: expert_hqq_parse_required_usize_env(
            col_value,
            "KRASIS_EXPERT_HQQ_PREFILL_EXACT_ROW_COL",
        )?,
        trace_row: expert_hqq_parse_optional_usize_env(
            trace_row_value,
            "KRASIS_EXPERT_HQQ_PREFILL_EXACT_ROW_TRACE_ROW",
        )?,
    }))
}

