fn pct_u64(n: u64, d: u64) -> f64 {
    if d == 0 {
        0.0
    } else {
        n as f64 * 100.0 / d as f64
    }
}

#[derive(Clone, Debug, Default)]
pub(crate) struct PrefillPrescanAccuracyLayerStats {
    model_layer_idx: usize,
    moe_layer_idx: usize,
    n_experts: usize,
    seen: bool,
    chunks: u64,
    prescanned_chunks: u64,
    tokens: u64,
    routed_slots: u64,
    slot_hits: u64,
    token_full_hits: u64,
    actual_active_sum: u64,
    predicted_active_sum: u64,
    active_intersection_sum: u64,
    missed_active_sum: u64,
    extra_active_sum: u64,
    pinned_slot_hits: u64,
    hcs_slot_hits: u64,
    actual_cold_active_sum: u64,
    predicted_cold_active_sum: u64,
    missed_cold_active_sum: u64,
    extra_cold_active_sum: u64,
}

impl PrefillPrescanAccuracyLayerStats {
    fn new(model_layer_idx: usize, moe_layer_idx: usize, n_experts: usize) -> Self {
        Self {
            model_layer_idx,
            moe_layer_idx,
            n_experts,
            seen: true,
            ..Self::default()
        }
    }

    fn active_recall_pct(&self) -> f64 {
        pct_u64(self.active_intersection_sum, self.actual_active_sum)
    }

    fn active_precision_pct(&self) -> f64 {
        pct_u64(self.active_intersection_sum, self.predicted_active_sum)
    }

    fn slot_hit_pct(&self) -> f64 {
        pct_u64(self.slot_hits, self.routed_slots)
    }
}

fn hd512_q2_dynamic_smem_bytes(
    q_heads_per_block: usize,
    br: usize,
    bc: usize,
    head_dim: usize,
) -> usize {
    q_heads_per_block * br * head_dim * 2
        + bc * head_dim * 2
        + bc * head_dim * 2
        + q_heads_per_block * br * bc * 4
        + q_heads_per_block * br * bc * 2
        + q_heads_per_block * 16 * 16 * 4
}

#[derive(Clone, Debug)]
struct TraceRange {
    start: usize,
    end: usize,
}

#[derive(Clone, Debug)]
pub(crate) struct PrefillTraceConfig {
    step_range: Option<TraceRange>,
    layer_range: Option<TraceRange>,
    components: Option<std::collections::HashSet<String>>,
    sample_values: usize,
    max_elems: usize,
}

impl PrefillTraceConfig {
    fn from_env() -> Option<Self> {
        let enabled = std::env::var("KRASIS_TRACE")
            .map(|v| v != "0")
            .unwrap_or(false);
        if !enabled {
            return None;
        }
        Some(Self {
            step_range: parse_trace_range(std::env::var("KRASIS_TRACE_STEPS").ok().as_deref()),
            layer_range: parse_trace_range(std::env::var("KRASIS_TRACE_LAYERS").ok().as_deref()),
            components: parse_trace_components(
                std::env::var("KRASIS_TRACE_COMPONENTS").ok().as_deref(),
            ),
            sample_values: std::env::var("KRASIS_TRACE_VALUES")
                .ok()
                .and_then(|v| v.trim().parse().ok())
                .unwrap_or(4)
                .max(1),
            max_elems: std::env::var("KRASIS_TRACE_ELEMS")
                .ok()
                .and_then(|v| v.trim().parse().ok())
                .unwrap_or(64)
                .max(1),
        })
    }

    fn allows_component(&self, component: &str) -> bool {
        self.components
            .as_ref()
            .map_or(true, |set| set.contains("all") || set.contains(component))
    }

    fn should_emit(&self, step: usize, layer: Option<usize>, component: &str) -> bool {
        if !self.allows_component(component) {
            return false;
        }
        if let Some(range) = self.step_range.as_ref() {
            if step < range.start || step > range.end {
                return false;
            }
        }
        if let Some(range) = self.layer_range.as_ref() {
            if let Some(layer_idx) = layer {
                if layer_idx < range.start || layer_idx > range.end {
                    return false;
                }
            } else {
                return false;
            }
        }
        true
    }
}

fn parse_trace_range(raw: Option<&str>) -> Option<TraceRange> {
    let raw = raw?.trim();
    if raw.is_empty() || raw.eq_ignore_ascii_case("all") {
        return None;
    }
    if let Some((start, end)) = raw.split_once('-') {
        let start = start.trim().parse::<usize>().ok()?;
        let end = end.trim().parse::<usize>().ok()?;
        return Some(TraceRange {
            start,
            end: end.max(start),
        });
    }
    let value = raw.parse::<usize>().ok()?;
    Some(TraceRange {
        start: value,
        end: value,
    })
}

fn parse_trace_components(raw: Option<&str>) -> Option<std::collections::HashSet<String>> {
    let raw = raw?.trim();
    if raw.is_empty() || raw.eq_ignore_ascii_case("all") {
        return None;
    }
    let set = raw
        .split(',')
        .map(|part| part.trim().to_ascii_lowercase())
        .filter(|part| !part.is_empty())
        .collect::<std::collections::HashSet<_>>();
    if set.is_empty() {
        None
    } else {
        Some(set)
    }
}

fn trace_format_sample(values: &[f32]) -> String {
    values
        .iter()
        .map(|v| format!("{:.6}", v))
        .collect::<Vec<_>>()
        .join(",")
}

fn round_f32_slice_to_bf16(values: &[f32]) -> Vec<f32> {
    values
        .iter()
        .map(|&v| half::bf16::from_f32(v).to_f32())
        .collect()
}

#[derive(Clone, Debug)]
struct TraceDiffSummary {
    max_abs: f32,
    max_abs_idx: usize,
    actual_at_max: f32,
    expected_at_max: f32,
    l2: f32,
    mean_abs: f32,
}

fn summarize_trace_diff(actual: &[f32], expected: &[f32]) -> TraceDiffSummary {
    assert_eq!(
        actual.len(),
        expected.len(),
        "trace diff compare length mismatch: actual={} expected={}",
        actual.len(),
        expected.len(),
    );
    if actual.is_empty() {
        return TraceDiffSummary {
            max_abs: 0.0,
            max_abs_idx: 0,
            actual_at_max: 0.0,
            expected_at_max: 0.0,
            l2: 0.0,
            mean_abs: 0.0,
        };
    }

    let mut max_abs = 0.0f32;
    let mut max_abs_idx = 0usize;
    let mut actual_at_max = actual[0];
    let mut expected_at_max = expected[0];
    let mut sum_sq = 0.0f64;
    let mut sum_abs = 0.0f64;

    for (idx, (&a, &e)) in actual.iter().zip(expected.iter()).enumerate() {
        let diff = a - e;
        let abs = diff.abs();
        if abs > max_abs {
            max_abs = abs;
            max_abs_idx = idx;
            actual_at_max = a;
            expected_at_max = e;
        }
        let diff64 = diff as f64;
        sum_sq += diff64 * diff64;
        sum_abs += abs as f64;
    }

    TraceDiffSummary {
        max_abs,
        max_abs_idx,
        actual_at_max,
        expected_at_max,
        l2: sum_sq.sqrt() as f32,
        mean_abs: (sum_abs / actual.len() as f64) as f32,
    }
}

fn download_device_u16(ptr: u64, len: usize) -> Result<Vec<u16>, String> {
    let mut out = vec![0u16; len];
    unsafe {
        let err = cuda_sys::lib().cuMemcpyDtoH_v2(
            out.as_mut_ptr() as *mut std::ffi::c_void,
            ptr,
            len * std::mem::size_of::<u16>(),
        );
        if err != cuda_sys::CUresult::CUDA_SUCCESS {
            return Err(format!("cuMemcpyDtoH u16 failed: {:?}", err));
        }
    }
    Ok(out)
}

fn prefill_state_diag_enabled(layer_idx: usize, start_pos: usize) -> bool {
    if start_pos == 0
        || std::env::var("KRASIS_PREFILL_STATE_DIAG")
            .map(|value| value != "1")
            .unwrap_or(true)
    {
        return false;
    }
    std::env::var("KRASIS_PREFILL_STATE_DIAG_LAYER")
        .ok()
        .and_then(|value| value.trim().parse::<usize>().ok())
        .map_or(true, |target| target == layer_idx)
}

fn emit_bf16_state_summary(label: &str, ptr: u64, len: usize) -> Result<(), String> {
    let bits = download_device_u16(ptr, len)?;
    let mut finite = 0usize;
    let mut nan = 0usize;
    let mut pos_inf = 0usize;
    let mut neg_inf = 0usize;
    let mut min = f32::INFINITY;
    let mut max = f32::NEG_INFINITY;
    for &value_bits in &bits {
        let value = bf16_to_f32(value_bits);
        if value.is_nan() {
            nan += 1;
        } else if value == f32::INFINITY {
            pos_inf += 1;
        } else if value == f32::NEG_INFINITY {
            neg_inf += 1;
        } else {
            finite += 1;
            min = min.min(value);
            max = max.max(value);
        }
    }
    eprintln!(
        "[PREFILL-STATE-DIAG] label={} ptr=0x{:x} elems={} finite={} nan={} pos_inf={} neg_inf={} min={} max={} hash=0x{:016x}",
        label,
        ptr,
        len,
        finite,
        nan,
        pos_inf,
        neg_inf,
        if finite > 0 { min } else { f32::NAN },
        if finite > 0 { max } else { f32::NAN },
        fnv1a_u16_hash(&bits),
    );
    Ok(())
}

fn download_device_u16_at(ptr: u64, index: usize, label: &str) -> Result<u16, String> {
    let byte_offset = index
        .checked_mul(std::mem::size_of::<u16>())
        .ok_or_else(|| format!("{label} u16 byte offset overflow"))?;
    let addr = ptr
        .checked_add(byte_offset as u64)
        .ok_or_else(|| format!("{label} u16 device pointer overflow"))?;
    download_device_u16(addr, 1).map(|values| values[0])
}

fn fnv1a_u16_hash(values: &[u16]) -> u64 {
    let mut hash = 0xcbf29ce484222325u64;
    for &value in values {
        for byte in value.to_le_bytes() {
            hash ^= byte as u64;
            hash = hash.wrapping_mul(0x100000001b3);
        }
    }
    hash
}

fn fnv1a_u8_hash(values: &[u8]) -> u64 {
    let mut hash = 0xcbf29ce484222325u64;
    for &value in values {
        hash ^= value as u64;
        hash = hash.wrapping_mul(0x100000001b3);
    }
    hash
}

fn fnv1a_f32_hash(values: &[f32]) -> u64 {
    let mut hash = 0xcbf29ce484222325u64;
    for &value in values {
        for byte in value.to_bits().to_le_bytes() {
            hash ^= byte as u64;
            hash = hash.wrapping_mul(0x100000001b3);
        }
    }
    hash
}

