fn fnv1a_f32_as_bf16_hash(values: &[f32]) -> u64 {
    let mut hash = 0xcbf29ce484222325u64;
    for &value in values {
        for byte in half::bf16::from_f32(value).to_bits().to_le_bytes() {
            hash ^= byte as u64;
            hash = hash.wrapping_mul(0x100000001b3);
        }
    }
    hash
}

