fn expert_hqq_row_index_json(
    absolute_row: usize,
    target: ExpertHqqExactRowAttributionTarget,
    trace_row: usize,
    ranges: &[ExpertHqqConsumeBoundaryExpertRange],
    gather_src: &[i32],
    gather_weights: &[f32],
) -> serde_json::Value {
    let range = expert_hqq_consume_boundary_expert_for_row(ranges, absolute_row);
    let gather_src_value = gather_src.get(absolute_row).copied();
    serde_json::json!({
        "absolute_row": absolute_row,
        "is_requested_worst_global_row": absolute_row == target.sorted_row,
        "is_selected_trace_row_contributor": gather_src_value == Some(trace_row as i32),
        "expert": range.map(|r| r.expert),
        "block_start": range.map(|r| r.start),
        "block_end": range.map(|r| r.end),
        "is_cached": range.map(|r| r.is_cached),
        "gather_src": gather_src_value,
        "gather_weight": gather_weights.get(absolute_row).copied().map(|v| v as f64),
        "gather_weight_bits": gather_weights.get(absolute_row).copied().map(|v| format!("0x{:08x}", v.to_bits())),
    })
}

fn expert_hqq_exact_row_attribution_capture_json(
    capture: &ExpertHqqExactRowAttributionCapture,
) -> serde_json::Value {
    let hqq_by_row: std::collections::BTreeMap<usize, &ExpertHqqExactRowRuntimeCapture> = capture
        .hqq_rows
        .iter()
        .map(|row| (row.absolute_row, row))
        .collect();
    let rows: Vec<_> = capture
        .bf16_gathered_rows
        .iter()
        .map(|bf16_row| {
            let hqq_row = hqq_by_row.get(&bf16_row.absolute_row).copied();
            let hqq_output_col = hqq_row
                .and_then(|row| row.output_bits.get(capture.target.col).copied());
            let bf16_output_col = bf16_row.output_bits.get(capture.target.col).copied();
            serde_json::json!({
                "row_index": expert_hqq_row_index_json(
                    bf16_row.absolute_row,
                    capture.target,
                    capture.trace_row,
                    &capture.expert_ranges,
                    &capture.gather_src,
                    &capture.gather_weights,
                ),
                "bf16": expert_hqq_exact_row_runtime_capture_json(bf16_row, "bf16_original"),
                "hqq_gpu": hqq_row.map(|row| expert_hqq_exact_row_runtime_capture_json(row, "hqq_gpu")),
                "target_col": {
                    "col": capture.target.col,
                    "bf16_bits": bf16_output_col.map(|bits| format!("0x{:04x}", bits)),
                    "bf16_value": bf16_output_col.map(|bits| bf16_to_f32(bits) as f64),
                    "hqq_bits": hqq_output_col.map(|bits| format!("0x{:04x}", bits)),
                    "hqq_value": hqq_output_col.map(|bits| bf16_to_f32(bits) as f64),
                    "abs_delta": match (bf16_output_col, hqq_output_col) {
                        (Some(bf16_bits), Some(hqq_bits)) => Some((bf16_to_f32(hqq_bits) - bf16_to_f32(bf16_bits)).abs() as f64),
                        _ => None,
                    },
                },
            })
        })
        .collect();
    let selected_row_contributors: Vec<_> = capture
        .rows_to_capture
        .iter()
        .filter(|&&row| capture.gather_src.get(row).copied() == Some(capture.trace_row as i32))
        .map(|&row| {
            expert_hqq_row_index_json(
                row,
                capture.target,
                capture.trace_row,
                &capture.expert_ranges,
                &capture.gather_src,
                &capture.gather_weights,
            )
        })
        .collect();
    serde_json::json!({
        "available": true,
        "scope": "request-scoped guarded expert-HQQ exact-row quantization attribution",
        "existing_trigger": "KRASIS_EXPERT_HQQ_PREFILL_EXACT_ROW_DIAG",
        "production_behavior_changed": true,
        "default_behavior_changed": false,
        "output_consumed_by_production": true,
        "broad_dump": false,
        "layer_idx": capture.target.layer_idx,
        "expert": capture.target.expert_idx,
        "requested_sorted_row": capture.target.sorted_row,
        "requested_col": capture.target.col,
        "trace_row": capture.trace_row,
        "total_active": capture.total_active,
        "hidden_size": capture.hidden_size,
        "w13_rows": capture.w13_rows,
        "intermediate_size": capture.intermediate_size,
        "experts_gated": capture.experts_gated,
        "activation": capture.activation,
        "nbits": capture.nbits,
        "group_size": capture.group_size,
        "block": {
            "expert": capture.block_expert,
            "absolute_row_offset": capture.block_offset,
            "row_count": capture.block_row_count,
            "target_local_row": capture.target_local_row,
        },
        "sync_before_bf16_download_success": capture.sync_before_bf16_download_success,
        "captured_rows": capture.rows_to_capture,
        "captured_row_count": capture.rows_to_capture.len(),
        "selected_trace_row": {
            "trace_row": capture.trace_row,
            "topk_ids": capture.topk_ids_selected_row,
            "topk_weights": capture.topk_weights_selected_row,
            "contributors": selected_row_contributors,
        },
        "rows": rows,
    })
}

fn first_token_margin_projection_dot(row_diff: &[f32], values: &[f32]) -> Result<f64, String> {
    if row_diff.len() != values.len() {
        return Err(format!(
            "first-token margin projection length mismatch: row_diff={} values={}",
            row_diff.len(),
            values.len()
        ));
    }
    Ok(row_diff
        .iter()
        .zip(values.iter())
        .map(|(&a, &b)| (a as f64) * (b as f64))
        .sum())
}

fn first_token_margin_projection_softcap_scalar(value: f64, softcap: f32) -> f64 {
    if softcap <= 0.0 || !softcap.is_finite() || !value.is_finite() {
        value
    } else {
        let softcap64 = softcap as f64;
        (value / softcap64).tanh() * softcap64
    }
}

fn first_token_margin_projection_top_terms_json(
    row_diff: &[f32],
    values: &[f32],
    top_n: usize,
    label: &str,
) -> serde_json::Value {
    let len = row_diff.len().min(values.len());
    let mut top: Vec<(f64, usize, f64, f64, f64)> = Vec::new();
    for idx in 0..len {
        let row_diff_value = row_diff[idx] as f64;
        let value = values[idx] as f64;
        let contribution = row_diff_value * value;
        let abs_contribution = contribution.abs();
        if abs_contribution == 0.0 || top_n == 0 {
            continue;
        }
        if top.len() < top_n {
            top.push((abs_contribution, idx, contribution, row_diff_value, value));
        } else if let Some((min_idx, min_entry)) = top
            .iter()
            .enumerate()
            .min_by(|(_, a), (_, b)| a.0.total_cmp(&b.0))
        {
            if abs_contribution > min_entry.0 {
                top[min_idx] = (abs_contribution, idx, contribution, row_diff_value, value);
            }
        }
    }
    top.sort_by(|a, b| b.0.total_cmp(&a.0));
    let entries: Vec<_> = top
        .into_iter()
        .map(
            |(abs_contribution, index, contribution, row_diff_value, value)| {
                serde_json::json!({
                    "index": index,
                    "abs_contribution": abs_contribution,
                    "contribution": contribution,
                    "row_diff": row_diff_value,
                    "value": value,
                })
            },
        )
        .collect();
    serde_json::json!({
        "available": true,
        "label": label,
        "top_n": top_n,
        "terms": entries,
    })
}

fn first_token_margin_projection_f32_summary_json(
    values: &[f32],
    label: &str,
) -> serde_json::Value {
    let mut value = reference_f32_trace_json(values, label);
    if let Some(obj) = value.as_object_mut() {
        obj.insert(
            "f32_values".to_string(),
            serde_json::json!(values.iter().map(|&v| v as f64).collect::<Vec<_>>()),
        );
    }
    value
}

fn read_only_checkpoint_selected_expert_state_hash(
    capture: &ExpertHqqConsumeBoundaryCapture,
    selected_rows: &[usize],
) -> u64 {
    let mut hash = 0xcbf29ce484222325u64;
    for &row in selected_rows {
        for byte in row.to_le_bytes() {
            hash ^= byte as u64;
            hash = hash.wrapping_mul(0x100000001b3);
        }
        let range = expert_hqq_consume_boundary_expert_for_row(&capture.expert_ranges, row);
        let expert = range.map(|r| r.expert).unwrap_or(usize::MAX);
        for byte in expert.to_le_bytes() {
            hash ^= byte as u64;
            hash = hash.wrapping_mul(0x100000001b3);
        }
        hash ^= range.map(|r| r.is_cached as u8).unwrap_or(255) as u64;
        hash = hash.wrapping_mul(0x100000001b3);
        let weight_bits = capture
            .gather_weights
            .get(row)
            .copied()
            .unwrap_or(f32::NAN)
            .to_bits();
        for byte in weight_bits.to_le_bytes() {
            hash ^= byte as u64;
            hash = hash.wrapping_mul(0x100000001b3);
        }
    }
    hash
}

fn read_only_checkpoint_layer_delta_state_hashes_json(
    capture: &ExpertHqqConsumeBoundaryCapture,
    bf16_cpu_routed: &[f32],
    hqq_cpu_routed: &[f32],
    hqq_expert_out: &[u16],
    label: &str,
) -> Result<serde_json::Value, String> {
    let h = capture.hidden_size;
    let expected_len = capture.total_active.saturating_mul(h);
    if capture.bf16_expert_out.len() != expected_len || hqq_expert_out.len() != expected_len {
        return Err(format!(
            "read-only checkpoint expert_out length mismatch: bf16={} hqq={} expected={}",
            capture.bf16_expert_out.len(),
            hqq_expert_out.len(),
            expected_len
        ));
    }
    if bf16_cpu_routed.len() != h || hqq_cpu_routed.len() != h {
        return Err(format!(
            "read-only checkpoint routed length mismatch: bf16={} hqq={} hidden={}",
            bf16_cpu_routed.len(),
            hqq_cpu_routed.len(),
            h
        ));
    }
    if capture.gather_src.len() != capture.total_active
        || capture.gather_weights.len() != capture.total_active
    {
        return Err(format!(
            "read-only checkpoint gather length mismatch: src={} weights={} total_active={}",
            capture.gather_src.len(),
            capture.gather_weights.len(),
            capture.total_active
        ));
    }

    let selected_rows = capture
        .gather_src
        .iter()
        .enumerate()
        .filter_map(|(row, &src)| (src == capture.trace_row as i32).then_some(row))
        .collect::<Vec<_>>();
    let mut bf16_selected_output = Vec::with_capacity(selected_rows.len().saturating_mul(h));
    let mut hqq_selected_output = Vec::with_capacity(selected_rows.len().saturating_mul(h));
    let mut selected_rows_json = Vec::with_capacity(selected_rows.len());
    for &row in &selected_rows {
        let start = row.saturating_mul(h);
        let end = start + h;
        bf16_selected_output.extend_from_slice(&capture.bf16_expert_out[start..end]);
        hqq_selected_output.extend_from_slice(&hqq_expert_out[start..end]);
        let range = expert_hqq_consume_boundary_expert_for_row(&capture.expert_ranges, row);
        let topk_pos = range.and_then(|range| {
            capture
                .topk_ids_selected_row
                .iter()
                .position(|&expert| expert == range.expert as i32)
        });
        selected_rows_json.push(serde_json::json!({
            "row": row,
            "expert": range.map(|r| r.expert),
            "is_cached": range.map(|r| r.is_cached),
            "gather_weight_bits": capture.gather_weights.get(row).copied().map(|v| format!("0x{:08x}", v.to_bits())),
            "topk_pos": topk_pos,
        }));
    }

    Ok(serde_json::json!({
        "available": true,
        "schema": "krasis_read_only_checkpoint_state_hashes_v1",
        "label": label,
        "scope": "request-scoped diagnostic read-only checkpoint",
        "existing_trigger": "KRASIS_READ_ONLY_CHECKPOINT_DIAG",
        "production_behavior_changed": false,
        "layer_idx": capture.layer_idx,
        "trace_row": capture.trace_row,
        "total_active": capture.total_active,
        "hidden_size": h,
        "route_topk_gather_hashes": {
            "gather_src": read_only_checkpoint_i32_hash_json("gather_src_all_active_rows", &capture.gather_src),
            "gather_weights": read_only_checkpoint_f32_hash_json("gather_weights_all_active_rows", &capture.gather_weights),
            "topk_ids_selected_row": read_only_checkpoint_i32_hash_json("topk_ids_selected_row", &capture.topk_ids_selected_row),
            "topk_weights_selected_row": read_only_checkpoint_f32_hash_json("topk_weights_selected_row", &capture.topk_weights_selected_row),
        },
        "selected_expert_output_state_hashes": {
            "selected_row_count": selected_rows.len(),
            "selected_rows": selected_rows_json,
            "selected_expert_state_hash_fnv1a64": format!("0x{:016x}", read_only_checkpoint_selected_expert_state_hash(capture, &selected_rows)),
            "bf16_selected_expert_output_rows": read_only_checkpoint_bf16_hash_json(
                "bf16_selected_expert_output_rows",
                &bf16_selected_output,
                Some(h),
            ),
            "hqq_selected_expert_output_rows": read_only_checkpoint_bf16_hash_json(
                "hqq_selected_expert_output_rows",
                &hqq_selected_output,
                Some(h),
            ),
            "bf16_all_expert_output_rows": read_only_checkpoint_bf16_hash_json(
                "bf16_all_expert_output_rows",
                &capture.bf16_expert_out,
                Some(h),
            ),
            "hqq_all_expert_output_rows": read_only_checkpoint_bf16_hash_json(
                "hqq_all_expert_output_rows",
                hqq_expert_out,
                Some(h),
            ),
        },
        "routed_output_state_hashes": {
            "bf16_cpu_routed_selected_row": read_only_checkpoint_f32_hash_json(
                "bf16_cpu_routed_selected_row",
                bf16_cpu_routed,
            ),
            "hqq_cpu_routed_selected_row": read_only_checkpoint_f32_hash_json(
                "hqq_cpu_routed_selected_row",
                hqq_cpu_routed,
            ),
        },
    }))
}

fn first_token_margin_projection_layer_delta_from_consume_capture(
    capture: &ExpertHqqConsumeBoundaryCapture,
    bf16_cpu_routed: &[f32],
    hqq_cpu_routed: &[f32],
    hqq_expert_out: &[u16],
) -> Result<FirstTokenMarginProjectionLayerDelta, String> {
    let h = capture.hidden_size;
    if bf16_cpu_routed.len() != h || hqq_cpu_routed.len() != h {
        return Err(format!(
            "first-token margin projection routed delta length mismatch: bf16={} hqq={} hidden={}",
            bf16_cpu_routed.len(),
            hqq_cpu_routed.len(),
            h
        ));
    }
    if capture.bf16_expert_out.len() != hqq_expert_out.len()
        || capture.bf16_expert_out.len() != capture.gather_src.len().saturating_mul(h)
    {
        return Err(format!(
            "first-token margin projection expert output length mismatch: bf16={} hqq={} gather={} hidden={}",
            capture.bf16_expert_out.len(),
            hqq_expert_out.len(),
            capture.gather_src.len(),
            h
        ));
    }
    let routed_delta = hqq_cpu_routed
        .iter()
        .zip(bf16_cpu_routed.iter())
        .map(|(&hqq, &bf16)| hqq - bf16)
        .collect::<Vec<_>>();
    let mut expert_contributions = Vec::new();
    for (row, &src) in capture.gather_src.iter().enumerate() {
        if src != capture.trace_row as i32 {
            continue;
        }
        let weight = capture.gather_weights.get(row).copied().ok_or_else(|| {
            format!("first-token margin projection missing gather weight for row {row}")
        })?;
        let range = expert_hqq_consume_boundary_expert_for_row(&capture.expert_ranges, row);
        let start = row * h;
        let end = start + h;
        let delta = hqq_expert_out[start..end]
            .iter()
            .zip(capture.bf16_expert_out[start..end].iter())
            .map(|(&hqq_bits, &bf16_bits)| {
                (bf16_to_f32(hqq_bits) - bf16_to_f32(bf16_bits)) * weight
            })
            .collect::<Vec<_>>();
        expert_contributions.push(FirstTokenMarginProjectionExpertDelta {
            row,
            expert: range.map(|range| range.expert),
            is_cached: range.map(|range| range.is_cached),
            gather_weight: weight,
            delta,
        });
    }
    Ok(FirstTokenMarginProjectionLayerDelta {
        layer_idx: capture.layer_idx,
        trace_row: capture.trace_row,
        hidden_size: h,
        total_active: capture.total_active,
        routed_delta,
        expert_contributions,
    })
}

fn first_token_margin_projection_trace_json_from_rows(
    target: FirstTokenMarginProjectionTarget,
    hidden_bits: &[u16],
    token_a_row_bits: &[u16],
    token_b_row_bits: &[u16],
    logits_after_softcap: &[f32],
    selected_token: usize,
    final_logit_softcap: f32,
    layer_deltas: &[FirstTokenMarginProjectionLayerDelta],
) -> Result<serde_json::Value, String> {
    let h = hidden_bits.len();
    if token_a_row_bits.len() != h || token_b_row_bits.len() != h {
        return Err(format!(
            "first-token margin projection LM-head row length mismatch: hidden={} token_a_row={} token_b_row={}",
            h,
            token_a_row_bits.len(),
            token_b_row_bits.len()
        ));
    }
    let hidden = hidden_bits
        .iter()
        .map(|&bits| bf16_to_f32(bits))
        .collect::<Vec<_>>();
    let token_a_row = token_a_row_bits
        .iter()
        .map(|&bits| bf16_to_f32(bits))
        .collect::<Vec<_>>();
    let token_b_row = token_b_row_bits
        .iter()
        .map(|&bits| bf16_to_f32(bits))
        .collect::<Vec<_>>();
    let row_diff = token_a_row
        .iter()
        .zip(token_b_row.iter())
        .map(|(&a, &b)| a - b)
        .collect::<Vec<_>>();
    let raw_logit_a = first_token_margin_projection_dot(&token_a_row, &hidden)?;
    let raw_logit_b = first_token_margin_projection_dot(&token_b_row, &hidden)?;
    let raw_margin = raw_logit_a - raw_logit_b;
    let softcapped_logit_a =
        first_token_margin_projection_softcap_scalar(raw_logit_a, final_logit_softcap);
    let softcapped_logit_b =
        first_token_margin_projection_softcap_scalar(raw_logit_b, final_logit_softcap);
    let token_a_after_softcap = logits_after_softcap
        .get(target.token_a)
        .copied()
        .map(|v| v as f64);
    let token_b_after_softcap = logits_after_softcap
        .get(target.token_b)
        .copied()
        .map(|v| v as f64);
    let downloaded_margin_after_softcap = token_a_after_softcap
        .zip(token_b_after_softcap)
        .map(|(a, b)| a - b);

    let mut layer_projection_rows = Vec::new();
    for layer in layer_deltas {
        if layer.hidden_size != h || layer.routed_delta.len() != h {
            return Err(format!(
                "first-token margin projection layer {} hidden mismatch: layer_hidden={} routed_delta={} expected={}",
                layer.layer_idx,
                layer.hidden_size,
                layer.routed_delta.len(),
                h
            ));
        }
        let routed_projection = first_token_margin_projection_dot(&row_diff, &layer.routed_delta)?;
        let mut expert_rows = Vec::new();
        for expert_delta in &layer.expert_contributions {
            if expert_delta.delta.len() != h {
                return Err(format!(
                    "first-token margin projection layer {} expert row {} hidden mismatch: delta={} expected={}",
                    layer.layer_idx,
                    expert_delta.row,
                    expert_delta.delta.len(),
                    h
                ));
            }
            let projection = first_token_margin_projection_dot(&row_diff, &expert_delta.delta)?;
            expert_rows.push(serde_json::json!({
                "row": expert_delta.row,
                "expert": expert_delta.expert,
                "is_cached": expert_delta.is_cached,
                "gather_weight": expert_delta.gather_weight as f64,
                "raw_margin_projection": projection,
                "top_terms": first_token_margin_projection_top_terms_json(
                    &row_diff,
                    &expert_delta.delta,
                    target.top_n,
                    "selected_row_expert_delta_projected_terms",
                ),
            }));
        }
        expert_rows.sort_by(|a, b| {
            let a_proj = a
                .get("raw_margin_projection")
                .and_then(|v| v.as_f64())
                .unwrap_or(0.0)
                .abs();
            let b_proj = b
                .get("raw_margin_projection")
                .and_then(|v| v.as_f64())
                .unwrap_or(0.0)
                .abs();
            b_proj.total_cmp(&a_proj)
        });
        layer_projection_rows.push(serde_json::json!({
            "layer_idx": layer.layer_idx,
            "trace_row": layer.trace_row,
            "hidden_size": layer.hidden_size,
            "total_active": layer.total_active,
            "raw_margin_projection": routed_projection,
            "routed_delta_summary": reference_f32_trace_json(
                &layer.routed_delta,
                "hqq_minus_bf16_selected_row_routed_delta",
            ),
            "top_terms": first_token_margin_projection_top_terms_json(
                &row_diff,
                &layer.routed_delta,
                target.top_n,
                "selected_row_routed_delta_projected_terms",
            ),
            "expert_contribution_count": layer.expert_contributions.len(),
            "expert_contributions": expert_rows,
        }));
    }
    layer_projection_rows.sort_by(|a, b| {
        let a_proj = a
            .get("raw_margin_projection")
            .and_then(|v| v.as_f64())
            .unwrap_or(0.0)
            .abs();
        let b_proj = b
            .get("raw_margin_projection")
            .and_then(|v| v.as_f64())
            .unwrap_or(0.0)
            .abs();
        b_proj.total_cmp(&a_proj)
    });

    Ok(serde_json::json!({
        "available": true,
        "scope": "request-scoped first-token margin projection diagnostic",
        "existing_trigger": "KRASIS_FIRST_TOKEN_MARGIN_PROJECTION_DIAG",
        "production_behavior_changed": false,
        "default_behavior_changed": false,
        "target": {
            "token_a": target.token_a,
            "token_b": target.token_b,
            "margin_definition": "token_a_minus_token_b",
            "top_n": target.top_n,
        },
        "selected_token_id_after_suppression": selected_token,
        "hidden_size": h,
        "final_logit_softcap": final_logit_softcap as f64,
        "selected_hidden_before_lm_head_full": {
            "dtype": "bf16",
            "value_count": hidden_bits.len(),
            "hash_fnv1a64_bf16_bits": format!("0x{:016x}", fnv1a_u16_hash(hidden_bits)),
            "bf16_bits_u16": hidden_bits.iter().map(|&bits| bits as u64).collect::<Vec<_>>(),
        },
        "target_lm_head_rows": {
            "dtype": "bf16",
            "token_a_hash_fnv1a64_bf16_bits": format!("0x{:016x}", fnv1a_u16_hash(token_a_row_bits)),
            "token_b_hash_fnv1a64_bf16_bits": format!("0x{:016x}", fnv1a_u16_hash(token_b_row_bits)),
        },
        "target_lm_head_row_difference": first_token_margin_projection_f32_summary_json(
            &row_diff,
            "lm_head_row_token_a_minus_token_b",
        ),
        "final_hidden_projection": {
            "raw_logit_a_from_projection": raw_logit_a,
            "raw_logit_b_from_projection": raw_logit_b,
            "raw_margin_from_projection": raw_margin,
            "softcapped_logit_a_from_projection": softcapped_logit_a,
            "softcapped_logit_b_from_projection": softcapped_logit_b,
            "softcapped_margin_from_projection": softcapped_logit_a - softcapped_logit_b,
            "downloaded_token_a_logit_after_softcap": token_a_after_softcap,
            "downloaded_token_b_logit_after_softcap": token_b_after_softcap,
            "downloaded_margin_after_softcap": downloaded_margin_after_softcap,
            "top_terms": first_token_margin_projection_top_terms_json(
                &row_diff,
                &hidden,
                target.top_n,
                "final_hidden_margin_projection_terms",
            ),
        },
        "layer_delta_projections": {
            "available": !layer_projection_rows.is_empty(),
            "source": "expert-HQQ consume-boundary selected-row BF16-vs-HQQ routed deltas",
            "limitation": "Layer rows project immediate selected-row routed deltas through the final LM-head row difference; they are diagnostic contribution summaries, not a full nonlinear downstream causal decomposition.",
            "captured_layer_count": layer_projection_rows.len(),
            "rows": layer_projection_rows,
        },
    }))
}

fn expert_hqq_consume_boundary_f32_delta_summary(
    actual: &[f32],
    expected: &[f32],
    top_n: usize,
    label: &str,
) -> serde_json::Value {
    let len = actual.len().min(expected.len());
    let mut sum_abs = 0.0f64;
    let mut sum_sq = 0.0f64;
    let mut max_abs = 0.0f32;
    let mut max_abs_index = 0usize;
    let mut top: Vec<(f32, usize)> = Vec::new();
    for idx in 0..len {
        let abs_delta = (actual[idx] - expected[idx]).abs();
        let delta64 = abs_delta as f64;
        sum_abs += delta64;
        sum_sq += delta64 * delta64;
        if abs_delta > max_abs {
            max_abs = abs_delta;
            max_abs_index = idx;
        }
        if abs_delta > 0.0 && top_n > 0 {
            if top.len() < top_n {
                top.push((abs_delta, idx));
            } else if let Some((min_idx, _)) = top
                .iter()
                .enumerate()
                .min_by(|(_, a), (_, b)| a.0.total_cmp(&b.0))
            {
                if abs_delta > top[min_idx].0 {
                    top[min_idx] = (abs_delta, idx);
                }
            }
        }
    }
    top.sort_by(|a, b| b.0.total_cmp(&a.0));
    let top_deltas: Vec<_> = top
        .into_iter()
        .map(|(abs_delta, idx)| {
            serde_json::json!({
                "abs_delta": abs_delta as f64,
                "index": idx,
                "actual": actual[idx] as f64,
                "expected": expected[idx] as f64,
                "actual_bits": format!("0x{:08x}", actual[idx].to_bits()),
                "expected_bits": format!("0x{:08x}", expected[idx].to_bits()),
            })
        })
        .collect();
    serde_json::json!({
        "available": true,
        "label": label,
        "dtype": "f32",
        "compared_len": len,
        "actual_len": actual.len(),
        "expected_len": expected.len(),
        "sum_abs": sum_abs,
        "mean_abs": if len == 0 { 0.0 } else { sum_abs / len as f64 },
        "max_abs": max_abs as f64,
        "max_abs_index": max_abs_index,
        "actual_at_max": actual.get(max_abs_index).copied().map(|v| v as f64),
        "expected_at_max": expected.get(max_abs_index).copied().map(|v| v as f64),
        "l2": sum_sq.sqrt(),
        "top_n": top_n,
        "top_deltas": top_deltas,
    })
}

fn reference_lm_head_logit_trace_json(
    logits: &[f32],
    vocab_size: usize,
    selected_token: usize,
    top_n: usize,
) -> serde_json::Value {
    let vocab_size = vocab_size.min(logits.len());
    if vocab_size == 0 {
        return serde_json::json!({
            "available": false,
            "reason": "empty_logits",
        });
    }

    let mut max_logit = f32::NEG_INFINITY;
    let mut max_token = 0usize;
    for (idx, &value) in logits[..vocab_size].iter().enumerate() {
        if !value.is_nan() && value > max_logit {
            max_logit = value;
            max_token = idx;
        }
    }
    let sum_exp: f64 = logits[..vocab_size]
        .iter()
        .filter(|v| !v.is_nan())
        .map(|&x| ((x - max_logit) as f64).exp())
        .sum();
    let logsumexp = max_logit as f64 + sum_exp.ln();
    let selected_raw = logits.get(selected_token).copied().unwrap_or(f32::NAN);

    let mut top_logits: Vec<(usize, f32)> = Vec::with_capacity(top_n);
    for (idx, &value) in logits[..vocab_size].iter().enumerate() {
        if value.is_nan() {
            continue;
        }
        if top_logits.len() < top_n {
            top_logits.push((idx, value));
            if top_logits.len() == top_n {
                top_logits
                    .sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
            }
        } else if top_n > 0 && value > top_logits[top_n - 1].1 {
            top_logits[top_n - 1] = (idx, value);
            top_logits.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
        }
    }
    top_logits.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));

    let top_entries: Vec<serde_json::Value> = top_logits
        .iter()
        .enumerate()
        .map(|(rank, &(token_id, raw_logit))| {
            serde_json::json!({
                "rank": rank + 1,
                "token_id": token_id,
                "raw_logit": raw_logit as f64,
                "logprob": raw_logit as f64 - logsumexp,
            })
        })
        .collect();

    serde_json::json!({
        "available": true,
        "source": "prefill_engine.scratch.d_logits_after_lm_head_before_suppression",
        "dtype": "f32",
        "device_before_download": "cuda",
        "vocab_size": vocab_size,
        "selected_token_id": selected_token,
        "selected_raw_logit": selected_raw as f64,
        "selected_logprob_from_raw": selected_raw as f64 - logsumexp,
        "max_logit": max_logit as f64,
        "max_token_id": max_token,
        "sum_exp_shifted": sum_exp,
        "logsumexp": logsumexp,
        "top_logits_before_logprob": top_entries,
    })
}

fn download_device_u8(ptr: u64, len: usize) -> Result<Vec<u8>, String> {
    let mut out = vec![0u8; len];
    unsafe {
        let err =
            cuda_sys::lib().cuMemcpyDtoH_v2(out.as_mut_ptr() as *mut std::ffi::c_void, ptr, len);
        if err != cuda_sys::CUresult::CUDA_SUCCESS {
            return Err(format!("cuMemcpyDtoH u8 failed: {:?}", err));
        }
    }
    Ok(out)
}

fn download_device_u32(ptr: u64, len: usize) -> Result<Vec<u32>, String> {
    let mut out = vec![0u32; len];
    unsafe {
        let err = cuda_sys::lib().cuMemcpyDtoH_v2(
            out.as_mut_ptr() as *mut std::ffi::c_void,
            ptr,
            len * std::mem::size_of::<u32>(),
        );
        if err != cuda_sys::CUresult::CUDA_SUCCESS {
            return Err(format!("cuMemcpyDtoH u32 failed: {:?}", err));
        }
    }
    Ok(out)
}

