fn download_device_f32_at(ptr: u64, index: usize, label: &str) -> Result<f32, String> {
    let byte_offset = index
        .checked_mul(std::mem::size_of::<f32>())
        .ok_or_else(|| format!("{label} f32 byte offset overflow"))?;
    let addr = ptr
        .checked_add(byte_offset as u64)
        .ok_or_else(|| format!("{label} f32 device pointer overflow"))?;
    download_device_f32(addr, 1).map(|values| values[0])
}

fn upload_device_i32(ptr: u64, values: &[i32]) -> Result<(), String> {
    if values.is_empty() {
        return Ok(());
    }
    unsafe {
        let err = cuda_sys::lib().cuMemcpyHtoD_v2(
            ptr,
            values.as_ptr() as *const std::ffi::c_void,
            std::mem::size_of_val(values),
        );
        if err != cuda_sys::CUresult::CUDA_SUCCESS {
            return Err(format!("cuMemcpyHtoD i32 failed: {:?}", err));
        }
    }
    Ok(())
}

