fn ranges_overlap(a_ptr: u64, a_bytes: usize, b_ptr: u64, b_bytes: usize) -> bool {
    if a_ptr == 0 || b_ptr == 0 || a_bytes == 0 || b_bytes == 0 {
        return false;
    }
    let a_end = a_ptr.saturating_add(a_bytes as u64);
    let b_end = b_ptr.saturating_add(b_bytes as u64);
    a_ptr < b_end && b_ptr < a_end
}

fn top_abs_indices(values: &[f32], take: usize) -> Vec<usize> {
    let mut ranked = values
        .iter()
        .enumerate()
        .map(|(idx, &value)| (idx, value.abs()))
        .collect::<Vec<_>>();
    ranked.sort_by(|a, b| b.1.total_cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    ranked
        .into_iter()
        .take(take.min(values.len()))
        .map(|(idx, _)| idx)
        .collect()
}

struct DiagF32Summary {
    finite: usize,
    nan: usize,
    pos_inf: usize,
    neg_inf: usize,
    min: String,
    max: String,
    hash: String,
    sample: String,
}

struct DiagBf16Summary {
    finite: usize,
    nan: usize,
    pos_inf: usize,
    neg_inf: usize,
    min: String,
    max: String,
    hash: String,
    sample_bits: String,
    sample_values: String,
}

struct InputRmsnormDiagPre {
    sample_rows: usize,
    hidden_pre_bits: Vec<u16>,
    residual_pre_bits: Vec<u16>,
    weight_bits: Vec<u16>,
}

fn format_diag_f32(value: f32) -> String {
    if value.is_nan() {
        "NaN".to_string()
    } else if value == f32::INFINITY {
        "Inf".to_string()
    } else if value == f32::NEG_INFINITY {
        "-Inf".to_string()
    } else {
        format!("{:.9e}", value)
    }
}

fn first_nonfinite_bf16(values: &[u16]) -> (String, String, String) {
    for (idx, &bits) in values.iter().enumerate() {
        let value = bf16_to_f32(bits);
        if !value.is_finite() {
            return (
                idx.to_string(),
                format!("{:04x}", bits),
                format_diag_f32(value),
            );
        }
    }
    ("none".to_string(), "none".to_string(), "none".to_string())
}

fn first_nonfinite_f32(values: &[f32]) -> (String, String, String) {
    for (idx, &value) in values.iter().enumerate() {
        if !value.is_finite() {
            return (
                idx.to_string(),
                format!("{:08x}", value.to_bits()),
                format_diag_f32(value),
            );
        }
    }
    ("none".to_string(), "none".to_string(), "none".to_string())
}

fn summarize_f32_diag(values: &[f32], sample_len: usize) -> DiagF32Summary {
    let mut finite = 0usize;
    let mut nan = 0usize;
    let mut pos_inf = 0usize;
    let mut neg_inf = 0usize;
    let mut min_value = f32::INFINITY;
    let mut max_value = f32::NEG_INFINITY;
    for &value in values {
        if value.is_nan() {
            nan += 1;
        } else if value == f32::INFINITY {
            pos_inf += 1;
        } else if value == f32::NEG_INFINITY {
            neg_inf += 1;
        } else {
            finite += 1;
            min_value = min_value.min(value);
            max_value = max_value.max(value);
        }
    }
    let sample_n = sample_len.min(values.len());
    DiagF32Summary {
        finite,
        nan,
        pos_inf,
        neg_inf,
        min: if finite > 0 {
            format!("{:.6}", min_value)
        } else {
            "NaN".to_string()
        },
        max: if finite > 0 {
            format!("{:.6}", max_value)
        } else {
            "NaN".to_string()
        },
        hash: format!("0x{:016x}", fnv1a_f32_hash(values)),
        sample: format_f32_sample(&values[..sample_n]),
    }
}

fn summarize_bf16_diag(values: &[u16], sample_len: usize) -> DiagBf16Summary {
    let mut finite = 0usize;
    let mut nan = 0usize;
    let mut pos_inf = 0usize;
    let mut neg_inf = 0usize;
    let mut min_value = f32::INFINITY;
    let mut max_value = f32::NEG_INFINITY;
    for &bits in values {
        let value = bf16_to_f32(bits);
        if value.is_nan() {
            nan += 1;
        } else if value == f32::INFINITY {
            pos_inf += 1;
        } else if value == f32::NEG_INFINITY {
            neg_inf += 1;
        } else {
            finite += 1;
            min_value = min_value.min(value);
            max_value = max_value.max(value);
        }
    }
    let sample_n = sample_len.min(values.len());
    let sample_values: Vec<f32> = values[..sample_n]
        .iter()
        .map(|&bits| bf16_to_f32(bits))
        .collect();
    DiagBf16Summary {
        finite,
        nan,
        pos_inf,
        neg_inf,
        min: if finite > 0 {
            format!("{:.6}", min_value)
        } else {
            "NaN".to_string()
        },
        max: if finite > 0 {
            format!("{:.6}", max_value)
        } else {
            "NaN".to_string()
        },
        hash: format!("0x{:016x}", fnv1a_u16_hash(values)),
        sample_bits: format_u16_hex_sample(&values[..sample_n]),
        sample_values: format_f32_sample(&sample_values),
    }
}

fn dequantize_marlin_weight_cpu(weight: &MarlinWeight) -> Result<Vec<f32>, String> {
    let packed_len = match weight.num_bits {
        4 => (weight.k / 16) * (weight.n * 2),
        8 => (weight.k / 16) * (weight.n * 4),
        other => return Err(format!("unsupported Marlin bit width: {}", other)),
    };
    let scales_len = weight.num_groups * weight.n;
    let packed = download_device_u32(weight.packed, packed_len)?;
    let scales = download_device_u16(weight.scales, scales_len)?;
    let repacked = MarlinRepacked {
        packed,
        scales,
        k: weight.k,
        n: weight.n,
        group_size: weight.group_size,
    };
    match weight.num_bits {
        4 => Ok(dequantize_marlin(&repacked)),
        8 => Ok(dequantize_marlin_int8(&repacked)),
        _ => unreachable!(),
    }
}

fn download_marlin_scales_cpu(weight: &MarlinWeight) -> Result<Vec<f32>, String> {
    match weight.num_bits {
        4 | 8 => {}
        other => {
            return Err(format!(
                "unsupported Marlin bit width for scales: {}",
                other
            ))
        }
    }
    let num_groups_k = weight.num_groups;
    let scales_len = num_groups_k * weight.n;
    let scales = download_device_u16(weight.scales, scales_len)?;
    let (scale_perm, scale_perm_single) = generate_scale_perms();
    let is_grouped = weight.group_size < weight.k;
    let sperm: &[usize] = if is_grouped {
        &scale_perm
    } else {
        &scale_perm_single
    };
    let perm_len = sperm.len();
    let mut scales_transposed = vec![0u16; scales_len];
    for chunk in 0..(scales_len / perm_len) {
        let base = chunk * perm_len;
        for i in 0..perm_len {
            scales_transposed[base + sperm[i]] = scales[base + i];
        }
    }
    Ok(scales_transposed.into_iter().map(bf16_to_f32).collect())
}

fn gather_weight_row_slice(
    weight_rows: &[f32],
    rows: usize,
    cols: usize,
    out_idx: usize,
    input_idx: &[usize],
) -> Result<Vec<f32>, String> {
    if out_idx >= rows {
        return Err(format!(
            "weight row index out of range: out_idx={} rows={}",
            out_idx, rows
        ));
    }
    let row = &weight_rows[out_idx * cols..(out_idx + 1) * cols];
    let mut out = Vec::with_capacity(input_idx.len());
    for &idx in input_idx {
        if idx >= cols {
            return Err(format!(
                "weight input index out of range: idx={} cols={}",
                idx, cols
            ));
        }
        out.push(row[idx]);
    }
    Ok(out)
}

fn gather_group_scale_slice(
    scales_by_group: &[f32],
    rows: usize,
    group_count: usize,
    out_idx: usize,
    input_idx: &[usize],
    group_size: usize,
) -> Result<Vec<f32>, String> {
    if out_idx >= rows {
        return Err(format!(
            "group scale row index out of range: out_idx={} rows={}",
            out_idx, rows
        ));
    }
    let expected = group_count * rows;
    if scales_by_group.len() != expected {
        return Err(format!(
            "group scale length mismatch: got {} expected {}",
            scales_by_group.len(),
            expected
        ));
    }
    let mut out = Vec::with_capacity(input_idx.len());
    for &idx in input_idx {
        let group_idx = idx / group_size;
        if group_idx >= group_count {
            return Err(format!(
                "group scale group index out of range: idx={} group_idx={} group_count={}",
                idx, group_idx, group_count
            ));
        }
        out.push(scales_by_group[group_idx * rows + out_idx]);
    }
    Ok(out)
}

fn scalar_type_label(st: &ScalarType) -> &'static str {
    if st.mantissa == ScalarType::U4.mantissa && st.bias == ScalarType::U4.bias {
        "U4"
    } else if st.mantissa == ScalarType::U4B8.mantissa && st.bias == ScalarType::U4B8.bias {
        "U4B8"
    } else if st.mantissa == ScalarType::U8B128.mantissa && st.bias == ScalarType::U8B128.bias {
        "U8B128"
    } else if st.mantissa == ScalarType::U8.mantissa && st.bias == ScalarType::U8.bias {
        "U8"
    } else {
        "UNKNOWN"
    }
}

fn is_exact_frozen_trace_sid(sid: usize) -> bool {
    sid == 2315 || sid == 2319
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ReferenceRouterVariant {
    RawBaseline,
    CorrectedHfUnsorted,
    CorrectedSorted,
    CorrectedSetRawSlotWeights,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ReferenceRouterForcedSlotOrder {
    pub layer_idx: usize,
    pub row_idx: usize,
    pub expert_ids: Vec<usize>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ReferenceMamba2GatedNormReplayMode {
    SqrtApproxDivRn,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ReferenceMamba2GatedNormReplay {
    pub layer_idx: usize,
    pub row_idx: usize,
    pub mode: ReferenceMamba2GatedNormReplayMode,
}

impl ReferenceRouterVariant {
    pub fn from_request_str(value: &str) -> Option<Self> {
        match value.trim().to_ascii_lowercase().as_str() {
            "raw" | "raw_sigmoid" | "restored_raw_baseline" => Some(Self::RawBaseline),
            "corrected_hf_unsorted" | "hf_unsorted_corrected" => Some(Self::CorrectedHfUnsorted),
            "corrected_sorted" | "sorted_corrected" => Some(Self::CorrectedSorted),
            "corrected_set_raw_slot_weights" | "corrected_raw_slot_weights" => {
                Some(Self::CorrectedSetRawSlotWeights)
            }
            _ => None,
        }
    }

    pub fn as_str(self) -> &'static str {
        match self {
            Self::RawBaseline => "raw",
            Self::CorrectedHfUnsorted => "corrected_hf_unsorted",
            Self::CorrectedSorted => "corrected_sorted",
            Self::CorrectedSetRawSlotWeights => "corrected_set_raw_slot_weights",
        }
    }

    fn is_override(self) -> bool {
        !matches!(self, Self::RawBaseline)
    }
}

impl ReferenceMamba2GatedNormReplayMode {
    pub fn from_request_str(value: &str) -> Option<Self> {
        match value.trim().to_ascii_lowercase().as_str() {
            "sqrt_approx_div_rn" | "sqrt.approx.ftz.f32+div.rn.f32" | "sqrt_approx_ftz_div_rn" => {
                Some(Self::SqrtApproxDivRn)
            }
            _ => None,
        }
    }

    pub fn as_str(self) -> &'static str {
        match self {
            Self::SqrtApproxDivRn => "sqrt_approx_div_rn",
        }
    }
}

fn compute_router_topk_cpu_reference(
    logits: &[f32],
    topk: usize,
    scoring_func: u8,
    gate_bias: Option<&[f32]>,
    e_score_corr: Option<&[f32]>,
) -> Result<(Vec<f32>, Vec<i32>), String> {
    if topk == 0 {
        return Ok((Vec::new(), Vec::new()));
    }
    let mut scores = logits.to_vec();
    if let Some(bias) = gate_bias {
        if bias.len() != scores.len() {
            return Err(format!(
                "router gate bias length mismatch: got {} expected {}",
                bias.len(),
                scores.len(),
            ));
        }
        for (score, &b) in scores.iter_mut().zip(bias.iter()) {
            *score += b;
        }
    }
    if let Some(corr) = e_score_corr {
        if corr.len() != scores.len() {
            return Err(format!(
                "router e_score correction length mismatch: got {} expected {}",
                corr.len(),
                scores.len(),
            ));
        }
    }

    match scoring_func {
        0 => {
            let max_val = scores.iter().copied().fold(f32::NEG_INFINITY, f32::max);
            let mut exp_scores = scores
                .iter()
                .map(|&v| (v - max_val).exp())
                .collect::<Vec<_>>();
            let sum = exp_scores.iter().copied().sum::<f32>();
            let inv_sum = if sum > 0.0 { 1.0 / sum } else { 0.0 };
            for v in &mut exp_scores {
                *v *= inv_sum;
            }
            let mut selection_scores = exp_scores.clone();
            if let Some(corr) = e_score_corr {
                for (score, &c) in selection_scores.iter_mut().zip(corr.iter()) {
                    *score += c;
                }
            }
            let mut ranked = selection_scores
                .iter()
                .copied()
                .enumerate()
                .collect::<Vec<_>>();
            ranked.sort_by(|a, b| b.1.total_cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
            let take = topk.min(ranked.len());
            let mut out_w = Vec::with_capacity(take);
            let mut out_i = Vec::with_capacity(take);
            let wsum = ranked
                .iter()
                .take(take)
                .map(|(idx, _)| exp_scores[*idx])
                .sum::<f32>();
            let inv_wsum = if wsum > 0.0 { 1.0 / wsum } else { 0.0 };
            for (idx, _) in ranked.into_iter().take(take) {
                out_w.push(exp_scores[idx] * inv_wsum);
                out_i.push(idx as i32);
            }
            Ok((out_w, out_i))
        }
        1 => {
            let sigmoid_scores = scores
                .iter()
                .copied()
                .map(|v| 1.0 / (1.0 + (-v).exp()))
                .collect::<Vec<_>>();
            let mut selection_scores = sigmoid_scores.clone();
            if let Some(corr) = e_score_corr {
                for (score, &c) in selection_scores.iter_mut().zip(corr.iter()) {
                    *score += c;
                }
            }
            let mut ranked = selection_scores
                .iter()
                .copied()
                .enumerate()
                .collect::<Vec<_>>();
            ranked.sort_by(|a, b| b.1.total_cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
            let take = topk.min(ranked.len());
            let mut out_w = Vec::with_capacity(take);
            let mut out_i = Vec::with_capacity(take);
            for (idx, _) in ranked.into_iter().take(take) {
                out_w.push(sigmoid_scores[idx]);
                out_i.push(idx as i32);
            }
            Ok((out_w, out_i))
        }
        2 => {
            let raw_scores = scores
                .iter()
                .copied()
                .map(|v| (v.max(0.0) + (-v.abs()).exp().ln_1p()).sqrt())
                .collect::<Vec<_>>();
            let mut selection_scores = raw_scores.clone();
            if let Some(corr) = e_score_corr {
                for (score, &c) in selection_scores.iter_mut().zip(corr.iter()) {
                    *score += c;
                }
            }
            let mut ranked = selection_scores
                .iter()
                .copied()
                .enumerate()
                .collect::<Vec<_>>();
            ranked.sort_by(|a, b| b.1.total_cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
            let take = topk.min(ranked.len());
            let mut out_w = Vec::with_capacity(take);
            let mut out_i = Vec::with_capacity(take);
            for (idx, _) in ranked.into_iter().take(take) {
                out_w.push(raw_scores[idx]);
                out_i.push(idx as i32);
            }
            Ok((out_w, out_i))
        }
        other => Err(format!("unsupported router scoring_func {}", other)),
    }
}

fn router_kernel_name(scoring_func: u8) -> &'static str {
    match scoring_func {
        0 => "softmax_topk_kernel",
        1 => "sigmoid_topk_kernel",
        2 => "deepseek_v4_sqrtsoftplus_topk_kernel",
        _ => "unsupported_router_kernel",
    }
}

fn compute_router_topk_cpu_debug(
    logits: &[f32],
    topk: usize,
    scoring_func: u8,
    gate_bias: Option<&[f32]>,
    e_score_corr: Option<&[f32]>,
) -> Result<(Vec<f32>, Vec<i32>, serde_json::Value), String> {
    let mut scores = logits.to_vec();
    if let Some(bias) = gate_bias {
        if bias.len() != scores.len() {
            return Err(format!(
                "router gate bias length mismatch: got {} expected {}",
                bias.len(),
                scores.len(),
            ));
        }
        for (score, &b) in scores.iter_mut().zip(bias.iter()) {
            *score += b;
        }
    }
    if let Some(corr) = e_score_corr {
        if corr.len() != scores.len() {
            return Err(format!(
                "router e_score correction length mismatch: got {} expected {}",
                corr.len(),
                scores.len(),
            ));
        }
    }

    match scoring_func {
        0 => {
            let max_val = scores.iter().copied().fold(f32::NEG_INFINITY, f32::max);
            let exp_scores = scores
                .iter()
                .map(|&v| (v - max_val).exp())
                .collect::<Vec<_>>();
            let exp_sum = exp_scores.iter().copied().sum::<f32>();
            let inv_sum = if exp_sum > 0.0 { 1.0 / exp_sum } else { 0.0 };
            let probs = exp_scores.iter().map(|&v| v * inv_sum).collect::<Vec<_>>();
            let mut selection_scores = probs.clone();
            if let Some(corr) = e_score_corr {
                for (score, &c) in selection_scores.iter_mut().zip(corr.iter()) {
                    *score += c;
                }
            }
            let mut ranked = selection_scores
                .iter()
                .copied()
                .enumerate()
                .collect::<Vec<_>>();
            ranked.sort_by(|a, b| b.1.total_cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
            let take = topk.min(ranked.len());
            let top = ranked.into_iter().take(take).collect::<Vec<_>>();
            let topk_prob_sum = top.iter().map(|(idx, _)| probs[*idx]).sum::<f32>();
            let inv_topk_sum = if topk_prob_sum > 0.0 {
                1.0 / topk_prob_sum
            } else {
                0.0
            };
            let mut out_w = Vec::with_capacity(take);
            let mut out_i = Vec::with_capacity(take);
            let selected = top
                .iter()
                .map(|(idx, choice)| {
                    serde_json::json!({
                        "expert_id": *idx,
                        "score_after_bias_or_corr": scores[*idx],
                        "exp_score_minus_max": exp_scores[*idx],
                        "softmax_probability": probs[*idx],
                        "selection_score": *choice,
                        "topk_normalized_weight": probs[*idx] * inv_topk_sum,
                    })
                })
                .collect::<Vec<_>>();
            for (idx, _) in top {
                out_w.push(probs[idx] * inv_topk_sum);
                out_i.push(idx as i32);
            }
            Ok((
                out_w,
                out_i,
                serde_json::json!({
                    "scoring_func": "softmax",
                    "max_score": max_val,
                    "exp_sum": exp_sum,
                    "topk_probability_sum": topk_prob_sum,
                    "normalization": "softmax_all_experts_then_renormalize_topk",
                    "gate_bias_present": gate_bias.is_some(),
                    "e_score_corr_present": e_score_corr.is_some(),
                    "selected_experts": selected,
                }),
            ))
        }
        1 => {
            let sigmoid_scores = scores
                .iter()
                .copied()
                .map(|v| 1.0 / (1.0 + (-v).exp()))
                .collect::<Vec<_>>();
            let mut selection_scores = sigmoid_scores.clone();
            if let Some(corr) = e_score_corr {
                for (score, &c) in selection_scores.iter_mut().zip(corr.iter()) {
                    *score += c;
                }
            }
            let mut ranked = selection_scores
                .iter()
                .copied()
                .enumerate()
                .collect::<Vec<_>>();
            ranked.sort_by(|a, b| b.1.total_cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
            let take = topk.min(ranked.len());
            let top = ranked.into_iter().take(take).collect::<Vec<_>>();
            let mut out_w = Vec::with_capacity(take);
            let mut out_i = Vec::with_capacity(take);
            let selected = top
                .iter()
                .map(|(idx, choice)| {
                    serde_json::json!({
                        "expert_id": *idx,
                        "score_after_bias_or_corr": scores[*idx],
                        "sigmoid_score": sigmoid_scores[*idx],
                        "selection_score": *choice,
                        "topk_weight": sigmoid_scores[*idx],
                    })
                })
                .collect::<Vec<_>>();
            for (idx, _) in top {
                out_w.push(sigmoid_scores[idx]);
                out_i.push(idx as i32);
            }
            Ok((
                out_w,
                out_i,
                serde_json::json!({
                    "scoring_func": "sigmoid",
                    "normalization": "sigmoid_scores_no_topk_renormalization",
                    "gate_bias_present": gate_bias.is_some(),
                    "e_score_corr_present": e_score_corr.is_some(),
                    "selected_experts": selected,
                }),
            ))
        }
        2 => {
            let raw_scores = scores
                .iter()
                .copied()
                .map(|v| (v.max(0.0) + (-v.abs()).exp().ln_1p()).sqrt())
                .collect::<Vec<_>>();
            let mut selection_scores = raw_scores.clone();
            if let Some(corr) = e_score_corr {
                for (score, &c) in selection_scores.iter_mut().zip(corr.iter()) {
                    *score += c;
                }
            }
            let mut ranked = selection_scores
                .iter()
                .copied()
                .enumerate()
                .collect::<Vec<_>>();
            ranked.sort_by(|a, b| b.1.total_cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
            let take = topk.min(ranked.len());
            let top = ranked.into_iter().take(take).collect::<Vec<_>>();
            let selected_sum = top.iter().map(|(idx, _)| raw_scores[*idx]).sum::<f32>();
            let inv_sum = if selected_sum > 0.0 {
                1.0 / selected_sum
            } else {
                0.0
            };
            let mut out_w = Vec::with_capacity(take);
            let mut out_i = Vec::with_capacity(take);
            let selected = top
                .iter()
                .map(|(idx, choice)| {
                    serde_json::json!({
                        "expert_id": *idx,
                        "sqrtsoftplus_score": raw_scores[*idx],
                        "selection_score": *choice,
                        "topk_normalized_weight": raw_scores[*idx] * inv_sum,
                    })
                })
                .collect::<Vec<_>>();
            for (idx, _) in top {
                out_w.push(raw_scores[idx]);
                out_i.push(idx as i32);
            }
            Ok((
                out_w,
                out_i,
                serde_json::json!({
                    "scoring_func": "sqrtsoftplus",
                    "normalization": "selected_raw_scores_normalized_by_runtime_when_configured",
                    "gate_bias_present": gate_bias.is_some(),
                    "e_score_corr_present": e_score_corr.is_some(),
                    "selected_experts": selected,
                }),
            ))
        }
        other => Err(format!("unsupported router scoring_func {}", other)),
    }
}

fn f32_sum_in_order(values: impl IntoIterator<Item = f32>) -> f32 {
    let mut sum = 0.0f32;
    for value in values {
        sum += value;
    }
    sum
}

#[derive(Clone, Debug)]
struct RouterTopkKernelMathDebug {
    metadata: serde_json::Value,
    envelope_min: Vec<f32>,
    envelope_max: Vec<f32>,
    envelope_midpoint: Vec<f32>,
}

fn deterministic_reduction_orders(thread_count: usize) -> Vec<(&'static str, Vec<usize>)> {
    let threads = thread_count.max(1);
    let asc = (0..threads).collect::<Vec<_>>();
    let desc = (0..threads).rev().collect::<Vec<_>>();
    let even_odd = (0..threads)
        .step_by(2)
        .chain((1..threads).step_by(2))
        .collect::<Vec<_>>();
    let odd_even = (1..threads)
        .step_by(2)
        .chain((0..threads).step_by(2))
        .collect::<Vec<_>>();
    let mut bit_reverse = (0..threads).collect::<Vec<_>>();
    let bits = usize::BITS - (threads.saturating_sub(1)).leading_zeros();
    bit_reverse.sort_by_key(|&idx| idx.reverse_bits() >> (usize::BITS - bits));
    vec![
        ("thread_asc", asc),
        ("thread_desc", desc),
        ("thread_even_odd", even_odd),
        ("thread_odd_even", odd_even),
        ("thread_bit_reverse", bit_reverse),
    ]
}

fn envelope_compare_json(
    actual: &[f32],
    min_values: &[f32],
    max_values: &[f32],
) -> serde_json::Value {
    let mut outside_max_abs = 0.0f32;
    let mut outside_l2 = 0.0f64;
    let mut outside_count = 0usize;
    let mut first_outside_idx: Option<usize> = None;
    for (idx, &value) in actual.iter().enumerate() {
        let Some(&lo) = min_values.get(idx) else {
            continue;
        };
        let Some(&hi) = max_values.get(idx) else {
            continue;
        };
        let outside = if value < lo {
            lo - value
        } else if value > hi {
            value - hi
        } else {
            0.0
        };
        if outside > 0.0 {
            outside_count += 1;
            if first_outside_idx.is_none() {
                first_outside_idx = Some(idx);
            }
            outside_max_abs = outside_max_abs.max(outside);
            let outside64 = outside as f64;
            outside_l2 += outside64 * outside64;
        }
    }
    serde_json::json!({
        "all_actual_values_within_envelope": outside_count == 0,
        "outside_count": outside_count,
        "first_outside_idx": first_outside_idx,
        "outside_max_abs": outside_max_abs,
        "outside_l2": outside_l2.sqrt(),
    })
}

fn compute_router_topk_kernel_math_debug(
    logits: &[f32],
    topk: usize,
    scoring_func: u8,
    gate_bias: Option<&[f32]>,
    e_score_corr: Option<&[f32]>,
    thread_count: usize,
) -> Result<RouterTopkKernelMathDebug, String> {
    let mut scores = logits.to_vec();
    if let Some(bias) = gate_bias {
        if bias.len() != scores.len() {
            return Err(format!(
                "router gate bias length mismatch: got {} expected {}",
                bias.len(),
                scores.len(),
            ));
        }
        for (score, &b) in scores.iter_mut().zip(bias.iter()) {
            *score += b;
        }
    }
    if let Some(corr) = e_score_corr {
        if corr.len() != scores.len() {
            return Err(format!(
                "router e_score correction length mismatch: got {} expected {}",
                corr.len(),
                scores.len(),
            ));
        }
    }

    let take = topk.min(scores.len());
    if take == 0 {
        return Ok(RouterTopkKernelMathDebug {
            metadata: serde_json::json!({
                "scoring_func": scoring_func,
                "topk": topk,
                "selected_experts": [],
            }),
            envelope_min: Vec::new(),
            envelope_max: Vec::new(),
            envelope_midpoint: Vec::new(),
        });
    }

    match scoring_func {
        0 => {
            let max_val = scores.iter().copied().fold(f32::NEG_INFINITY, f32::max);
            let exp_scores = scores
                .iter()
                .map(|&value| (value - max_val).exp())
                .collect::<Vec<_>>();
            let mut selection_scores = exp_scores.clone();
            if let Some(corr) = e_score_corr {
                for (score, &c) in selection_scores.iter_mut().zip(corr.iter()) {
                    *score += c;
                }
            }
            let mut ranked = selection_scores
                .iter()
                .copied()
                .enumerate()
                .collect::<Vec<_>>();
            ranked.sort_by(|a, b| b.1.total_cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
            let top = ranked.into_iter().take(take).collect::<Vec<_>>();

            let exact_top_sum = f32_sum_in_order(top.iter().map(|(idx, _)| exp_scores[*idx]));
            let exact_selected_weights = top
                .iter()
                .map(|(idx, _)| {
                    if exact_top_sum > 0.0 {
                        exp_scores[*idx] / exact_top_sum
                    } else {
                        0.0
                    }
                })
                .collect::<Vec<_>>();

            let seq_sum = f32_sum_in_order(exp_scores.iter().copied());
            let threads = thread_count.max(1);
            let mut per_thread = vec![0.0f32; threads];
            for tid in 0..threads {
                let mut local = 0.0f32;
                let mut idx = tid;
                while idx < exp_scores.len() {
                    local += exp_scores[idx];
                    idx += threads;
                }
                per_thread[tid] = local;
            }
            let thread_asc_sum = f32_sum_in_order(per_thread.iter().copied());
            let thread_desc_sum = f32_sum_in_order(per_thread.iter().rev().copied());

            let two_stage_weights = |denom: f32| -> Vec<f32> {
                let inv_sum = if denom > 0.0 { 1.0f32 / denom } else { 0.0 };
                let probs = top
                    .iter()
                    .map(|(idx, _)| exp_scores[*idx] * inv_sum)
                    .collect::<Vec<_>>();
                let top_sum = f32_sum_in_order(probs.iter().copied());
                let inv_top = if top_sum > 0.0 { 1.0f32 / top_sum } else { 0.0 };
                probs
                    .iter()
                    .map(|value| *value * inv_top)
                    .collect::<Vec<_>>()
            };

            let mut variants: Vec<(String, f32, Vec<f32>)> = vec![
                (
                    "rust_sequential_all_experts".to_string(),
                    seq_sum,
                    two_stage_weights(seq_sum),
                ),
                (
                    "thread_asc_atomic_sum".to_string(),
                    thread_asc_sum,
                    two_stage_weights(thread_asc_sum),
                ),
                (
                    "thread_desc_atomic_sum".to_string(),
                    thread_desc_sum,
                    two_stage_weights(thread_desc_sum),
                ),
            ];
            for (label, order) in deterministic_reduction_orders(threads) {
                let denom =
                    f32_sum_in_order(order.iter().filter_map(|&idx| per_thread.get(idx).copied()));
                variants.push((label.to_string(), denom, two_stage_weights(denom)));
            }
            let mut envelope_min = vec![f32::INFINITY; take];
            let mut envelope_max = vec![f32::NEG_INFINITY; take];
            for (_, _, weights) in &variants {
                for idx in 0..take {
                    envelope_min[idx] = envelope_min[idx].min(weights[idx]);
                    envelope_max[idx] = envelope_max[idx].max(weights[idx]);
                }
            }
            let envelope_midpoint = envelope_min
                .iter()
                .zip(envelope_max.iter())
                .map(|(&lo, &hi)| lo + (hi - lo) * 0.5)
                .collect::<Vec<_>>();
            let envelope_spread = envelope_min
                .iter()
                .zip(envelope_max.iter())
                .map(|(&lo, &hi)| hi - lo)
                .collect::<Vec<_>>();
            let envelope_spread_l2 = diag_l2_norm(&envelope_spread);
            let variant_json = variants
                .iter()
                .map(|(label, denom, weights)| {
                    serde_json::json!({
                        "label": label,
                        "denominator": *denom,
                        "weights": weights,
                    })
                })
                .collect::<Vec<_>>();

            let selected = top
                .iter()
                .zip(exact_selected_weights.iter())
                .map(|((idx, choice), &weight)| {
                    serde_json::json!({
                        "expert_id": *idx,
                        "score_after_bias_or_corr": scores[*idx],
                        "exp_score_minus_max": exp_scores[*idx],
                        "selection_score": *choice,
                        "exact_selected_logit_normalized_weight": weight,
                    })
                })
                .collect::<Vec<_>>();

            Ok(RouterTopkKernelMathDebug {
                metadata: serde_json::json!({
                "scoring_func": "softmax",
                "max_score": max_val,
                "thread_count": threads,
                "exp_sum_rust_sequential": seq_sum,
                "exp_sum_thread_asc": thread_asc_sum,
                "exp_sum_thread_desc": thread_desc_sum,
                "exp_sum_thread_order_spread": (thread_asc_sum - thread_desc_sum).abs(),
                "topk_exp_sum": exact_top_sum,
                "selected_experts": selected,
                "weights_exact_selected_logit_normalization": exact_selected_weights,
                "weights_two_stage_rust_sequential_sum": two_stage_weights(seq_sum),
                "weights_two_stage_thread_asc_sum": two_stage_weights(thread_asc_sum),
                "weights_two_stage_thread_desc_sum": two_stage_weights(thread_desc_sum),
                "same_logit_reduction_order_variants": variant_json,
                "same_logit_reduction_order_envelope_min": envelope_min,
                "same_logit_reduction_order_envelope_max": envelope_max,
                "same_logit_reduction_order_envelope_midpoint": envelope_midpoint,
                "same_logit_reduction_order_envelope_spread": envelope_spread,
                "same_logit_reduction_order_envelope_spread_l2": envelope_spread_l2,
                "same_logit_reduction_order_variant_count": variants.len(),
                "normalization": "softmax_kernel_uses_full_sum_then_topk_renormalization; exact_selected_variant_cancels_full_sum",
                "gate_bias_present": gate_bias.is_some(),
                "e_score_corr_present": e_score_corr.is_some(),
                }),
                envelope_min,
                envelope_max,
                envelope_midpoint,
            })
        }
        1 => {
            let sigmoid_scores = scores
                .iter()
                .copied()
                .map(|value| 1.0f32 / (1.0f32 + (-value).exp()))
                .collect::<Vec<_>>();
            let mut selection_scores = sigmoid_scores.clone();
            if let Some(corr) = e_score_corr {
                for (score, &c) in selection_scores.iter_mut().zip(corr.iter()) {
                    *score += c;
                }
            }
            let mut ranked = selection_scores
                .iter()
                .copied()
                .enumerate()
                .collect::<Vec<_>>();
            ranked.sort_by(|a, b| b.1.total_cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
            let top = ranked.into_iter().take(take).collect::<Vec<_>>();
            let selected = top
                .iter()
                .map(|(idx, choice)| {
                    serde_json::json!({
                        "expert_id": *idx,
                        "score_after_bias_or_corr": scores[*idx],
                        "sigmoid_score": sigmoid_scores[*idx],
                        "selection_score": *choice,
                    })
                })
                .collect::<Vec<_>>();
            let weights = top
                .iter()
                .map(|(idx, _)| sigmoid_scores[*idx])
                .collect::<Vec<_>>();
            Ok(RouterTopkKernelMathDebug {
                metadata: serde_json::json!({
                    "scoring_func": "sigmoid",
                    "selected_experts": selected,
                    "normalization": "sigmoid_scores_no_topk_renormalization",
                    "same_logit_reduction_order_variant_count": 1,
                    "same_logit_reduction_order_envelope_spread_l2": 0.0,
                    "gate_bias_present": gate_bias.is_some(),
                    "e_score_corr_present": e_score_corr.is_some(),
                }),
                envelope_min: weights.clone(),
                envelope_max: weights.clone(),
                envelope_midpoint: weights,
            })
        }
        2 => {
            let raw_scores = scores
                .iter()
                .copied()
                .map(|v| (v.max(0.0) + (-v.abs()).exp().ln_1p()).sqrt())
                .collect::<Vec<_>>();
            let mut selection_scores = raw_scores.clone();
            if let Some(corr) = e_score_corr {
                for (score, &c) in selection_scores.iter_mut().zip(corr.iter()) {
                    *score += c;
                }
            }
            let mut ranked = selection_scores
                .iter()
                .copied()
                .enumerate()
                .collect::<Vec<_>>();
            ranked.sort_by(|a, b| b.1.total_cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
            let top = ranked.into_iter().take(take).collect::<Vec<_>>();
            let weights = top
                .iter()
                .map(|(idx, _)| raw_scores[*idx])
                .collect::<Vec<_>>();
            let selected = top
                .iter()
                .map(|(idx, choice)| {
                    serde_json::json!({
                        "expert_id": *idx,
                        "sqrtsoftplus_score": raw_scores[*idx],
                        "selection_score": *choice,
                    })
                })
                .collect::<Vec<_>>();
            Ok(RouterTopkKernelMathDebug {
                metadata: serde_json::json!({
                    "scoring_func": "sqrtsoftplus",
                    "selected_experts": selected,
                    "normalization": "selected_raw_scores_normalized_by_runtime_when_configured",
                    "same_logit_reduction_order_variant_count": 1,
                    "same_logit_reduction_order_envelope_spread_l2": 0.0,
                    "gate_bias_present": gate_bias.is_some(),
                    "e_score_corr_present": e_score_corr.is_some(),
                }),
                envelope_min: weights.clone(),
                envelope_max: weights.clone(),
                envelope_midpoint: weights,
            })
        }
        other => Err(format!("unsupported router scoring_func {}", other)),
    }
}

fn compute_topk_ids_from_logits_cpu(logits: &[f32], topk: usize) -> Vec<i32> {
    if topk == 0 || logits.is_empty() {
        return Vec::new();
    }
    let mut ranked = logits.iter().copied().enumerate().collect::<Vec<_>>();
    ranked.sort_by(|a, b| b.1.total_cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    ranked
        .into_iter()
        .take(topk.min(logits.len()))
        .map(|(idx, _)| idx as i32)
        .collect()
}

#[inline]
fn apply_logit_softcap_in_place(logits: &mut [f32], softcap: f32) {
    if softcap <= 0.0 || !softcap.is_finite() {
        return;
    }
    for value in logits.iter_mut() {
        if value.is_finite() {
            *value = (*value / softcap).tanh() * softcap;
        }
    }
}

fn compute_marlin_gemm_row_cpu_reference(
    input_row_bf16: &[u16],
    weight: &MarlinWeight,
) -> Result<Vec<f32>, String> {
    if input_row_bf16.len() != weight.k {
        return Err(format!(
            "marlin cpu ref input length mismatch: got {} expected {}",
            input_row_bf16.len(),
            weight.k,
        ));
    }
    let packed_len = match weight.num_bits {
        4 => (weight.k / 16) * (weight.n * 2),
        8 => (weight.k / 16) * (weight.n * 4),
        other => return Err(format!("unsupported Marlin bit width: {}", other)),
    };
    let scales_len = weight.num_groups * weight.n;
    let packed = download_device_u32(weight.packed, packed_len)?;
    let scales = download_device_u16(weight.scales, scales_len)?;
    let repacked = MarlinRepacked {
        packed,
        scales,
        k: weight.k,
        n: weight.n,
        group_size: weight.group_size,
    };
    let dequant = match weight.num_bits {
        4 => dequantize_marlin(&repacked),
        8 => dequantize_marlin_int8(&repacked),
        _ => unreachable!(),
    };
    let input_f32: Vec<f32> = input_row_bf16.iter().map(|&v| bf16_to_f32(v)).collect();
    let mut out = vec![0.0f32; weight.n];
    for out_idx in 0..weight.n {
        let row = &dequant[out_idx * weight.k..(out_idx + 1) * weight.k];
        let mut acc = 0.0f32;
        for i in 0..weight.k {
            acc += row[i] * input_f32[i];
        }
        out[out_idx] = acc;
    }
    Ok(out)
}

fn compute_marlin_gemm_row_cpu_reference_alt_layout(
    input_row_bf16: &[u16],
    weight: &MarlinWeight,
) -> Result<Vec<f32>, String> {
    if input_row_bf16.len() != weight.k {
        return Err(format!(
            "marlin alt cpu ref input length mismatch: got {} expected {}",
            input_row_bf16.len(),
            weight.k,
        ));
    }
    let packed_len = match weight.num_bits {
        4 => (weight.k / 16) * (weight.n * 2),
        8 => (weight.k / 16) * (weight.n * 4),
        other => return Err(format!("unsupported Marlin bit width: {}", other)),
    };
    let scales_len = weight.num_groups * weight.n;
    let packed = download_device_u32(weight.packed, packed_len)?;
    let scales = download_device_u16(weight.scales, scales_len)?;
    let repacked = MarlinRepacked {
        packed,
        scales,
        k: weight.k,
        n: weight.n,
        group_size: weight.group_size,
    };
    let dequant = match weight.num_bits {
        4 => dequantize_marlin(&repacked),
        8 => dequantize_marlin_int8(&repacked),
        _ => unreachable!(),
    };
    let input_f32: Vec<f32> = input_row_bf16.iter().map(|&v| bf16_to_f32(v)).collect();
    let mut out = vec![0.0f32; weight.n];
    for out_idx in 0..weight.n {
        let mut acc = 0.0f32;
        for i in 0..weight.k {
            acc += dequant[i * weight.n + out_idx] * input_f32[i];
        }
        out[out_idx] = acc;
    }
    Ok(out)
}

fn diag_compute_moe_accum_last_cpu_from_rows(
    expert_out_rows_bf16: &[f32],
    gather_src: &[i32],
    gather_weights: &[f32],
    last_pos: usize,
    h: usize,
) -> Result<Vec<f32>, String> {
    if gather_src.len() != gather_weights.len() {
        return Err(format!(
            "moe accum cpu ref gather length mismatch: src={} weights={}",
            gather_src.len(),
            gather_weights.len(),
        ));
    }
    if expert_out_rows_bf16.len() != gather_src.len() * h {
        return Err(format!(
            "moe accum cpu ref expert_out length mismatch: got {} expected {}",
            expert_out_rows_bf16.len(),
            gather_src.len() * h,
        ));
    }
    let mut out = vec![0.0f32; h];
    for row in 0..gather_src.len() {
        if gather_src[row] != last_pos as i32 {
            continue;
        }
        let wt = gather_weights[row];
        let row_slice = &expert_out_rows_bf16[row * h..(row + 1) * h];
        for i in 0..h {
            out[i] += row_slice[i] * wt;
        }
    }
    Ok(out)
}

fn diag_compute_moe_accum_selected_cpu_from_bf16_bits(
    expert_out_rows_bf16: &[u16],
    gather_src: &[i32],
    gather_weights: &[f32],
    selected_pos: usize,
    h: usize,
) -> Result<Vec<f32>, String> {
    if gather_src.len() != gather_weights.len() {
        return Err(format!(
            "moe accum cpu ref gather length mismatch: src={} weights={}",
            gather_src.len(),
            gather_weights.len(),
        ));
    }
    if expert_out_rows_bf16.len() != gather_src.len() * h {
        return Err(format!(
            "moe accum cpu ref expert_out bits length mismatch: got {} expected {}",
            expert_out_rows_bf16.len(),
            gather_src.len() * h,
        ));
    }
    let mut out = vec![0.0f32; h];
    for row in 0..gather_src.len() {
        if gather_src[row] != selected_pos as i32 {
            continue;
        }
        let wt = gather_weights[row];
        let row_slice = &expert_out_rows_bf16[row * h..(row + 1) * h];
        for col in 0..h {
            out[col] += bf16_to_f32(row_slice[col]) * wt;
        }
    }
    Ok(out)
}

fn diag_l2_norm(values: &[f32]) -> f32 {
    values.iter().map(|v| v * v).sum::<f32>().sqrt()
}

fn diag_compute_moe_accum_last_cpu_from_sorted_rows(
    expert_out_rows_bf16: &[f32],
    sorted_ids: &[i32],
    sorted_weights: &[f32],
    last_pos: usize,
    h: usize,
    topk: usize,
) -> Result<Vec<f32>, String> {
    if sorted_ids.len() != sorted_weights.len() {
        return Err(format!(
            "moe accum cpu ref sorted length mismatch: ids={} weights={}",
            sorted_ids.len(),
            sorted_weights.len(),
        ));
    }
    if expert_out_rows_bf16.len() != sorted_ids.len() * h {
        return Err(format!(
            "moe accum cpu ref sorted expert_out length mismatch: got {} expected {}",
            expert_out_rows_bf16.len(),
            sorted_ids.len() * h,
        ));
    }
    if topk == 0 {
        return Err("moe accum cpu ref sorted topk must be > 0".to_string());
    }
    let mut out = vec![0.0f32; h];
    for row in 0..sorted_ids.len() {
        let sid = sorted_ids[row];
        if sid < 0 {
            continue;
        }
        let token = (sid as usize) / topk;
        if token != last_pos {
            continue;
        }
        let sid_usize = sid as usize;
        if sid_usize >= sorted_ids.len() {
            return Err(format!(
                "moe accum cpu ref sorted sid out of range: sid={} rows={}",
                sid_usize,
                sorted_ids.len(),
            ));
        }
        let wt = sorted_weights[row];
        let row_slice = &expert_out_rows_bf16[sid_usize * h..(sid_usize + 1) * h];
        for i in 0..h {
            out[i] += row_slice[i] * wt;
        }
    }
    Ok(out)
}

