fn diag_cleanup_temp_moe_scatter(
    d_accum: &mut u64,
    d_src: &mut u64,
    d_sorted_ids: &mut u64,
    d_topk_weights: &mut u64,
) {
    unsafe {
        if *d_accum != 0 {
            cuda_sys::lib().cuMemFree_v2(*d_accum);
            *d_accum = 0;
        }
        if *d_src != 0 {
            cuda_sys::lib().cuMemFree_v2(*d_src);
            *d_src = 0;
        }
        if *d_sorted_ids != 0 {
            cuda_sys::lib().cuMemFree_v2(*d_sorted_ids);
            *d_sorted_ids = 0;
        }
        if *d_topk_weights != 0 {
            cuda_sys::lib().cuMemFree_v2(*d_topk_weights);
            *d_topk_weights = 0;
        }
    }
}

fn diag_cleanup_temp_shared_add(d_accum: &mut u64, d_shared: &mut u64, d_gate: &mut u64) {
    unsafe {
        if *d_accum != 0 {
            cuda_sys::lib().cuMemFree_v2(*d_accum);
            *d_accum = 0;
        }
        if *d_shared != 0 {
            cuda_sys::lib().cuMemFree_v2(*d_shared);
            *d_shared = 0;
        }
        if *d_gate != 0 {
            cuda_sys::lib().cuMemFree_v2(*d_gate);
            *d_gate = 0;
        }
    }
}

fn diag_compute_moe_total_accum_last_cpu(
    routed_accum_last: &[f32],
    shared_out_last_bf16: Option<&[f32]>,
    shared_gate_raw: Option<f32>,
) -> Result<Vec<f32>, String> {
    let mut out = routed_accum_last.to_vec();
    let Some(shared_out) = shared_out_last_bf16 else {
        return Ok(out);
    };
    if shared_out.len() != out.len() {
        return Err(format!(
            "moe total accum cpu ref shared length mismatch: shared={} accum={}",
            shared_out.len(),
            out.len(),
        ));
    }
    let shared_scale = shared_gate_raw
        .map(|raw| 1.0 / (1.0 + (-raw).exp()))
        .unwrap_or(1.0);
    for i in 0..out.len() {
        out[i] += shared_out[i] * shared_scale;
    }
    Ok(out)
}

fn diag_compute_shared_gate_raw_last_cpu(
    hidden_last_bf16: &[f32],
    shared_gate_weight_bf16: &[f32],
) -> Result<f32, String> {
    if hidden_last_bf16.len() != shared_gate_weight_bf16.len() {
        return Err(format!(
            "shared gate cpu ref length mismatch: hidden={} gate={}",
            hidden_last_bf16.len(),
            shared_gate_weight_bf16.len(),
        ));
    }
    let mut acc = 0.0f32;
    for i in 0..hidden_last_bf16.len() {
        acc += hidden_last_bf16[i] * shared_gate_weight_bf16[i];
    }
    Ok(acc)
}

fn diag_compute_shared_out_last_cpu_bf16(
    hidden_last_bf16: &[f32],
    shared_w1_bf16: &[f32],
    shared_w2_bf16: &[f32],
    hidden_size: usize,
    shared_inter: usize,
    gated: bool,
    activation: u8,
) -> Result<Vec<f32>, String> {
    let w1_out = if gated {
        shared_inter * 2
    } else {
        shared_inter
    };
    if hidden_last_bf16.len() != hidden_size {
        return Err(format!(
            "shared_out cpu ref hidden length mismatch: hidden={} expected={}",
            hidden_last_bf16.len(),
            hidden_size,
        ));
    }
    if shared_w1_bf16.len() != w1_out * hidden_size {
        return Err(format!(
            "shared_out cpu ref w1 length mismatch: got={} expected={}",
            shared_w1_bf16.len(),
            w1_out * hidden_size,
        ));
    }
    if shared_w2_bf16.len() % shared_inter != 0 {
        return Err(format!(
            "shared_out cpu ref w2 length mismatch: len={} shared_inter={}",
            shared_w2_bf16.len(),
            shared_inter,
        ));
    }
    let out_dim = shared_w2_bf16.len() / shared_inter;

    let mut w1 = vec![0.0f32; w1_out];
    for row in 0..w1_out {
        let mut acc = 0.0f32;
        let row_off = row * hidden_size;
        for col in 0..hidden_size {
            acc += shared_w1_bf16[row_off + col] * hidden_last_bf16[col];
        }
        w1[row] = acc;
    }

    let mut act = vec![0.0f32; shared_inter];
    if gated {
        for i in 0..shared_inter {
            let gate = w1[i];
            let up = w1[shared_inter + i];
            let silu_gate = if activation == 1 {
                let relu = gate.max(0.0);
                relu * relu
            } else {
                gate / (1.0 + (-gate).exp())
            };
            act[i] = silu_gate * up;
        }
    } else {
        for i in 0..shared_inter {
            let v = w1[i];
            act[i] = if activation == 1 {
                let relu = v.max(0.0);
                relu * relu
            } else {
                v / (1.0 + (-v).exp())
            };
        }
    }

    let mut out = vec![0.0f32; out_dim];
    for row in 0..out_dim {
        let mut acc = 0.0f32;
        let row_off = row * shared_inter;
        for col in 0..shared_inter {
            acc += shared_w2_bf16[row_off + col] * act[col];
        }
        out[row] = acc;
    }
    Ok(out)
}

fn diag_compute_shared_out_last_cpu_marlin(
    hidden_last_bf16: &[u16],
    shared_w1: &MarlinWeight,
    shared_w2: &MarlinWeight,
    gated: bool,
    activation: u8,
) -> Result<Vec<f32>, String> {
    if hidden_last_bf16.len() != shared_w1.k {
        return Err(format!(
            "shared_out marlin cpu ref hidden length mismatch: hidden={} expected={}",
            hidden_last_bf16.len(),
            shared_w1.k,
        ));
    }
    let shared_inter = shared_w1.n / if gated { 2 } else { 1 };
    if shared_w2.k != shared_inter {
        return Err(format!(
            "shared_out marlin cpu ref w2 input mismatch: w2.k={} shared_inter={}",
            shared_w2.k, shared_inter,
        ));
    }

    let w1 = compute_marlin_gemm_row_cpu_reference(hidden_last_bf16, shared_w1)?;
    let mut act = vec![0.0f32; shared_inter];
    if gated {
        for i in 0..shared_inter {
            let gate = w1[i];
            let up = w1[shared_inter + i];
            let activated = if activation == 1 {
                let relu = gate.max(0.0);
                relu * relu
            } else {
                gate / (1.0 + (-gate).exp())
            };
            act[i] = activated * up;
        }
    } else {
        for i in 0..shared_inter {
            let v = w1[i];
            act[i] = if activation == 1 {
                let relu = v.max(0.0);
                relu * relu
            } else {
                v / (1.0 + (-v).exp())
            };
        }
    }

    let act_bf16 = act
        .iter()
        .map(|&v| half::bf16::from_f32(v).to_bits())
        .collect::<Vec<_>>();
    compute_marlin_gemm_row_cpu_reference(&act_bf16, shared_w2)
}

fn diag_max_abs_diff(a: &[f32], b: &[f32]) -> Result<f32, String> {
    if a.len() != b.len() {
        return Err(format!("diff length mismatch: {} vs {}", a.len(), b.len()));
    }
    let mut max_abs = 0.0f32;
    for i in 0..a.len() {
        let diff = (a[i] - b[i]).abs();
        if diff > max_abs {
            max_abs = diff;
        }
    }
    Ok(max_abs)
}

fn trace_emit_prefill_mark(
    trace: Option<&PrefillTraceConfig>,
    step: usize,
    position: usize,
    token_id: usize,
    layer: Option<usize>,
    component: &str,
    message: &str,
) {
    let Some(trace) = trace else {
        return;
    };
    if !trace.should_emit(step, layer, component) {
        return;
    }
    let layer_s = layer
        .map(|v| v.to_string())
        .unwrap_or_else(|| "-".to_string());
    eprintln!(
        "[KRASIS-TRACE] event=mark step={} pos={} tok={} layer={} component={} {}",
        step, position, token_id, layer_s, component, message
    );
}

fn trace_emit_prefill_global_mark(
    trace: Option<&PrefillTraceConfig>,
    component: &str,
    message: &str,
) {
    let Some(trace) = trace else {
        return;
    };
    if !trace.allows_component(component) {
        return;
    }
    eprintln!(
        "[KRASIS-TRACE] event=mark scope=global component={} {}",
        component, message,
    );
}

const MARLIN_PIPE_STAGES: usize = 4;
const MARLIN_MIN_THREAD_N: usize = 64;
const MARLIN_MIN_THREAD_K: usize = 64;
const MARLIN_MAX_BLOCKS_PER_SM: usize = 4;
const MARLIN_MAX_LOCK_SLOTS_PER_SM: usize = 4;

fn marlin_moe_scales_cache_size(
    thread_n: usize,
    thread_k: usize,
    prob_n: usize,
    prob_k: usize,
    num_bits: usize,
    group_size: isize,
    has_act_order: bool,
    is_k_full: bool,
) -> usize {
    let cache_scales_chunk = has_act_order && !is_k_full;
    let tb_n = thread_n;
    let tb_k = thread_k;
    let tb_groups = if group_size == -1 {
        1
    } else if group_size == 0 {
        tb_k.div_ceil(32)
    } else {
        tb_k.div_ceil(group_size as usize)
    };

    if cache_scales_chunk {
        let load_groups = (tb_groups * MARLIN_PIPE_STAGES * 2).max(32);
        load_groups * tb_n * 2
    } else {
        let _ = (prob_n, prob_k, num_bits);
        tb_groups * tb_n * 2 * MARLIN_PIPE_STAGES
    }
}

fn marlin_moe_kernel_cache_size(
    thread_m_blocks: usize,
    thread_n: usize,
    thread_k: usize,
    prob_n: usize,
    prob_k: usize,
    num_bits: usize,
    group_size: isize,
    has_act_order: bool,
    is_k_full: bool,
    has_zp: bool,
    is_zp_float: bool,
) -> usize {
    let pack_factor = 32 / num_bits;
    let tb_k = thread_k;
    let tb_n = thread_n;
    let tb_m = thread_m_blocks * 16;
    // MoE metadata ahead of sh_new matches the CUDA template layout:
    // - sh_block_sorted_ids: moe_block_size / 4 int4s
    // - sh_rd_block_sorted_ids: moe_block_size / 4 int4s
    // - sh_block_topk_weights plus pad: moe_block_size / 2 + moe_block_size int4s
    // Total = 2 * moe_block_size int4s = tb_m * 32 bytes.
    let sh_block_meta_size = tb_m * 32;
    let sh_a_size = MARLIN_PIPE_STAGES * (tb_m * tb_k) * 2;
    let sh_b_size = MARLIN_PIPE_STAGES * (tb_k * tb_n / pack_factor) * 4;
    let sh_red_size = tb_m * (tb_n + 8) * 2;
    let sh_bias_size = tb_n * 2;
    let mut tmp_size = sh_red_size.max(sh_b_size) + sh_bias_size;
    tmp_size = tmp_size.max(sh_b_size.max(sh_red_size));
    let sh_s_size = marlin_moe_scales_cache_size(
        thread_n,
        thread_k,
        prob_n,
        prob_k,
        num_bits,
        group_size,
        has_act_order,
        is_k_full,
    );
    let sh_g_idx_size = if has_act_order && !is_k_full {
        MARLIN_PIPE_STAGES * tb_k / 4
    } else {
        0
    };
    let sh_zp_size = if has_zp {
        if is_zp_float {
            sh_s_size
        } else if num_bits == 4 {
            sh_s_size / 4
        } else if num_bits == 8 {
            sh_s_size / 2
        } else {
            0
        }
    } else {
        0
    };
    tmp_size + sh_a_size + sh_s_size + sh_zp_size + sh_g_idx_size + sh_block_meta_size
}

fn fused_moe_fp32_reduce_floats(
    moe_block_size: usize,
    prob_n: usize,
    prob_k: usize,
    num_bits: usize,
    group_size: usize,
    sms: usize,
    max_shared_mem: usize,
) -> usize {
    let thread_m_blocks = moe_block_size.div_ceil(16);
    let candidate_cfgs: &[(usize, usize)] = if thread_m_blocks > 1 {
        &[(64, 256), (64, 128), (128, 64)]
    } else {
        &[(128, 128), (64, 128), (128, 64)]
    };
    let group_size = group_size as isize;
    let mut max_floats = 0usize;

    for &(thread_k, thread_n) in candidate_cfgs {
        if prob_k % thread_k != 0 || prob_n % thread_n != 0 {
            continue;
        }
        if thread_n < MARLIN_MIN_THREAD_N || thread_k < MARLIN_MIN_THREAD_K {
            continue;
        }
        let cache_size = marlin_moe_kernel_cache_size(
            thread_m_blocks,
            thread_n,
            thread_k,
            prob_n,
            prob_k,
            num_bits,
            group_size,
            false,
            true,
            false,
            false,
        );
        if cache_size + 512 > max_shared_mem {
            continue;
        }
        // The fused MoE kernel indexes C_tmp by locks_off rather than by launch
        // block id. locks_off can consume any slot in the fixed workspace lock
        // arena (sms * 4), so the FP32 reduction scratch must cover the full
        // lock-slot fanout even when the chosen launch occupancy is 1 block/SM.
        let floats = sms * MARLIN_MAX_LOCK_SLOTS_PER_SM * moe_block_size * thread_n;
        max_floats = max_floats.max(floats);
    }

    if max_floats == 0 {
        sms * moe_block_size * 256
    } else {
        max_floats
    }
}

fn max_shared_mem_for_device(device_ordinal: usize) -> usize {
    let mut max_shared_mem: i32 = 0;
    unsafe {
        cuda_sys::lib().cuDeviceGetAttribute(
            &mut max_shared_mem,
            cuda_sys::CUdevice_attribute_enum::CU_DEVICE_ATTRIBUTE_MAX_SHARED_MEMORY_PER_BLOCK_OPTIN,
            device_ordinal as i32,
        );
    }
    max_shared_mem.max(0) as usize
}

pub fn fused_moe_ctmp_floats_for_config(config: &PrefillModelConfig) -> (usize, usize) {
    if config.n_routed_experts == 0 {
        return (0, 0);
    }
    let moe_block_size = 64;
    let hidden_size = config.hidden_size;
    let moe_intermediate_size = config.moe_intermediate_size;
    let expert_bits = config.expert_bits as usize;
    let group_size = config.group_size.max(1);
    let max_shared_mem = max_shared_mem_for_device(config.device_ordinal);
    let w1_n = if config.moe_gated {
        2 * moe_intermediate_size
    } else {
        moe_intermediate_size
    };
    let w1_ctmp_floats = fused_moe_fp32_reduce_floats(
        moe_block_size,
        w1_n,
        hidden_size,
        expert_bits,
        group_size,
        config.sms,
        max_shared_mem,
    );
    let w2_ctmp_floats = fused_moe_fp32_reduce_floats(
        moe_block_size,
        hidden_size,
        moe_intermediate_size,
        expert_bits,
        group_size,
        config.sms,
        max_shared_mem,
    );
    (w1_ctmp_floats, w2_ctmp_floats)
}

fn installed_package_sidecar(name: &str) -> Option<String> {
    use pyo3::types::PyModule;

    Python::with_gil(|py| {
        let pkg = PyModule::import(py, "krasis").ok()?;
        let pkg_file: String = pkg.getattr("__file__").ok()?.extract().ok()?;
        let pkg_dir = PathBuf::from(pkg_file).parent()?.to_path_buf();
        for candidate in [
            pkg_dir.join(name),
            pkg_dir.parent()?.join("krasis.libs").join(name),
        ] {
            if candidate.exists() {
                return Some(candidate.to_string_lossy().to_string());
            }
        }
        None
    })
}

// ════════════════════════════════════════════════════════════════════════
//  GpuBuf: raw synchronous GPU allocation (bypasses cudarc pool)
// ════════════════════════════════════════════════════════════════════════
//
// cudarc's CudaSlice uses cuMemAllocAsync/cuMemFreeAsync through the CUDA
// stream-ordered memory pool. When scratch buffers are freed and reallocated
// between prefill cycles, the pool's async free/alloc interacts badly with
// our CU_STREAM_NON_BLOCKING compute streams, causing GPU kernel hangs.
//
// GpuBuf uses cuMemAlloc_v2/cuMemFree_v2 (synchronous, no pool) so
// allocation and deallocation are immediate and deterministic.

pub struct GpuBuf<T: Copy> {
    ptr: u64,   // CUdeviceptr
    len: usize, // element count (not bytes)
    device_ordinal: i32,
    _phantom: std::marker::PhantomData<T>,
}

unsafe impl<T: Copy + Send> Send for GpuBuf<T> {}
unsafe impl<T: Copy + Sync> Sync for GpuBuf<T> {}

impl<T: Copy> GpuBuf<T> {
    pub fn alloc_uninit(count: usize) -> Result<Self, String> {
        let bytes = count * std::mem::size_of::<T>();
        if bytes == 0 {
            return Ok(Self {
                ptr: 0,
                len: 0,
                device_ordinal: 0,
                _phantom: std::marker::PhantomData,
            });
        }
        // Get current device ordinal for drop
        let mut dev: i32 = 0;
        unsafe {
            cuda_sys::lib().cuCtxGetDevice(&mut dev);
        }
        let mut ptr: u64 = 0;
        let err = unsafe { cuda_sys::lib().cuMemAlloc_v2(&mut ptr, bytes) };
        if err != cuda_sys::CUresult::CUDA_SUCCESS {
            return Err(format!("cuMemAlloc_v2({} bytes) failed: {:?}", bytes, err));
        }
        Ok(Self {
            ptr,
            len: count,
            device_ordinal: dev,
            _phantom: std::marker::PhantomData,
        })
    }

    pub fn alloc_zeroed(count: usize) -> Result<Self, String> {
        let buf = Self::alloc_uninit(count)?;
        let bytes = count * std::mem::size_of::<T>();
        if bytes == 0 {
            return Ok(buf);
        }
        let err = unsafe { cuda_sys::lib().cuMemsetD8_v2(buf.ptr, 0, bytes) };
        if err != cuda_sys::CUresult::CUDA_SUCCESS {
            unsafe {
                cuda_sys::lib().cuMemFree_v2(buf.ptr);
            }
            return Err(format!("cuMemsetD8({} bytes) failed: {:?}", bytes, err));
        }
        Ok(buf)
    }

    /// Compatible with CudaSlice::device_ptr() — returns &u64 so *buf.device_ptr() works.
    pub fn device_ptr(&self) -> &u64 {
        &self.ptr
    }

    pub fn len(&self) -> usize {
        self.len
    }
}

impl<T: Copy> Drop for GpuBuf<T> {
    fn drop(&mut self) {
        if self.ptr != 0 {
            unsafe {
                // Retain the primary context for this device and make it current,
                // so cuMemFree_v2 works regardless of which thread we're on.
                let mut ctx: cuda_sys::CUcontext = std::ptr::null_mut();
                cuda_sys::lib().cuDevicePrimaryCtxRetain(&mut ctx, self.device_ordinal);
                cuda_sys::lib().cuCtxSetCurrent(ctx);
                cuda_sys::lib().cuMemFree_v2(self.ptr);
                cuda_sys::lib().cuDevicePrimaryCtxRelease_v2(self.device_ordinal);
            }
            self.ptr = 0;
        }
    }
}

