fn prefill_device_trace_f32_json(bits_word: u64) -> serde_json::Value {
    let value = f32::from_bits((bits_word & 0xffff_ffff) as u32);
    if value.is_nan() {
        serde_json::json!("NaN")
    } else if value == f32::INFINITY {
        serde_json::json!("Infinity")
    } else if value == f32::NEG_INFINITY {
        serde_json::json!("-Infinity")
    } else {
        serde_json::json!(value as f64)
    }
}

fn prefill_device_trace_f32_bits_hex(bits_word: u64) -> String {
    format!("0x{:08x}", bits_word & 0xffff_ffff)
}

fn prefill_device_trace_f32_bf16_bits_hex(bits_word: u64) -> String {
    let value = f32::from_bits((bits_word & 0xffff_ffff) as u32);
    format!("0x{:04x}", half::bf16::from_f32(value).to_bits())
}

fn prefill_device_trace_f32_bf16_value_json(bits_word: u64) -> serde_json::Value {
    let value = f32::from_bits((bits_word & 0xffff_ffff) as u32);
    let bf16_value = half::bf16::from_f32(value).to_f32();
    serde_json::json!(bf16_value as f64)
}

fn prefill_device_trace_bf16_rounding_json(bits_word: u64) -> serde_json::Value {
    let raw = (bits_word & 0xffff_ffff) as u32;
    let value = f32::from_bits(raw);
    if !value.is_finite() {
        return serde_json::json!({
            "f32_bits_hex": format!("0x{:08x}", raw),
            "available": false,
            "reason": "non-finite FP32 value",
        });
    }

    let truncated = (raw >> 16) as u16;
    let next_bits = truncated.wrapping_add(1);
    let truncated_value = half::bf16::from_bits(truncated).to_f32();
    let next_value = half::bf16::from_bits(next_bits).to_f32();
    let midpoint = (truncated_value + next_value) * 0.5;
    let midpoint_bits = midpoint.to_bits();
    let tie_rounds_to = if (truncated & 1) == 0 {
        truncated
    } else {
        next_bits
    };
    let side = if value < midpoint {
        "below_midpoint"
    } else if value > midpoint {
        "above_midpoint"
    } else {
        "at_midpoint"
    };

    serde_json::json!({
        "f32_bits_hex": format!("0x{:08x}", raw),
        "truncated_bf16_bits": format!("0x{:04x}", truncated),
        "truncated_bf16_value": truncated_value as f64,
        "next_bf16_bits": format!("0x{:04x}", next_bits),
        "next_bf16_value": next_value as f64,
        "midpoint_f32_bits": format!("0x{:08x}", midpoint_bits),
        "midpoint_value": midpoint as f64,
        "value_vs_midpoint": side,
        "tie_rounds_to_bf16_bits": format!("0x{:04x}", tie_rounds_to),
    })
}

fn prefill_device_trace_bf16_json(bits_word: u64) -> serde_json::Value {
    let value = half::bf16::from_bits((bits_word & 0xffff) as u16).to_f32();
    serde_json::json!(value as f64)
}

/// PTX source for prefill kernels (compiled by build.rs).
