/// Matches sglang::ScalarType memory layout for FFI.
#[repr(C)]
#[derive(Clone, Copy)]
pub struct ScalarType {
    pub exponent: u8,
    pub mantissa: u8,
    pub is_signed: u8,
    pub _pad0: u8,
    pub bias: i32,
    pub finite_values_only: u8,
    pub nan_repr: u8,
    pub _pad1: [u8; 2],
}

impl ScalarType {
    pub const U4: ScalarType = ScalarType {
        exponent: 0,
        mantissa: 4,
        is_signed: 0,
        _pad0: 0,
        bias: 0,
        finite_values_only: 0,
        nan_repr: 1,
        _pad1: [0; 2], // nan_repr=1 = NAN_IEEE_754
    };
    pub const U8: ScalarType = ScalarType {
        exponent: 0,
        mantissa: 8,
        is_signed: 0,
        _pad0: 0,
        bias: 0,
        finite_values_only: 0,
        nan_repr: 1,
        _pad1: [0; 2], // nan_repr=1 = NAN_IEEE_754
    };
    pub const U4B8: ScalarType = ScalarType {
        exponent: 0,
        mantissa: 4,
        is_signed: 0,
        _pad0: 0,
        bias: 8,
        finite_values_only: 0,
        nan_repr: 1,
        _pad1: [0; 2], // nan_repr=1 = NAN_IEEE_754
    };
    pub const U8B128: ScalarType = ScalarType {
        exponent: 0,
        mantissa: 8,
        is_signed: 0,
        _pad0: 0,
        bias: 128,
        finite_values_only: 0,
        nan_repr: 1,
        _pad1: [0; 2], // nan_repr=1 = NAN_IEEE_754
    };
}

