const DSA_PREFILL_SELECTION_TIMING_QUERY: usize = 0;
const DSA_PREFILL_SELECTION_TIMING_SCORES: usize = 1;
const DSA_PREFILL_SELECTION_TIMING_BASE_SORT: usize = 2;
const DSA_PREFILL_SELECTION_TIMING_MERGE: usize = 3;
const DSA_PREFILL_SELECTION_TIMING_STAGES: usize = 4;
const DSA_PREFILL_RADIX_CAPACITY: usize = 256 * 4;

#[derive(Clone, Copy)]
struct DsaPrefillSelectionTimingEvents {
    start: cuda_sys::CUevent,
    stop: cuda_sys::CUevent,
}

struct DsaPrefillSelectionTiming {
    wall_ms: [f64; DSA_PREFILL_SELECTION_TIMING_STAGES],
    event_ms: [f64; DSA_PREFILL_SELECTION_TIMING_STAGES],
    sync_ms: [f64; DSA_PREFILL_SELECTION_TIMING_STAGES],
    calls: [u64; DSA_PREFILL_SELECTION_TIMING_STAGES],
}

impl Default for DsaPrefillSelectionTiming {
    fn default() -> Self {
        Self {
            wall_ms: [0.0; DSA_PREFILL_SELECTION_TIMING_STAGES],
            event_ms: [0.0; DSA_PREFILL_SELECTION_TIMING_STAGES],
            sync_ms: [0.0; DSA_PREFILL_SELECTION_TIMING_STAGES],
            calls: [0; DSA_PREFILL_SELECTION_TIMING_STAGES],
        }
    }
}

fn dsa_prefill_selection_timing_start(
    events: Option<DsaPrefillSelectionTimingEvents>,
    stream: cuda_sys::CUstream,
    label: &str,
) -> Result<Option<Instant>, String> {
    let Some(events) = events else {
        return Ok(None);
    };
    if events.start.is_null() || events.stop.is_null() {
        return Ok(None);
    }
    unsafe {
        let err = cuda_sys::lib().cuEventRecord(events.start, stream);
        if err != cuda_sys::CUresult::CUDA_SUCCESS {
            return Err(format!("record {label} timing start event: {:?}", err));
        }
    }
    Ok(Some(Instant::now()))
}

fn dsa_prefill_selection_timing_finish(
    events: Option<DsaPrefillSelectionTimingEvents>,
    started: Option<Instant>,
    stream: cuda_sys::CUstream,
    stage: usize,
    label: &str,
    timing: &mut DsaPrefillSelectionTiming,
) -> Result<(), String> {
    let Some(started) = started else {
        return Ok(());
    };
    let events = events.ok_or_else(|| format!("{label} timing events disappeared"))?;
    let sync_t0 = Instant::now();
    unsafe {
        let stop_err = cuda_sys::lib().cuEventRecord(events.stop, stream);
        if stop_err != cuda_sys::CUresult::CUDA_SUCCESS {
            return Err(format!("record {label} timing stop event: {:?}", stop_err));
        }
        let sync_err = cuda_sys::lib().cuStreamSynchronize(stream);
        if sync_err != cuda_sys::CUresult::CUDA_SUCCESS {
            return Err(format!("synchronize {label} timing stream: {:?}", sync_err));
        }
    }
    let sync_ms = sync_t0.elapsed().as_secs_f64() * 1000.0;
    let mut event_ms = 0.0f32;
    unsafe {
        let elapsed_err =
            cuda_sys::lib().cuEventElapsedTime(&mut event_ms, events.start, events.stop);
        if elapsed_err != cuda_sys::CUresult::CUDA_SUCCESS {
            return Err(format!("elapsed {label} timing event: {:?}", elapsed_err));
        }
    }
    if stage < DSA_PREFILL_SELECTION_TIMING_STAGES {
        timing.wall_ms[stage] += started.elapsed().as_secs_f64() * 1000.0;
        timing.event_ms[stage] += event_ms as f64;
        timing.sync_ms[stage] += sync_ms;
        timing.calls[stage] += 1;
    }
    Ok(())
}

pub(crate) struct DsaPrefillRequestWorkspace {
    max_chunk_rows: usize,
    max_context_end: usize,
    max_selected_per_row: usize,
    selection_workspace_capacity_bytes: usize,
    index_n_heads: usize,
    index_head_dim: usize,
    configured_topk: usize,
    output_topk: usize,
    context_divisor: usize,
    causal_context_row_span: usize,
    d_rope_queries: GpuBuf<u16>,
    d_selection_workspace: GpuBuf<u8>,
    d_selected_indices: GpuBuf<i32>,
    d_pool_selected_indices: Option<GpuBuf<i32>>,
    mla_num_heads: usize,
    mla_ckv_cache_dim: usize,
    d_mla_q_absorbed: GpuBuf<f32>,
    d_mla_attention: GpuBuf<f32>,
    active_owner_layer_idx: Cell<Option<usize>>,
    active_chunk_start: Cell<usize>,
    active_chunk_rows: Cell<usize>,
    active_context_end: Cell<usize>,
    active_selected_per_row: Cell<usize>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct DsaPrefillSelectedIndexView {
    owner_layer_idx: usize,
    ptr: u64,
    rows: usize,
    selected_per_row: usize,
    context_end: usize,
}

impl DsaPrefillRequestWorkspace {
    fn allocate(
        chunk_rows: usize,
        context_end: usize,
        configured_topk: usize,
        output_topk: usize,
        context_divisor: usize,
        causal_context_row_span: usize,
        index_n_heads: usize,
        index_head_dim: usize,
        mla_num_heads: usize,
        mla_ckv_cache_dim: usize,
        workspace_capacity_bytes: usize,
    ) -> Result<Self, String> {
        if index_n_heads == 0 || index_head_dim == 0 {
            return Err(format!(
                "DSA prefill workspace requires positive query geometry, got heads={} head_dim={}",
                index_n_heads, index_head_dim
            ));
        }
        if output_topk < configured_topk || context_divisor == 0 || causal_context_row_span == 0 {
            return Err(format!(
                "DSA prefill workspace has invalid selection geometry score_topk={} output_topk={} position_divisor={} causal_row_span={}",
                configured_topk, output_topk, context_divisor, causal_context_row_span
            ));
        }
        if (mla_num_heads == 0) != (mla_ckv_cache_dim == 0) {
            return Err(format!(
                "DSA prefill MLA workspace requires both heads and cKV width or neither, got heads={} ckv={}",
                mla_num_heads, mla_ckv_cache_dim
            ));
        }
        let plan = plan_dsa_prefill_selection(
            chunk_rows,
            context_end,
            configured_topk,
            workspace_capacity_bytes,
            1,
            causal_context_row_span,
        )?;
        let query_elements = chunk_rows
            .checked_mul(index_n_heads)
            .and_then(|value| value.checked_mul(index_head_dim))
            .ok_or_else(|| "DSA prefill query workspace size overflow".to_string())?;
        let mla_elements = chunk_rows
            .checked_mul(mla_num_heads)
            .and_then(|value| value.checked_mul(mla_ckv_cache_dim))
            .ok_or_else(|| "DSA prefill MLA workspace size overflow".to_string())?;
        Ok(Self {
            max_chunk_rows: chunk_rows,
            max_context_end: context_end,
            max_selected_per_row: plan.selected_per_row,
            selection_workspace_capacity_bytes: workspace_capacity_bytes,
            index_n_heads,
            index_head_dim,
            configured_topk,
            output_topk,
            context_divisor,
            causal_context_row_span,
            d_rope_queries: GpuBuf::alloc_zeroed(query_elements)
                .map_err(|error| format!("alloc DSA prefill RoPE queries: {error}"))?,
            d_selection_workspace: GpuBuf::alloc_zeroed(workspace_capacity_bytes)
                .map_err(|error| format!("alloc DSA prefill selection workspace: {error}"))?,
            d_selected_indices: GpuBuf::alloc_zeroed(
                chunk_rows
                    .checked_mul(output_topk)
                    .ok_or_else(|| "DSA prefill raw selected-index size overflow".to_string())?,
            )
            .map_err(|error| format!("alloc DSA prefill selected indices: {error}"))?,
            d_pool_selected_indices: if context_divisor > 1 {
                Some(
                    GpuBuf::alloc_zeroed(plan.selection_elements).map_err(|error| {
                        format!("alloc DSA prefill pooled selected indices: {error}")
                    })?,
                )
            } else {
                None
            },
            mla_num_heads,
            mla_ckv_cache_dim,
            d_mla_q_absorbed: GpuBuf::alloc_zeroed(mla_elements)
                .map_err(|error| format!("alloc DSA prefill absorbed queries: {error}"))?,
            d_mla_attention: GpuBuf::alloc_zeroed(mla_elements)
                .map_err(|error| format!("alloc DSA prefill MLA attention: {error}"))?,
            active_owner_layer_idx: Cell::new(None),
            active_chunk_start: Cell::new(0),
            active_chunk_rows: Cell::new(0),
            active_context_end: Cell::new(0),
            active_selected_per_row: Cell::new(0),
        })
    }

    fn mark_owner_result(
        &self,
        owner_layer_idx: usize,
        chunk_start: usize,
        chunk_rows: usize,
        context_end: usize,
        selected_per_row: usize,
    ) {
        self.active_owner_layer_idx.set(Some(owner_layer_idx));
        self.active_chunk_start.set(chunk_start);
        self.active_chunk_rows.set(chunk_rows);
        self.active_context_end.set(context_end);
        self.active_selected_per_row.set(selected_per_row);
    }

    fn resolve_for_layer(
        &self,
        layer_idx: usize,
        registration: DsaPrefillLayerDescriptor,
        chunk_start: usize,
        chunk_rows: usize,
        context_end: usize,
    ) -> Result<DsaPrefillSelectedIndexView, String> {
        let active_owner = self.active_owner_layer_idx.get().ok_or_else(|| {
            format!(
                "DSA prefill layer {} has no active owner selection for this chunk",
                layer_idx
            )
        })?;
        if active_owner != registration.owner_layer_idx
            || self.active_chunk_start.get() != chunk_start
            || self.active_chunk_rows.get() != chunk_rows
            || self.active_context_end.get() != context_end
        {
            return Err(format!(
                "DSA prefill layer {} IndexShare state mismatch: expected owner={} chunk=[{}, {}) context={}, active owner={} chunk=[{}, {}) context={}",
                layer_idx,
                registration.owner_layer_idx,
                chunk_start,
                chunk_start.saturating_add(chunk_rows),
                context_end,
                active_owner,
                self.active_chunk_start.get(),
                self.active_chunk_start
                    .get()
                    .saturating_add(self.active_chunk_rows.get()),
                self.active_context_end.get(),
            ));
        }
        let (score_topk, output_topk, context_divisor) =
            registration.workspace_selection_geometry()?;
        if score_topk != self.configured_topk
            || output_topk != self.output_topk
            || context_divisor != self.context_divisor
            || registration.index_n_heads != self.index_n_heads
            || registration.index_head_dim != self.index_head_dim
        {
            return Err(format!(
                "DSA prefill layer {} IndexShare geometry differs from active owner {}: registration score/output/divisor={}/{}/{} heads={} head_dim={}, workspace={}/{}/{} heads={} head_dim={}",
                layer_idx,
                active_owner,
                score_topk,
                output_topk,
                context_divisor,
                registration.index_n_heads,
                registration.index_head_dim,
                self.configured_topk,
                self.output_topk,
                self.context_divisor,
                self.index_n_heads,
                self.index_head_dim,
            ));
        }
        Ok(DsaPrefillSelectedIndexView {
            owner_layer_idx: active_owner,
            ptr: *self.d_selected_indices.device_ptr(),
            rows: self.active_chunk_rows.get(),
            selected_per_row: self.active_selected_per_row.get(),
            context_end: self.active_context_end.get(),
        })
    }
}

extern "C" fn dsa_prefill_zero_dynamic_smem_for_occupancy(_: std::ffi::c_int) -> usize {
    0
}

fn dsa_prefill_occupancy_launch(
    kernel: RawCuFunc,
    dynamic_shared_bytes: usize,
    work_items: usize,
    label: &str,
) -> Result<(u32, u32), String> {
    if work_items == 0 {
        return Err(format!("{label} requires positive work_items"));
    }
    let mut minimum_grid = 0i32;
    let mut block_threads = 0i32;
    let result = unsafe {
        cuda_sys::lib().cuOccupancyMaxPotentialBlockSize(
            &mut minimum_grid,
            &mut block_threads,
            kernel.0,
            Some(dsa_prefill_zero_dynamic_smem_for_occupancy),
            dynamic_shared_bytes,
            0,
        )
    };
    if result != cuda_sys::CUresult::CUDA_SUCCESS {
        return Err(format!(
            "query {label} occupancy for {} shared bytes: {:?}",
            dynamic_shared_bytes, result
        ));
    }
    if minimum_grid <= 0 || block_threads <= 0 {
        return Err(format!(
            "{label} occupancy returned invalid grid/block {minimum_grid}/{block_threads}"
        ));
    }
    let grid = usize::try_from(minimum_grid)
        .map_err(|_| format!("{label} minimum grid is negative"))?
        .min(work_items)
        .max(1);
    Ok((
        u32::try_from(grid).map_err(|_| format!("{label} grid {grid} exceeds u32"))?,
        u32::try_from(block_threads)
            .map_err(|_| format!("{label} block {block_threads} exceeds u32"))?,
    ))
}

fn dsa_prefill_configure_dynamic_shared(
    kernel: RawCuFunc,
    dynamic_shared_bytes: usize,
    label: &str,
) -> Result<u32, String> {
    let mut device = 0;
    let current_device = unsafe { cuda_sys::lib().cuCtxGetDevice(&mut device) };
    if current_device != cuda_sys::CUresult::CUDA_SUCCESS {
        return Err(format!(
            "query {label} active CUDA device: {:?}",
            current_device
        ));
    }
    let mut default_limit = 0i32;
    let default_result = unsafe {
        cuda_sys::lib().cuDeviceGetAttribute(
            &mut default_limit,
            cuda_sys::CUdevice_attribute_enum::CU_DEVICE_ATTRIBUTE_MAX_SHARED_MEMORY_PER_BLOCK,
            device,
        )
    };
    if default_result != cuda_sys::CUresult::CUDA_SUCCESS {
        return Err(format!(
            "query {label} default shared-memory limit: {:?}",
            default_result
        ));
    }
    let mut optin_limit = 0i32;
    let optin_result = unsafe {
        cuda_sys::lib().cuDeviceGetAttribute(
            &mut optin_limit,
            cuda_sys::CUdevice_attribute_enum::CU_DEVICE_ATTRIBUTE_MAX_SHARED_MEMORY_PER_BLOCK_OPTIN,
            device,
        )
    };
    if optin_result != cuda_sys::CUresult::CUDA_SUCCESS {
        return Err(format!(
            "query {label} opt-in shared-memory limit: {:?}",
            optin_result
        ));
    }
    let default_limit = usize::try_from(default_limit.max(0))
        .map_err(|_| format!("{label} default shared-memory limit is invalid"))?;
    let optin_limit = usize::try_from(optin_limit.max(0))
        .map_err(|_| format!("{label} opt-in shared-memory limit is invalid"))?;
    if dynamic_shared_bytes > optin_limit {
        return Err(format!(
            "{label} requires {dynamic_shared_bytes} shared-memory bytes but active CUDA device {device} supports {optin_limit} opt-in bytes"
        ));
    }
    if dynamic_shared_bytes > default_limit {
        let requested = i32::try_from(dynamic_shared_bytes)
            .map_err(|_| format!("{label} shared-memory request exceeds i32"))?;
        let attribute_result = unsafe {
            cuda_sys::lib().cuFuncSetAttribute(
                kernel.0,
                cuda_sys::CUfunction_attribute_enum::CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES,
                requested,
            )
        };
        if attribute_result != cuda_sys::CUresult::CUDA_SUCCESS {
            return Err(format!(
                "configure {label} for {dynamic_shared_bytes} shared-memory bytes: {:?}",
                attribute_result
            ));
        }
    }
    u32::try_from(dynamic_shared_bytes)
        .map_err(|_| format!("{label} shared-memory bytes exceed u32"))
}

#[allow(clippy::too_many_arguments)]
fn launch_dsa_prefill_gemm_scores(
    kernels: DsaPrefillSelectionKernels,
    stream: cuda_sys::CUstream,
    cublas_handle: cudarc::cublas::sys::cublasHandle_t,
    cublas_workspace_ptr: u64,
    cublas_workspace_bytes: usize,
    key_cache_ptr: u64,
    rope_queries_ptr: u64,
    head_weights_ptr: u64,
    positions_ptr: u64,
    rows: usize,
    context_end: usize,
    index_n_heads: usize,
    index_head_dim: usize,
    score_scale: f32,
    temporary_is_bf16: bool,
    causal_position_start: usize,
    causal_position_divisor: usize,
    causal_context_row_span: usize,
    causal_band_rows: usize,
    buffers: DsaPrefillSelectionBuffers,
) -> Result<(), String> {
    use cudarc::cublas::result as cublas_result;
    use cudarc::cublas::sys as cublas_sys;

    if cublas_handle.is_null() || cublas_workspace_ptr == 0 || cublas_workspace_bytes == 0 {
        return Err(format!(
            "DSA prefill GEMM scores require a fail-closed cuBLAS handle/workspace, got handle_null={} workspace=0x{:x}/{}",
            cublas_handle.is_null(), cublas_workspace_ptr, cublas_workspace_bytes
        ));
    }
    let output_score_elements = rows
        .checked_mul(context_end)
        .ok_or_else(|| "DSA prefill GEMM score element count overflow".to_string())?;
    if buffers.score_temp_ptr == 0 || output_score_elements > buffers.score_temp_capacity {
        return Err(format!(
            "DSA prefill GEMM temporary score capacity {} < required {} or pointer is null",
            buffers.score_temp_capacity, output_score_elements
        ));
    }
    let causal_bands_enabled = causal_band_rows > 0;
    if causal_bands_enabled && (causal_position_divisor == 0 || causal_context_row_span == 0) {
        return Err(format!(
            "DSA prefill causal GEMM requires positive position divisor and causal row span when banding is enabled, got divisor={} row_span={} band_rows={}",
            causal_position_divisor, causal_context_row_span, causal_band_rows
        ));
    }
    let output_context_i32 = i32::try_from(context_end)
        .map_err(|_| format!("DSA prefill GEMM output context {context_end} exceeds i32"))?;
    let heads_i32 = i32::try_from(index_n_heads)
        .map_err(|_| format!("DSA prefill GEMM heads {index_n_heads} exceed i32"))?;
    let head_dim_i32 = i32::try_from(index_head_dim)
        .map_err(|_| format!("DSA prefill GEMM head dimension {index_head_dim} exceeds i32"))?;
    let query_row_stride = index_n_heads
        .checked_mul(index_head_dim)
        .ok_or_else(|| "DSA prefill GEMM query row stride overflow".to_string())?;
    let query_row_stride_i32 = i32::try_from(query_row_stride)
        .map_err(|_| format!("DSA prefill GEMM query row stride {query_row_stride} exceeds i32"))?;

    let trace_geometry_vram = if vram_ledger_enabled() {
        static TRACED_GEOMETRIES: std::sync::OnceLock<
            std::sync::Mutex<std::collections::HashSet<(usize, usize)>>,
        > = std::sync::OnceLock::new();
        TRACED_GEOMETRIES
            .get_or_init(|| std::sync::Mutex::new(std::collections::HashSet::new()))
            .lock()
            .map_err(|_| "DSA prefill GEMM VRAM geometry ledger lock poisoned".to_string())?
            .insert((rows, context_end))
    } else {
        false
    };
    let sample_vram = |phase: &str| -> Result<(), String> {
        if !trace_geometry_vram {
            return Ok(());
        }
        let mut free_bytes = 0usize;
        let mut total_bytes = 0usize;
        unsafe {
            let sync = cuda_sys::lib().cuCtxSynchronize();
            if sync != cuda_sys::CUresult::CUDA_SUCCESS {
                return Err(format!(
                    "DSA prefill GEMM VRAM ledger sync failed at {phase}: {sync:?}"
                ));
            }
            let info = cuda_sys::lib().cuMemGetInfo_v2(&mut free_bytes, &mut total_bytes);
            if info != cuda_sys::CUresult::CUDA_SUCCESS {
                return Err(format!(
                    "DSA prefill GEMM VRAM ledger query failed at {phase}: {info:?}"
                ));
            }
        }
        vram_ledger_log!(
            "VRAM LEDGER dsa_index_score_gemm_geometry rows={} context_end={} phase={} free_bytes={} free_mb={:.3} total_mb={:.3}",
            rows,
            context_end,
            phase,
            free_bytes,
            free_bytes as f64 / (1024.0 * 1024.0),
            total_bytes as f64 / (1024.0 * 1024.0),
        );
        Ok(())
    };

    sample_vram("before_set_workspace")?;

    let lib = unsafe { cublas_sys::lib() };
    let set_workspace = unsafe {
        lib.cublasSetWorkspace_v2(
            cublas_handle,
            cublas_workspace_ptr as *mut std::ffi::c_void,
            cublas_workspace_bytes,
        )
    };
    if set_workspace != cublas_sys::cublasStatus_t::CUBLAS_STATUS_SUCCESS {
        return Err(format!(
            "DSA prefill GEMM cublasSetWorkspace failed: {set_workspace:?} bytes={cublas_workspace_bytes}"
        ));
    }
    sample_vram("after_set_workspace")?;

    let run_result = (|| -> Result<(), String> {
        unsafe {
            cublas_result::set_stream(cublas_handle, stream as cublas_sys::cudaStream_t)
                .map_err(|error| format!("DSA prefill GEMM set_stream: {error:?}"))?;
        }
        let alpha = score_scale;
        let beta = 0.0f32;
        let epilogue_block = 256u32;
        let query_row_bytes = query_row_stride
            .checked_mul(std::mem::size_of::<u16>())
            .ok_or_else(|| "DSA prefill GEMM query row-byte size overflow".to_string())?;
        let head_weight_row_bytes = index_n_heads
            .checked_mul(std::mem::size_of::<u16>())
            .ok_or_else(|| "DSA prefill GEMM weight row-byte size overflow".to_string())?;
        let output_row_bytes = context_end
            .checked_mul(std::mem::size_of::<f32>())
            .ok_or_else(|| "DSA prefill GEMM output row-byte size overflow".to_string())?;
        let band_row_limit = if causal_bands_enabled {
            causal_band_rows.min(rows)
        } else {
            rows
        };
        let mut band_row_start = 0usize;
        while band_row_start < rows {
            let band_rows = (rows - band_row_start).min(band_row_limit);
            let score_context_end = if causal_bands_enabled {
                causal_position_start
                    .checked_add(band_row_start)
                    .and_then(|value| value.checked_add(band_rows))
                    .ok_or_else(|| "DSA prefill causal GEMM position overflow".to_string())?
                    / causal_context_row_span
            } else {
                context_end
            }
            .min(context_end);
            if score_context_end == 0 {
                return Err(format!(
                    "DSA prefill causal GEMM band [{}, {}) has no causal compressed rows (position_start={} row_span={})",
                    band_row_start,
                    band_row_start + band_rows,
                    causal_position_start,
                    causal_context_row_span
                ));
            }
            let band_score_elements = band_rows
                .checked_mul(score_context_end)
                .ok_or_else(|| "DSA prefill GEMM band score size overflow".to_string())?;
            if band_score_elements > buffers.score_temp_capacity {
                return Err(format!(
                    "DSA prefill GEMM temporary score capacity {} < causal band requirement {}",
                    buffers.score_temp_capacity, band_score_elements
                ));
            }
            let band_rows_i32 = i32::try_from(band_rows)
                .map_err(|_| format!("DSA prefill GEMM band rows {band_rows} exceed i32"))?;
            let score_context_i32 = i32::try_from(score_context_end).map_err(|_| {
                format!("DSA prefill GEMM score context {score_context_end} exceeds i32")
            })?;
            let epilogue_grid =
                u32::try_from(band_score_elements.div_ceil(epilogue_block as usize))
                    .map_err(|_| "DSA prefill GEMM epilogue grid exceeds u32".to_string())?;
            let query_band_ptr = rope_queries_ptr
                .checked_add(
                    u64::try_from(band_row_start.checked_mul(query_row_bytes).ok_or_else(
                        || "DSA prefill GEMM query band offset overflow".to_string(),
                    )?)
                    .map_err(|_| "DSA prefill GEMM query band offset exceeds u64".to_string())?,
                )
                .ok_or_else(|| "DSA prefill GEMM query band pointer overflow".to_string())?;
            let head_weights_band_ptr = head_weights_ptr
                .checked_add(
                    u64::try_from(
                        band_row_start
                            .checked_mul(head_weight_row_bytes)
                            .ok_or_else(|| {
                                "DSA prefill GEMM weight band offset overflow".to_string()
                            })?,
                    )
                    .map_err(|_| "DSA prefill GEMM weight band offset exceeds u64".to_string())?,
                )
                .ok_or_else(|| "DSA prefill GEMM weight band pointer overflow".to_string())?;
            let positions_band_ptr = positions_ptr
                .checked_add(
                    u64::try_from(
                        band_row_start
                            .checked_mul(std::mem::size_of::<i32>())
                            .ok_or_else(|| {
                                "DSA prefill GEMM position band offset overflow".to_string()
                            })?,
                    )
                    .map_err(|_| "DSA prefill GEMM position band offset exceeds u64".to_string())?,
                )
                .ok_or_else(|| "DSA prefill GEMM position band pointer overflow".to_string())?;
            let output_band_ptr = buffers
                .scores_ptr
                .checked_add(
                    u64::try_from(band_row_start.checked_mul(output_row_bytes).ok_or_else(
                        || "DSA prefill GEMM output band offset overflow".to_string(),
                    )?)
                    .map_err(|_| "DSA prefill GEMM output band offset exceeds u64".to_string())?,
                )
                .ok_or_else(|| "DSA prefill GEMM output band pointer overflow".to_string())?;
            let head_score_batch_capacity = buffers.score_temp_capacity / band_score_elements;
            if head_score_batch_capacity == 0 {
                return Err(format!(
                    "DSA prefill GEMM temporary score capacity {} cannot hold one band of {} elements",
                    buffers.score_temp_capacity, band_score_elements
                ));
            }
            let head_score_batch_capacity = head_score_batch_capacity.min(index_n_heads);
            let head_score_batch_stride = i64::try_from(band_score_elements).map_err(|_| {
                "DSA prefill GEMM temporary head-batch stride exceeds i64".to_string()
            })?;
            let mut head_start = 0usize;
            while head_start < index_n_heads {
                let head_count = (index_n_heads - head_start).min(head_score_batch_capacity);
                let query_head_ptr = query_band_ptr
                    .checked_add(
                        u64::try_from(
                            head_start
                                .checked_mul(index_head_dim)
                                .and_then(|elements| {
                                    elements.checked_mul(std::mem::size_of::<u16>())
                                })
                                .ok_or_else(|| {
                                    "DSA prefill GEMM query-head offset overflow".to_string()
                                })?,
                        )
                        .map_err(|_| {
                            "DSA prefill GEMM query-head offset exceeds u64".to_string()
                        })?,
                    )
                    .ok_or_else(|| "DSA prefill GEMM query-head pointer overflow".to_string())?;
                let head_count_i32 = i32::try_from(head_count)
                    .map_err(|_| format!("DSA prefill GEMM head batch {head_count} exceeds i32"))?;
                unsafe {
                    cublas_result::gemm_strided_batched_ex(
                        cublas_handle,
                        cublas_sys::cublasOperation_t::CUBLAS_OP_T,
                        cublas_sys::cublasOperation_t::CUBLAS_OP_N,
                        score_context_i32,
                        band_rows_i32,
                        head_dim_i32,
                        &alpha as *const f32 as *const std::ffi::c_void,
                        key_cache_ptr as *const std::ffi::c_void,
                        cublas_sys::cudaDataType::CUDA_R_16BF,
                        head_dim_i32,
                        0,
                        query_head_ptr as *const std::ffi::c_void,
                        cublas_sys::cudaDataType::CUDA_R_16BF,
                        query_row_stride_i32,
                        i64::try_from(index_head_dim).map_err(|_| {
                            "DSA prefill GEMM query head stride exceeds i64".to_string()
                        })?,
                        &beta as *const f32 as *const std::ffi::c_void,
                        buffers.score_temp_ptr as *mut std::ffi::c_void,
                        if temporary_is_bf16 {
                            cublas_sys::cudaDataType::CUDA_R_16BF
                        } else {
                            cublas_sys::cudaDataType::CUDA_R_32F
                        },
                        score_context_i32,
                        head_score_batch_stride,
                        head_count_i32,
                        cublas_sys::cublasComputeType_t::CUBLAS_COMPUTE_32F,
                        cublas_sys::cublasGemmAlgo_t::CUBLAS_GEMM_DEFAULT,
                    )
                    .map_err(|error| {
                        format!(
                            "DSA prefill BF16/FP32 GEMM failed at band [{}, {}) context={} heads [{}, {})/{}: {:?}",
                            band_row_start,
                            band_row_start + band_rows,
                            score_context_end,
                            head_start,
                            head_start + head_count,
                            index_n_heads,
                            error
                        )
                    })?;
                }
                let mut e0 = output_band_ptr;
                let mut e1 = buffers.score_temp_ptr;
                let mut e2 = head_weights_band_ptr;
                let mut e3 = positions_band_ptr;
                let mut e4 = band_rows_i32;
                let mut e5 = output_context_i32;
                let mut e6 = score_context_i32;
                let mut e7 = heads_i32;
                let mut e8 = i32::try_from(head_start)
                    .map_err(|_| format!("DSA prefill GEMM head {head_start} exceeds i32"))?;
                let mut e9 = head_count_i32;
                let mut e10 = i32::try_from(band_score_elements).map_err(|_| {
                    "DSA prefill GEMM epilogue head-score stride exceeds i32".to_string()
                })?;
                let mut e11 = if head_start == 0 { 1i32 } else { 0i32 };
                let mut e12 = i32::from(temporary_is_bf16);
                let mut e13 = i32::try_from(causal_position_divisor.max(1)).map_err(|_| {
                    "DSA prefill GEMM causal position divisor exceeds i32".to_string()
                })?;
                unsafe {
                    launch(
                        kernels.accumulate_gemm_scores,
                        (epilogue_grid, 1, 1),
                        (epilogue_block, 1, 1),
                        0,
                        stream,
                        &mut [
                            &mut e0 as *mut _ as *mut _,
                            &mut e1 as *mut _ as *mut _,
                            &mut e2 as *mut _ as *mut _,
                            &mut e3 as *mut _ as *mut _,
                            &mut e4 as *mut _ as *mut _,
                            &mut e5 as *mut _ as *mut _,
                            &mut e6 as *mut _ as *mut _,
                            &mut e7 as *mut _ as *mut _,
                            &mut e8 as *mut _ as *mut _,
                            &mut e9 as *mut _ as *mut _,
                            &mut e10 as *mut _ as *mut _,
                            &mut e11 as *mut _ as *mut _,
                            &mut e12 as *mut _ as *mut _,
                            &mut e13 as *mut _ as *mut _,
                        ],
                    )?;
                }
                if band_row_start == 0 && head_start == 0 {
                    sample_vram("after_first_head")?;
                }
                head_start += head_count;
            }
            band_row_start += band_rows;
        }
        sample_vram("after_all_heads")?;
        Ok(())
    })();

    let restore_workspace =
        unsafe { lib.cublasSetWorkspace_v2(cublas_handle, std::ptr::null_mut(), 0) };
    if restore_workspace != cublas_sys::cublasStatus_t::CUBLAS_STATUS_SUCCESS {
        return Err(format!(
            "DSA prefill GEMM failed to restore cuBLAS workspace: {restore_workspace:?}; operation={run_result:?}"
        ));
    }
    sample_vram("after_restore_workspace")?;
    run_result
}

#[allow(clippy::too_many_arguments)]
fn launch_dsa_prefill_selection_rows(
    kernels: DsaPrefillSelectionKernels,
    stream: cuda_sys::CUstream,
    raw_queries_ptr: u64,
    rope_queries_ptr: u64,
    key_cache_ptr: u64,
    head_weights_ptr: u64,
    positions_ptr: u64,
    rope_cos_ptr: u64,
    rope_sin_ptr: u64,
    rows: usize,
    context_end: usize,
    index_n_heads: usize,
    index_head_dim: usize,
    qk_rope_head_dim: usize,
    configured_topk: usize,
    score_scale: f32,
    causal_position_start: usize,
    causal_position_divisor: usize,
    causal_context_row_span: usize,
    index_score_mode: DeepseekV4PrefillIndexScoreMode,
    topk_mode: DeepseekV4PrefillTopkMode,
    cublas_handle: cudarc::cublas::sys::cublasHandle_t,
    cublas_workspace_ptr: u64,
    cublas_workspace_bytes: usize,
    buffers: DsaPrefillSelectionBuffers,
    timing_events: Option<DsaPrefillSelectionTimingEvents>,
    timing: &mut DsaPrefillSelectionTiming,
) -> Result<crate::gpu_decode::DsaTopkPlan, String> {
    if rows == 0 || context_end == 0 {
        return Err(format!(
            "DSA prefill selection requires positive rows/context, got {rows}/{context_end}"
        ));
    }
    if index_n_heads == 0
        || index_head_dim == 0
        || qk_rope_head_dim > index_head_dim
        || qk_rope_head_dim % 2 != 0
        || !score_scale.is_finite()
        || score_scale <= 0.0
    {
        return Err(format!(
            "DSA prefill selection has invalid geometry: heads={index_n_heads} head_dim={index_head_dim} rope_dim={qk_rope_head_dim} score_scale={score_scale}"
        ));
    }
    for (name, ptr) in [
        ("raw_queries", raw_queries_ptr),
        ("rope_queries", rope_queries_ptr),
        ("key_cache", key_cache_ptr),
        ("head_weights", head_weights_ptr),
        ("positions", positions_ptr),
        ("scores", buffers.scores_ptr),
        ("selected", buffers.selected_ptr),
    ] {
        if ptr == 0 {
            return Err(format!("DSA prefill selection {name} pointer is null"));
        }
    }
    if qk_rope_head_dim > 0 && (rope_cos_ptr == 0 || rope_sin_ptr == 0) {
        return Err(
            "DSA prefill selection RoPE tables are null for a positional indexer".to_string(),
        );
    }

    let plan = crate::gpu_decode::plan_dsa_topk(context_end, configured_topk)?;
    let score_elements = rows
        .checked_mul(context_end)
        .ok_or_else(|| "DSA prefill score size overflow".to_string())?;
    let selected_elements = rows
        .checked_mul(plan.selected)
        .ok_or_else(|| "DSA prefill selected-index size overflow".to_string())?;
    let candidate_elements = rows
        .checked_mul(plan.candidate_capacity)
        .ok_or_else(|| "DSA prefill candidate size overflow".to_string())?;
    if score_elements > buffers.scores_capacity {
        return Err(format!(
            "DSA prefill score capacity {} < required {}",
            buffers.scores_capacity, score_elements
        ));
    }
    if selected_elements > buffers.selected_capacity {
        return Err(format!(
            "DSA prefill selected-index capacity {} < required {}",
            buffers.selected_capacity, selected_elements
        ));
    }
    if plan.initial_runs > 1 {
        for (name, ptr) in [
            ("candidate_scores_a", buffers.candidate_scores_a_ptr),
            ("candidate_scores_b", buffers.candidate_scores_b_ptr),
            ("candidate_indices_a", buffers.candidate_indices_a_ptr),
            ("candidate_indices_b", buffers.candidate_indices_b_ptr),
        ] {
            if ptr == 0 {
                return Err(format!(
                    "DSA prefill multi-run selection {name} pointer is null"
                ));
            }
        }
        if candidate_elements > buffers.candidate_capacity {
            return Err(format!(
                "DSA prefill candidate capacity {} < required {}",
                buffers.candidate_capacity, candidate_elements
            ));
        }
    }

    let rows_i32 =
        i32::try_from(rows).map_err(|_| format!("DSA prefill rows {rows} exceed i32"))?;
    let context_i32 = i32::try_from(context_end)
        .map_err(|_| format!("DSA prefill context {context_end} exceeds i32"))?;
    let index_n_heads_i32 = i32::try_from(index_n_heads)
        .map_err(|_| format!("DSA prefill head count {index_n_heads} exceeds i32"))?;
    let index_head_dim_i32 = i32::try_from(index_head_dim)
        .map_err(|_| format!("DSA prefill head dimension {index_head_dim} exceeds i32"))?;
    let qk_rope_head_dim_i32 = i32::try_from(qk_rope_head_dim)
        .map_err(|_| format!("DSA prefill RoPE dimension {qk_rope_head_dim} exceeds i32"))?;

    let query_elements = rows
        .checked_mul(index_n_heads)
        .and_then(|value| value.checked_mul(index_head_dim))
        .ok_or_else(|| "DSA prefill query element count overflow".to_string())?;
    let (query_grid, query_block) = dsa_prefill_occupancy_launch(
        kernels.rope_query_bf16,
        0,
        query_elements,
        "DSA prefill query RoPE",
    )?;
    let query_logical_grid = query_elements.div_ceil(query_block as usize);
    let mut q0 = rope_queries_ptr;
    let mut q1 = raw_queries_ptr;
    let mut q2 = rope_cos_ptr;
    let mut q3 = rope_sin_ptr;
    let mut q4 = positions_ptr;
    let mut q5 = rows_i32;
    let mut q6 = index_n_heads_i32;
    let mut q7 = index_head_dim_i32;
    let mut q8 = qk_rope_head_dim_i32;
    let query_timing =
        dsa_prefill_selection_timing_start(timing_events, stream, "DSA prefill selection query")?;
    unsafe {
        launch(
            kernels.rope_query_bf16,
            (
                u32::try_from(query_logical_grid)
                    .map_err(|_| "DSA prefill query grid exceeds u32".to_string())?
                    .max(query_grid),
                1,
                1,
            ),
            (query_block, 1, 1),
            0,
            stream,
            &mut [
                &mut q0 as *mut _ as *mut _,
                &mut q1 as *mut _ as *mut _,
                &mut q2 as *mut _ as *mut _,
                &mut q3 as *mut _ as *mut _,
                &mut q4 as *mut _ as *mut _,
                &mut q5 as *mut _ as *mut _,
                &mut q6 as *mut _ as *mut _,
                &mut q7 as *mut _ as *mut _,
                &mut q8 as *mut _ as *mut _,
            ],
        )?;
    }
    dsa_prefill_selection_timing_finish(
        timing_events,
        query_timing,
        stream,
        DSA_PREFILL_SELECTION_TIMING_QUERY,
        "DSA prefill selection query",
        timing,
    )?;

    let score_timing =
        dsa_prefill_selection_timing_start(timing_events, stream, "DSA prefill selection scores")?;
    match index_score_mode {
        DeepseekV4PrefillIndexScoreMode::Scalar => {
            let score_shared_bytes = index_head_dim
                .checked_add(index_n_heads)
                .and_then(|elements| elements.checked_mul(std::mem::size_of::<f32>()))
                .ok_or_else(|| "DSA prefill score shared-memory size overflow".to_string())?;
            let score_shared_bytes_u32 = dsa_prefill_configure_dynamic_shared(
                kernels.fused_scores,
                score_shared_bytes,
                "DSA prefill fused score",
            )?;
            let (score_grid, score_block) = dsa_prefill_occupancy_launch(
                kernels.fused_scores,
                score_shared_bytes,
                context_end,
                "DSA prefill fused score",
            )?;
            let mut s0 = buffers.scores_ptr;
            let mut s1 = key_cache_ptr;
            let mut s2 = rope_queries_ptr;
            let mut s3 = head_weights_ptr;
            let mut s4 = positions_ptr;
            let mut s5 = rows_i32;
            let mut s6 = context_i32;
            let mut s7 = index_n_heads_i32;
            let mut s8 = index_head_dim_i32;
            let mut s9 = score_scale;
            let mut s10 = i32::try_from(causal_position_divisor.max(1))
                .map_err(|_| "DSA causal compression ratio exceeds i32")?;
            unsafe {
                launch(
                    kernels.fused_scores,
                    (
                        score_grid,
                        u32::try_from(rows).map_err(|_| "DSA rows exceed u32")?,
                        1,
                    ),
                    (score_block, 1, 1),
                    score_shared_bytes_u32,
                    stream,
                    &mut [
                        &mut s0 as *mut _ as *mut _,
                        &mut s1 as *mut _ as *mut _,
                        &mut s2 as *mut _ as *mut _,
                        &mut s3 as *mut _ as *mut _,
                        &mut s4 as *mut _ as *mut _,
                        &mut s5 as *mut _ as *mut _,
                        &mut s6 as *mut _ as *mut _,
                        &mut s7 as *mut _ as *mut _,
                        &mut s8 as *mut _ as *mut _,
                        &mut s9 as *mut _ as *mut _,
                        &mut s10 as *mut _ as *mut _,
                    ],
                )?;
            }
        }
        DeepseekV4PrefillIndexScoreMode::Bf16Fp32Gemm
        | DeepseekV4PrefillIndexScoreMode::Bf16Bf16Gemm
        | DeepseekV4PrefillIndexScoreMode::Bf16Bf16CausalGemm => {
            let causal_band_rows = if index_score_mode.uses_causal_gemm_bands() {
                if causal_context_row_span == 0 {
                    return Err(
                        "DSA prefill causal GEMM mode requires a positive causal row span"
                            .to_string(),
                    );
                }
                configured_topk
                    .checked_mul(causal_context_row_span)
                    .ok_or_else(|| "DSA prefill causal GEMM band rows overflow".to_string())?
            } else {
                0
            };
            launch_dsa_prefill_gemm_scores(
                kernels,
                stream,
                cublas_handle,
                cublas_workspace_ptr,
                cublas_workspace_bytes,
                key_cache_ptr,
                rope_queries_ptr,
                head_weights_ptr,
                positions_ptr,
                rows,
                context_end,
                index_n_heads,
                index_head_dim,
                score_scale,
                index_score_mode.temporary_is_bf16(),
                causal_position_start,
                causal_position_divisor.max(1),
                causal_context_row_span,
                causal_band_rows,
                buffers,
            )?;
        }
    }
    dsa_prefill_selection_timing_finish(
        timing_events,
        score_timing,
        stream,
        DSA_PREFILL_SELECTION_TIMING_SCORES,
        "DSA prefill selection scores",
        timing,
    )?;

    let selected_i32 = i32::try_from(plan.selected)
        .map_err(|_| format!("DSA selected count {} exceeds i32", plan.selected))?;
    let candidate_stride_i32 = i32::try_from(plan.candidate_capacity).map_err(|_| {
        format!(
            "DSA candidate stride {} exceeds i32",
            plan.candidate_capacity
        )
    })?;
    let initial_runs_i32 = i32::try_from(plan.initial_runs)
        .map_err(|_| format!("DSA initial run count {} exceeds i32", plan.initial_runs))?;
    let sort_width_i32 = i32::try_from(plan.sort_width)
        .map_err(|_| format!("DSA sort width {} exceeds i32", plan.sort_width))?;
    let (sort_kernel, merge_kernel, block_threads, topk_shared_bytes_u32) = match topk_mode {
        DeepseekV4PrefillTopkMode::Bitonic => {
            let block_threads = u32::try_from(plan.sort_width.min(256).max(1))
                .map_err(|_| "DSA top-k block width exceeds u32".to_string())?;
            let shared_bytes = dsa_prefill_configure_dynamic_shared(
                kernels.topk_sort_rows,
                plan.shared_bytes,
                "DSA prefill top-k sort",
            )?;
            dsa_prefill_configure_dynamic_shared(
                kernels.topk_merge_rows,
                plan.shared_bytes,
                "DSA prefill top-k merge",
            )?;
            (
                kernels.topk_sort_rows,
                kernels.topk_merge_rows,
                block_threads,
                shared_bytes,
            )
        }
        DeepseekV4PrefillTopkMode::RadixLinear => {
            if plan.sort_width > DSA_PREFILL_RADIX_CAPACITY
                || plan.selected > DSA_PREFILL_RADIX_CAPACITY
            {
                return Err(format!(
                    "DSA radix-linear top-k plan width/selected {}/{} exceeds kernel capacity {}",
                    plan.sort_width, plan.selected, DSA_PREFILL_RADIX_CAPACITY
                ));
            }
            (
                kernels.topk_radix_sort_rows,
                kernels.topk_linear_merge_rows,
                256,
                0,
            )
        }
    };
    let mut t0 = buffers.scores_ptr;
    let mut t1 = buffers.candidate_scores_a_ptr;
    let mut t2 = buffers.candidate_indices_a_ptr;
    let mut t3 = buffers.selected_ptr;
    let mut t4 = positions_ptr;
    let mut t5 = rows_i32;
    let mut t6 = context_i32;
    let mut t7 = selected_i32;
    let mut t8 = candidate_stride_i32;
    let mut t9 = initial_runs_i32;
    let mut t10 = sort_width_i32;
    let mut t11 = i32::try_from(causal_position_divisor.max(1))
        .map_err(|_| "DSA causal compression ratio exceeds i32".to_string())?;
    let base_sort_timing = dsa_prefill_selection_timing_start(
        timing_events,
        stream,
        "DSA prefill selection base sort",
    )?;
    unsafe {
        launch(
            sort_kernel,
            (
                u32::try_from(plan.initial_runs).map_err(|_| "DSA initial run grid exceeds u32")?,
                u32::try_from(rows).map_err(|_| "DSA rows exceed u32")?,
                1,
            ),
            (block_threads, 1, 1),
            topk_shared_bytes_u32,
            stream,
            &mut [
                &mut t0 as *mut _ as *mut _,
                &mut t1 as *mut _ as *mut _,
                &mut t2 as *mut _ as *mut _,
                &mut t3 as *mut _ as *mut _,
                &mut t4 as *mut _ as *mut _,
                &mut t5 as *mut _ as *mut _,
                &mut t6 as *mut _ as *mut _,
                &mut t7 as *mut _ as *mut _,
                &mut t8 as *mut _ as *mut _,
                &mut t9 as *mut _ as *mut _,
                &mut t10 as *mut _ as *mut _,
                &mut t11 as *mut _ as *mut _,
            ],
        )?;
    }
    dsa_prefill_selection_timing_finish(
        timing_events,
        base_sort_timing,
        stream,
        DSA_PREFILL_SELECTION_TIMING_BASE_SORT,
        "DSA prefill selection base sort",
        timing,
    )?;

    let mut input_runs = plan.initial_runs;
    let mut input_is_a = true;
    let merge_timing = if input_runs > 1 {
        dsa_prefill_selection_timing_start(timing_events, stream, "DSA prefill selection merge")?
    } else {
        None
    };
    while input_runs > 1 {
        let output_runs = input_runs.div_ceil(2);
        let (input_scores, input_indices, output_scores, output_indices) = if input_is_a {
            (
                buffers.candidate_scores_a_ptr,
                buffers.candidate_indices_a_ptr,
                buffers.candidate_scores_b_ptr,
                buffers.candidate_indices_b_ptr,
            )
        } else {
            (
                buffers.candidate_scores_b_ptr,
                buffers.candidate_indices_b_ptr,
                buffers.candidate_scores_a_ptr,
                buffers.candidate_indices_a_ptr,
            )
        };
        let mut m0 = input_scores;
        let mut m1 = input_indices;
        let mut m2 = output_scores;
        let mut m3 = output_indices;
        let mut m4 = buffers.selected_ptr;
        let mut m5 = rows_i32;
        let mut m6 = selected_i32;
        let mut m7 = candidate_stride_i32;
        let mut m8 =
            i32::try_from(input_runs).map_err(|_| "DSA input runs exceed i32".to_string())?;
        let mut m9 = sort_width_i32;
        unsafe {
            launch(
                merge_kernel,
                (
                    u32::try_from(output_runs).map_err(|_| "DSA output run grid exceeds u32")?,
                    u32::try_from(rows).map_err(|_| "DSA rows exceed u32")?,
                    1,
                ),
                (block_threads, 1, 1),
                topk_shared_bytes_u32,
                stream,
                &mut [
                    &mut m0 as *mut _ as *mut _,
                    &mut m1 as *mut _ as *mut _,
                    &mut m2 as *mut _ as *mut _,
                    &mut m3 as *mut _ as *mut _,
                    &mut m4 as *mut _ as *mut _,
                    &mut m5 as *mut _ as *mut _,
                    &mut m6 as *mut _ as *mut _,
                    &mut m7 as *mut _ as *mut _,
                    &mut m8 as *mut _ as *mut _,
                    &mut m9 as *mut _ as *mut _,
                ],
            )?;
        }
        input_runs = output_runs;
        input_is_a = !input_is_a;
    }
    dsa_prefill_selection_timing_finish(
        timing_events,
        merge_timing,
        stream,
        DSA_PREFILL_SELECTION_TIMING_MERGE,
        "DSA prefill selection merge",
        timing,
    )?;
    Ok(plan)
}

#[allow(clippy::too_many_arguments)]
fn launch_dsa_prefill_selection_chunk(
    kernels: DsaPrefillSelectionKernels,
    stream: cuda_sys::CUstream,
    owner_layer_idx: usize,
    chunk_start: usize,
    chunk_rows: usize,
    context_end: usize,
    raw_queries_ptr: u64,
    key_cache_ptr: u64,
    head_weights_ptr: u64,
    positions_ptr: u64,
    rope_cos_ptr: u64,
    rope_sin_ptr: u64,
    qk_rope_head_dim: usize,
    score_scale: f32,
    index_score_mode: DeepseekV4PrefillIndexScoreMode,
    topk_mode: DeepseekV4PrefillTopkMode,
    cublas_handle: cudarc::cublas::sys::cublasHandle_t,
    cublas_workspace_ptr: u64,
    cublas_workspace_bytes: usize,
    workspace: &DsaPrefillRequestWorkspace,
    timing_events: Option<DsaPrefillSelectionTimingEvents>,
) -> Result<DsaPrefillSelectionTiming, String> {
    if chunk_rows > workspace.max_chunk_rows || context_end > workspace.max_context_end {
        return Err(format!(
            "DSA prefill selection request rows/context {}/{} exceed workspace maxima {}/{}",
            chunk_rows, context_end, workspace.max_chunk_rows, workspace.max_context_end
        ));
    }
    // The workspace geometry is derived from the representation actually fed
    // to selection. GLM passes raw token positions with a pooled cache, while
    // DeepSeek-V4 passes count-1 positions that are already in compressed-cache
    // rows. Keep allocation, planning, and execution on this single source of
    // truth so callers cannot divide an already-compressed position twice.
    let causal_position_divisor = workspace.context_divisor;
    let causal_context_row_span = workspace.causal_context_row_span;
    let plan = plan_dsa_prefill_selection(
        chunk_rows,
        context_end,
        workspace.configured_topk,
        workspace.selection_workspace_capacity_bytes,
        index_score_mode.score_buffer_count(),
        causal_context_row_span,
    )?;
    if plan.selected_per_row > workspace.max_selected_per_row {
        return Err(format!(
            "DSA prefill selected width {} exceeds workspace maximum {}",
            plan.selected_per_row, workspace.max_selected_per_row
        ));
    }
    let query_row_bytes = workspace
        .index_n_heads
        .checked_mul(workspace.index_head_dim)
        .and_then(|elements| elements.checked_mul(std::mem::size_of::<u16>()))
        .ok_or_else(|| "DSA prefill query row-byte size overflow".to_string())?;
    let head_weight_row_bytes = workspace
        .index_n_heads
        .checked_mul(std::mem::size_of::<u16>())
        .ok_or_else(|| "DSA prefill head-weight row-byte size overflow".to_string())?;
    let selected_row_bytes = plan
        .selected_per_row
        .checked_mul(std::mem::size_of::<i32>())
        .ok_or_else(|| "DSA prefill selected row-byte size overflow".to_string())?;
    let score_bytes = plan
        .score_tile_elements
        .checked_mul(std::mem::size_of::<f32>())
        .ok_or_else(|| "DSA prefill score-tile byte size overflow".to_string())?;
    let candidate_component_bytes = plan
        .candidate_tile_elements
        .checked_mul(std::mem::size_of::<f32>())
        .ok_or_else(|| "DSA prefill candidate-component byte size overflow".to_string())?;
    let workspace_base = *workspace.d_selection_workspace.device_ptr();
    let score_temp_ptr = if index_score_mode != DeepseekV4PrefillIndexScoreMode::Scalar {
        workspace_base
            .checked_add(
                u64::try_from(score_bytes)
                    .map_err(|_| "DSA prefill temporary score offset exceeds u64".to_string())?,
            )
            .ok_or_else(|| "DSA prefill temporary score pointer overflow".to_string())?
    } else {
        0
    };
    let score_buffers_bytes = score_bytes
        .checked_mul(plan.score_buffer_count)
        .ok_or_else(|| "DSA prefill score-buffer workspace size overflow".to_string())?;
    let candidate_scores_a_ptr = if plan.candidate_tile_elements == 0 {
        0
    } else {
        workspace_base
            .checked_add(
                u64::try_from(score_buffers_bytes)
                    .map_err(|_| "DSA prefill score workspace offset exceeds u64".to_string())?,
            )
            .ok_or_else(|| "DSA prefill candidate score A pointer overflow".to_string())?
    };
    let candidate_scores_b_ptr = if plan.candidate_tile_elements == 0 {
        0
    } else {
        candidate_scores_a_ptr
            .checked_add(
                u64::try_from(candidate_component_bytes)
                    .map_err(|_| "DSA prefill candidate score component exceeds u64".to_string())?,
            )
            .ok_or_else(|| "DSA prefill candidate score B pointer overflow".to_string())?
    };
    let candidate_indices_a_ptr = if plan.candidate_tile_elements == 0 {
        0
    } else {
        candidate_scores_b_ptr
            .checked_add(
                u64::try_from(candidate_component_bytes)
                    .map_err(|_| "DSA prefill candidate index component exceeds u64".to_string())?,
            )
            .ok_or_else(|| "DSA prefill candidate index A pointer overflow".to_string())?
    };
    let candidate_indices_b_ptr = if plan.candidate_tile_elements == 0 {
        0
    } else {
        candidate_indices_a_ptr
            .checked_add(
                u64::try_from(candidate_component_bytes)
                    .map_err(|_| "DSA prefill candidate index component exceeds u64".to_string())?,
            )
            .ok_or_else(|| "DSA prefill candidate index B pointer overflow".to_string())?
    };
    let workspace_end_bytes = score_buffers_bytes
        .checked_add(
            candidate_component_bytes
                .checked_mul(4)
                .ok_or_else(|| "DSA prefill candidate workspace byte size overflow".to_string())?,
        )
        .ok_or_else(|| "DSA prefill workspace partition size overflow".to_string())?;
    if workspace_end_bytes != plan.workspace_tile_bytes
        || workspace_end_bytes > workspace.d_selection_workspace.len()
    {
        return Err(format!(
            "DSA prefill workspace partition {} bytes differs from planned {} or exceeds allocation {}",
            workspace_end_bytes,
            plan.workspace_tile_bytes,
            workspace.d_selection_workspace.len()
        ));
    }
    let mut timing = DsaPrefillSelectionTiming::default();
    for tile_idx in 0..plan.score_tile_count {
        let row_start = tile_idx
            .checked_mul(plan.score_tile_rows)
            .ok_or_else(|| "DSA prefill tile row offset overflow".to_string())?;
        let rows = (chunk_rows - row_start).min(plan.score_tile_rows);
        let raw_queries_tile = raw_queries_ptr
            .checked_add(
                u64::try_from(
                    row_start
                        .checked_mul(query_row_bytes)
                        .ok_or_else(|| "DSA prefill query tile offset overflow".to_string())?,
                )
                .map_err(|_| "DSA prefill query tile offset exceeds u64".to_string())?,
            )
            .ok_or_else(|| "DSA prefill query tile pointer overflow".to_string())?;
        let head_weights_tile =
            head_weights_ptr
                .checked_add(
                    u64::try_from(row_start.checked_mul(head_weight_row_bytes).ok_or_else(
                        || "DSA prefill head-weight tile offset overflow".to_string(),
                    )?)
                    .map_err(|_| "DSA prefill head-weight tile offset exceeds u64".to_string())?,
                )
                .ok_or_else(|| "DSA prefill head-weight tile pointer overflow".to_string())?;
        let positions_tile = positions_ptr
            .checked_add(
                u64::try_from(
                    row_start
                        .checked_mul(std::mem::size_of::<i32>())
                        .ok_or_else(|| "DSA prefill position tile offset overflow".to_string())?,
                )
                .map_err(|_| "DSA prefill position tile offset exceeds u64".to_string())?,
            )
            .ok_or_else(|| "DSA prefill position tile pointer overflow".to_string())?;
        let selected_base_ptr = workspace
            .d_pool_selected_indices
            .as_ref()
            .map_or(*workspace.d_selected_indices.device_ptr(), |buffer| {
                *buffer.device_ptr()
            });
        let selected_tile = selected_base_ptr
            .checked_add(
                u64::try_from(
                    row_start
                        .checked_mul(selected_row_bytes)
                        .ok_or_else(|| "DSA prefill selected tile offset overflow".to_string())?,
                )
                .map_err(|_| "DSA prefill selected tile offset exceeds u64".to_string())?,
            )
            .ok_or_else(|| "DSA prefill selected tile pointer overflow".to_string())?;
        let selected_capacity = rows
            .checked_mul(plan.selected_per_row)
            .ok_or_else(|| "DSA prefill selected tile capacity overflow".to_string())?;
        launch_dsa_prefill_selection_rows(
            kernels,
            stream,
            raw_queries_tile,
            *workspace.d_rope_queries.device_ptr(),
            key_cache_ptr,
            head_weights_tile,
            positions_tile,
            rope_cos_ptr,
            rope_sin_ptr,
            rows,
            context_end,
            workspace.index_n_heads,
            workspace.index_head_dim,
            qk_rope_head_dim,
            workspace.configured_topk,
            score_scale,
            chunk_start
                .checked_add(row_start)
                .ok_or_else(|| "DSA prefill causal position start overflow".to_string())?,
            causal_position_divisor,
            causal_context_row_span,
            index_score_mode,
            topk_mode,
            cublas_handle,
            cublas_workspace_ptr,
            cublas_workspace_bytes,
            DsaPrefillSelectionBuffers {
                scores_ptr: workspace_base,
                scores_capacity: plan.score_tile_elements,
                score_temp_ptr,
                score_temp_capacity: if score_temp_ptr == 0 {
                    0
                } else if index_score_mode.uses_causal_gemm_bands() {
                    plan.score_tile_elements.checked_mul(2).ok_or_else(|| {
                        "DSA prefill causal BF16 temporary score capacity overflow".to_string()
                    })?
                } else {
                    plan.score_tile_elements
                },
                candidate_scores_a_ptr,
                candidate_scores_b_ptr,
                candidate_indices_a_ptr,
                candidate_indices_b_ptr,
                candidate_capacity: plan.candidate_tile_elements,
                selected_ptr: selected_tile,
                selected_capacity,
            },
            timing_events,
            &mut timing,
        )?;
    }
    workspace.mark_owner_result(
        owner_layer_idx,
        chunk_start,
        chunk_rows,
        context_end,
        plan.selected_per_row,
    );
    Ok(timing)
}

