    fn maybe_apply_reference_mamba2_gated_norm_replay(
        &self,
        layer_idx: usize,
        chunk_idx: usize,
        trace_start_abs_pos: usize,
        token_count: usize,
        norm_out: u64,
        x: u64,
        gate: u64,
        weight: u64,
        n_groups: usize,
        group_size: usize,
        proj_dim: usize,
        eps: f32,
    ) -> Result<(), String> {
        let entries = self.reference_mamba2_gated_norm_replay.borrow().clone();
        if entries.is_empty()
            || token_count == 0
            || n_groups == 0
            || group_size == 0
            || proj_dim == 0
            || weight == 0
        {
            return Ok(());
        }
        let norm_threads = group_size.next_power_of_two().clamp(32, 1024) as u32;
        let mut applied = Vec::new();
        let mut skipped = Vec::new();
        for entry in entries.iter().filter(|entry| entry.layer_idx == layer_idx) {
            let local_row = entry.row_idx.checked_sub(trace_start_abs_pos);
            let Some(local_row) = local_row else {
                skipped.push(serde_json::json!({
                    "layer": entry.layer_idx,
                    "row": entry.row_idx,
                    "mode": entry.mode.as_str(),
                    "reason": "row before current chunk",
                }));
                continue;
            };
            if local_row >= token_count {
                skipped.push(serde_json::json!({
                    "layer": entry.layer_idx,
                    "row": entry.row_idx,
                    "mode": entry.mode.as_str(),
                    "reason": "row after current chunk",
                    "chunk_start_abs_pos": trace_start_abs_pos,
                    "token_count": token_count,
                }));
                continue;
            }
            match entry.mode {
                ReferenceMamba2GatedNormReplayMode::SqrtApproxDivRn => {
                    let mut p0 = norm_out;
                    let mut p1 = x;
                    let mut p2 = gate;
                    let mut p3 = weight;
                    let mut p4 = local_row as i32;
                    let mut p5 = n_groups as i32;
                    let mut p6 = group_size as i32;
                    let mut p7 = proj_dim as i32;
                    let mut p8 = eps;
                    unsafe {
                        launch(
                            self.kernels
                                .mamba2_gated_group_rmsnorm_sqrt_approx_div_rn_replay,
                            (n_groups as u32, 1, 1),
                            (norm_threads, 1, 1),
                            norm_threads * 4,
                            self.stream,
                            &mut [
                                &mut p0 as *mut _ as *mut std::ffi::c_void,
                                &mut p1 as *mut _ as *mut std::ffi::c_void,
                                &mut p2 as *mut _ as *mut std::ffi::c_void,
                                &mut p3 as *mut _ as *mut std::ffi::c_void,
                                &mut p4 as *mut _ as *mut std::ffi::c_void,
                                &mut p5 as *mut _ as *mut std::ffi::c_void,
                                &mut p6 as *mut _ as *mut std::ffi::c_void,
                                &mut p7 as *mut _ as *mut std::ffi::c_void,
                                &mut p8 as *mut _ as *mut std::ffi::c_void,
                            ],
                        )?;
                    }
                    applied.push(serde_json::json!({
                        "layer": entry.layer_idx,
                        "row": entry.row_idx,
                        "local_row": local_row,
                        "mode": entry.mode.as_str(),
                        "operation": "sqrt.approx.ftz.f32 + div.rn.f32",
                    }));
                }
            }
        }
        if self.reference_debug_trace_enabled && (!applied.is_empty() || !skipped.is_empty()) {
            self.push_reference_stage_metadata(
                "debug_mamba2_gated_norm_internal_replay",
                Some(layer_idx),
                chunk_idx,
                trace_start_abs_pos.saturating_add(token_count.saturating_sub(1)),
                0,
                serde_json::json!({
                    "scope": "/v1/internal/reference_test only",
                    "production_behavior_changed": false,
                    "production_kernel": "mamba2_gated_group_rmsnorm_kernel",
                    "replay_kernel": "mamba2_gated_group_rmsnorm_sqrt_approx_div_rn_replay_kernel",
                    "applied": applied,
                    "skipped": skipped,
                }),
            );
        }
        Ok(())
    }

