    fn record_prefill_device_trace_mamba2_ssd_shadow_context_details(
        &self,
        layer_idx: usize,
        chunk_idx: usize,
        absolute_position: usize,
        x_ptr: u64,
        dt_ptr: u64,
        a_log_ptr: u64,
        b_ptr: u64,
        c_ptr: u64,
        d_ptr: u64,
        ssm_state_ptr: u64,
        dt_bias_ptr: u64,
        out_ptr: u64,
        row_idx: usize,
        m: usize,
        n_heads: usize,
        head_dim: usize,
        state_size: usize,
        n_groups: usize,
        chunk_size: usize,
        use_softplus: bool,
    ) -> Result<(), String> {
        if !self.prefill_device_trace_enabled.get()
            || self.prefill_device_trace_layer.get() != layer_idx
            || x_ptr == 0
            || dt_ptr == 0
            || a_log_ptr == 0
            || b_ptr == 0
            || c_ptr == 0
            || out_ptr == 0
            || m == 0
            || n_heads == 0
            || head_dim == 0
            || state_size == 0
            || n_groups == 0
        {
            return Ok(());
        }
        let Some(buf) = self.d_prefill_device_trace.as_ref() else {
            return Ok(());
        };
        let selected_dims = self.prefill_device_trace_selected_dims.borrow().clone();
        if selected_dims.is_empty() {
            return Ok(());
        }
        let d_inner = n_heads.saturating_mul(head_dim);
        let trace_row = row_idx.min(m.saturating_sub(1));
        let entries_per_dim = 6usize;
        for dim in selected_dims.into_iter().filter(|&dim| dim < d_inner) {
            let entry_base = self.prefill_device_trace_next_slot.get();
            if entry_base.saturating_add(entries_per_dim) > PREFILL_DEVICE_TRACE_MAX_ENTRIES {
                break;
            }
            self.prefill_device_trace_next_slot
                .set(entry_base.saturating_add(entries_per_dim));
            let mut p0 = x_ptr;
            let mut p1 = dt_ptr;
            let mut p2 = a_log_ptr;
            let mut p3 = b_ptr;
            let mut p4 = c_ptr;
            let mut p5 = d_ptr;
            let mut p6 = ssm_state_ptr;
            let mut p7 = dt_bias_ptr;
            let mut p8 = out_ptr;
            let mut p9 = *buf.device_ptr();
            let mut p10 = entry_base as i32;
            let mut p11 = PREFILL_DEVICE_TRACE_MAX_ENTRIES as i32;
            let mut p12 = PDT_LAYER_MAMBA2_SSD_SHADOW_CONTEXT_POINTER_DETAIL as i32;
            let mut p13 = PDT_LAYER_MAMBA2_SSD_SHADOW_CONTEXT_INDEX_DETAIL as i32;
            let mut p14 = PDT_LAYER_MAMBA2_SSD_SHADOW_CONTEXT_SAMPLE_DETAIL as i32;
            let mut p15 = PDT_LAYER_MAMBA2_SSD_SHADOW_CONTEXT_SUMMARY_DETAIL as i32;
            let mut p16 = layer_idx as i32;
            let mut p17 = chunk_idx as i32;
            let mut p18 = absolute_position as i32;
            let mut p19 = trace_row as i32;
            let mut p20 = m as i32;
            let mut p21 = n_heads as i32;
            let mut p22 = head_dim as i32;
            let mut p23 = state_size as i32;
            let mut p24 = n_groups as i32;
            let mut p25 = chunk_size as i32;
            let mut p26 = if use_softplus { 1i32 } else { 0i32 };
            let mut p27 = dim as i32;
            unsafe {
                launch(
                    self.kernels.prefill_trace_mamba2_ssd_shadow_context_detail,
                    (1, 1, 1),
                    (1, 1, 1),
                    0,
                    self.stream,
                    &mut [
                        &mut p0 as *mut _ as *mut std::ffi::c_void,
                        &mut p1 as *mut _ as *mut std::ffi::c_void,
                        &mut p2 as *mut _ as *mut std::ffi::c_void,
                        &mut p3 as *mut _ as *mut std::ffi::c_void,
                        &mut p4 as *mut _ as *mut std::ffi::c_void,
                        &mut p5 as *mut _ as *mut std::ffi::c_void,
                        &mut p6 as *mut _ as *mut std::ffi::c_void,
                        &mut p7 as *mut _ as *mut std::ffi::c_void,
                        &mut p8 as *mut _ as *mut std::ffi::c_void,
                        &mut p9 as *mut _ as *mut std::ffi::c_void,
                        &mut p10 as *mut _ as *mut std::ffi::c_void,
                        &mut p11 as *mut _ as *mut std::ffi::c_void,
                        &mut p12 as *mut _ as *mut std::ffi::c_void,
                        &mut p13 as *mut _ as *mut std::ffi::c_void,
                        &mut p14 as *mut _ as *mut std::ffi::c_void,
                        &mut p15 as *mut _ as *mut std::ffi::c_void,
                        &mut p16 as *mut _ as *mut std::ffi::c_void,
                        &mut p17 as *mut _ as *mut std::ffi::c_void,
                        &mut p18 as *mut _ as *mut std::ffi::c_void,
                        &mut p19 as *mut _ as *mut std::ffi::c_void,
                        &mut p20 as *mut _ as *mut std::ffi::c_void,
                        &mut p21 as *mut _ as *mut std::ffi::c_void,
                        &mut p22 as *mut _ as *mut std::ffi::c_void,
                        &mut p23 as *mut _ as *mut std::ffi::c_void,
                        &mut p24 as *mut _ as *mut std::ffi::c_void,
                        &mut p25 as *mut _ as *mut std::ffi::c_void,
                        &mut p26 as *mut _ as *mut std::ffi::c_void,
                        &mut p27 as *mut _ as *mut std::ffi::c_void,
                    ],
                )?;
            }
        }
        Ok(())
    }

    fn record_prefill_device_trace_fused_rmsnorm_input_details(
        &self,
        stage_id: u64,
        layer_idx: usize,
        chunk_idx: usize,
        absolute_position: usize,
        token_id: usize,
        residual_row_ptr: u64,
        hidden_row_ptr: u64,
        width: usize,
    ) -> Result<(), String> {
        let trace_layer = self.prefill_device_trace_layer.get();
        let layer_matches = trace_layer == layer_idx
            || (stage_id == PDT_LAYER_OUTPUT_SUM_ELEMENT_DETAIL
                && trace_layer == layer_idx.saturating_add(1));
        if !self.prefill_device_trace_enabled.get() || !layer_matches || width == 0 {
            return Ok(());
        }
        let Some(buf) = self.d_prefill_device_trace.as_ref() else {
            return Ok(());
        };
        let selected_dims = self.prefill_device_trace_selected_dims.borrow().clone();
        if !selected_dims.is_empty() {
            for dim in selected_dims.into_iter().filter(|&dim| dim < width) {
                let entry_base = self.prefill_device_trace_next_slot.get();
                if entry_base >= PREFILL_DEVICE_TRACE_MAX_ENTRIES {
                    break;
                }
                self.prefill_device_trace_next_slot.set(entry_base + 1);
                let mut p0 = *buf.device_ptr();
                let mut p1 = entry_base as i32;
                let mut p2 = stage_id as i32;
                let mut p3 = layer_idx as i32;
                let mut p4 = chunk_idx as i32;
                let mut p5 = absolute_position as i32;
                let mut p6 = token_id as i32;
                let mut p7 = residual_row_ptr;
                let mut p8 = hidden_row_ptr;
                let mut p9 = width as i32;
                let mut p10 = dim as i32;
                let mut p11 = 1i32;
                unsafe {
                    launch(
                        self.kernels.prefill_trace_fused_rmsnorm_input_detail,
                        (1, 1, 1),
                        (1, 1, 1),
                        0,
                        self.stream,
                        &mut [
                            &mut p0 as *mut _ as *mut std::ffi::c_void,
                            &mut p1 as *mut _ as *mut std::ffi::c_void,
                            &mut p2 as *mut _ as *mut std::ffi::c_void,
                            &mut p3 as *mut _ as *mut std::ffi::c_void,
                            &mut p4 as *mut _ as *mut std::ffi::c_void,
                            &mut p5 as *mut _ as *mut std::ffi::c_void,
                            &mut p6 as *mut _ as *mut std::ffi::c_void,
                            &mut p7 as *mut _ as *mut std::ffi::c_void,
                            &mut p8 as *mut _ as *mut std::ffi::c_void,
                            &mut p9 as *mut _ as *mut std::ffi::c_void,
                            &mut p10 as *mut _ as *mut std::ffi::c_void,
                            &mut p11 as *mut _ as *mut std::ffi::c_void,
                        ],
                    )?;
                }
            }
            return Ok(());
        }
        let entry_base = self.prefill_device_trace_next_slot.get();
        let available = PREFILL_DEVICE_TRACE_MAX_ENTRIES.saturating_sub(entry_base);
        let element_count = width.min(available);
        if element_count == 0 {
            return Ok(());
        }
        self.prefill_device_trace_next_slot
            .set(entry_base + element_count);
        let block = 256u32;
        let grid = ((element_count as u32) + block - 1) / block;
        let mut p0 = *buf.device_ptr();
        let mut p1 = entry_base as i32;
        let mut p2 = stage_id as i32;
        let mut p3 = layer_idx as i32;
        let mut p4 = chunk_idx as i32;
        let mut p5 = absolute_position as i32;
        let mut p6 = token_id as i32;
        let mut p7 = residual_row_ptr;
        let mut p8 = hidden_row_ptr;
        let mut p9 = width as i32;
        let mut p10 = 0i32;
        let mut p11 = element_count as i32;
        unsafe {
            launch(
                self.kernels.prefill_trace_fused_rmsnorm_input_detail,
                (grid, 1, 1),
                (block, 1, 1),
                0,
                self.stream,
                &mut [
                    &mut p0 as *mut _ as *mut std::ffi::c_void,
                    &mut p1 as *mut _ as *mut std::ffi::c_void,
                    &mut p2 as *mut _ as *mut std::ffi::c_void,
                    &mut p3 as *mut _ as *mut std::ffi::c_void,
                    &mut p4 as *mut _ as *mut std::ffi::c_void,
                    &mut p5 as *mut _ as *mut std::ffi::c_void,
                    &mut p6 as *mut _ as *mut std::ffi::c_void,
                    &mut p7 as *mut _ as *mut std::ffi::c_void,
                    &mut p8 as *mut _ as *mut std::ffi::c_void,
                    &mut p9 as *mut _ as *mut std::ffi::c_void,
                    &mut p10 as *mut _ as *mut std::ffi::c_void,
                    &mut p11 as *mut _ as *mut std::ffi::c_void,
                ],
            )
        }
    }

