    fn trace_emit_f32(
        &self,
        step: usize,
        position: usize,
        token_id: usize,
        layer: Option<usize>,
        component: &str,
        tensor: &str,
        ptr: u64,
        n: usize,
    ) {
        let Some(trace) = self.trace.as_ref() else {
            return;
        };
        if !trace.should_emit(step, layer, component) {
            return;
        }
        let _ = self.stream_sync();
        let count = n.min(trace.max_elems).max(1);
        let mut values = vec![0.0f32; count];
        unsafe {
            let _ = cuda_sys::lib().cuMemcpyDtoH_v2(
                values.as_mut_ptr() as *mut std::ffi::c_void,
                ptr,
                count * 4,
            );
        }
        let mut min_v = f32::INFINITY;
        let mut max_v = f32::NEG_INFINITY;
        let mut sum = 0.0f64;
        let mut l2 = 0.0f64;
        let mut nan = 0usize;
        let mut inf = 0usize;
        for &v in &values {
            if v.is_nan() {
                nan += 1;
                continue;
            }
            if v.is_infinite() {
                inf += 1;
                continue;
            }
            min_v = min_v.min(v);
            max_v = max_v.max(v);
            let vf = v as f64;
            sum += vf;
            l2 += vf * vf;
        }
        let finite = count.saturating_sub(nan + inf).max(1);
        let sample = trace_format_sample(&values[..values.len().min(trace.sample_values)]);
        let layer_s = layer
            .map(|v| v.to_string())
            .unwrap_or_else(|| "-".to_string());
        eprintln!(
            "[KRASIS-TRACE] event=tensor step={} pos={} tok={} layer={} component={} tensor={} dtype=f32 n={} sample=[{}] l2={:.6} mean={:.6} min={:.6} max={:.6} nan={} inf={}",
            step,
            position,
            token_id,
            layer_s,
            component,
            tensor,
            count,
            sample,
            l2.sqrt(),
            sum / finite as f64,
            min_v,
            max_v,
            nan,
            inf,
        );
    }

    fn trace_emit_f32_values(
        &self,
        step: usize,
        position: usize,
        token_id: usize,
        layer: Option<usize>,
        component: &str,
        tensor: &str,
        values: &[f32],
    ) {
        let Some(trace) = self.trace.as_ref() else {
            return;
        };
        if !trace.should_emit(step, layer, component) {
            return;
        }
        if values.is_empty() {
            return;
        }
        let count = values.len().min(trace.max_elems).max(1);
        let values = &values[..count];
        let mut min_v = f32::INFINITY;
        let mut max_v = f32::NEG_INFINITY;
        let mut sum = 0.0f64;
        let mut l2 = 0.0f64;
        let mut nan = 0usize;
        let mut inf = 0usize;
        for &v in values {
            if v.is_nan() {
                nan += 1;
                continue;
            }
            if v.is_infinite() {
                inf += 1;
                continue;
            }
            min_v = min_v.min(v);
            max_v = max_v.max(v);
            let vf = v as f64;
            sum += vf;
            l2 += vf * vf;
        }
        let finite = count.saturating_sub(nan + inf).max(1);
        let sample = trace_format_sample(&values[..values.len().min(trace.sample_values)]);
        let layer_s = layer
            .map(|v| v.to_string())
            .unwrap_or_else(|| "-".to_string());
        eprintln!(
            "[KRASIS-TRACE] event=tensor step={} pos={} tok={} layer={} component={} tensor={} dtype=f32 n={} sample=[{}] l2={:.6} mean={:.6} min={:.6} max={:.6} nan={} inf={}",
            step,
            position,
            token_id,
            layer_s,
            component,
            tensor,
            count,
            sample,
            l2.sqrt(),
            sum / finite as f64,
            min_v,
            max_v,
            nan,
            inf,
        );
    }

    fn trace_emit_compare_summary(
        &self,
        step: usize,
        position: usize,
        token_id: usize,
        layer: Option<usize>,
        component: &str,
        stage: &str,
        actual_label: &str,
        expected_label: &str,
        actual: &[f32],
        expected: &[f32],
    ) -> TraceDiffSummary {
        let summary = summarize_trace_diff(actual, expected);
        let Some(trace) = self.trace.as_ref() else {
            return summary;
        };
        if !trace.should_emit(step, layer, component) {
            return summary;
        }
        let layer_s = layer
            .map(|v| v.to_string())
            .unwrap_or_else(|| "-".to_string());
        eprintln!(
            "[KRASIS-TRACE] event=compare step={} pos={} tok={} layer={} component={} stage={} actual={} expected={} max_abs={:.6} max_abs_idx={} actual_at_max={:.6} expected_at_max={:.6} l2={:.6} mean_abs={:.6}",
            step,
            position,
            token_id,
            layer_s,
            component,
            stage,
            actual_label,
            expected_label,
            summary.max_abs,
            summary.max_abs_idx,
            summary.actual_at_max,
            summary.expected_at_max,
            summary.l2,
            summary.mean_abs,
        );
        summary
    }

    fn trace_emit_router_compare_last(
        &self,
        layer_idx: usize,
        hidden_ptr: u64,
        gate_ptr: u64,
        gate_rows: usize,
        gate_cols: usize,
        gate_bias_ptr: u64,
        e_score_corr_ptr: u64,
        scoring_func: u8,
        topk: usize,
        gate_out_ptr: u64,
        topk_ids_ptr: u64,
        topk_weights_ptr: u64,
        m: usize,
    ) {
        if !self.trace.as_ref().map_or(false, |t| {
            t.should_emit(0, Some(layer_idx), "prefill_layer")
        }) {
            return;
        }
        let _ = self.stream_sync();
        let last_pos = m.saturating_sub(1);
        let hidden_row_ptr = hidden_ptr + (last_pos * gate_cols * 2) as u64;
        let gate_row_ptr = gate_out_ptr + (last_pos * gate_rows * 4) as u64;
        let topk_ids_row_ptr = topk_ids_ptr + (last_pos * topk * 4) as u64;
        let topk_weights_row_ptr = topk_weights_ptr + (last_pos * topk * 4) as u64;
        match (
            download_device_u16(hidden_row_ptr, gate_cols),
            download_device_f32(gate_row_ptr, gate_rows),
            download_device_i32(topk_ids_row_ptr, topk),
            download_device_f32(topk_weights_row_ptr, topk),
        ) {
            (
                Ok(hidden_row_bf16),
                Ok(actual_logits),
                Ok(actual_topk_ids),
                Ok(actual_topk_weights),
            ) => {
                match compute_bf16_gemm_row_cpu_reference(
                    &hidden_row_bf16,
                    gate_ptr,
                    gate_rows,
                    gate_cols,
                ) {
                    Ok(expected_logits) => {
                        self.trace_emit_f32_values(
                            0,
                            last_pos,
                            0,
                            Some(layer_idx),
                            "prefill_layer",
                            "router_logits_last_cpu_ref",
                            &expected_logits,
                        );
                        let logits_summary = self.trace_emit_compare_summary(
                            0,
                            last_pos,
                            0,
                            Some(layer_idx),
                            "prefill_layer",
                            "router_logits",
                            "router_logits_last_vendor",
                            "router_logits_last_cpu_ref",
                            &actual_logits,
                            &expected_logits,
                        );
                        let gate_bias = if gate_bias_ptr != 0 {
                            match download_device_f32(gate_bias_ptr, gate_rows) {
                                Ok(v) => Some(v),
                                Err(err) => {
                                    trace_emit_prefill_mark(
                                        self.trace.as_ref(),
                                        0,
                                        last_pos,
                                        0,
                                        Some(layer_idx),
                                        "prefill_layer",
                                        &format!(
                                            "phase=router_gate_bias_download_failed error={}",
                                            err
                                        ),
                                    );
                                    return;
                                }
                            }
                        } else {
                            None
                        };
                        let e_score_corr = if e_score_corr_ptr != 0 {
                            match download_device_f32(e_score_corr_ptr, gate_rows) {
                                Ok(v) => Some(v),
                                Err(err) => {
                                    trace_emit_prefill_mark(
                                        self.trace.as_ref(),
                                        0,
                                        last_pos,
                                        0,
                                        Some(layer_idx),
                                        "prefill_layer",
                                        &format!(
                                            "phase=router_e_score_corr_download_failed error={}",
                                            err
                                        ),
                                    );
                                    return;
                                }
                            }
                        } else {
                            None
                        };
                        match compute_router_topk_cpu_reference(
                            &expected_logits,
                            topk,
                            scoring_func,
                            gate_bias.as_deref(),
                            e_score_corr.as_deref(),
                        ) {
                            Ok((expected_topk_weights, expected_topk_ids)) => {
                                self.trace_emit_f32_values(
                                    0,
                                    last_pos,
                                    0,
                                    Some(layer_idx),
                                    "prefill_layer",
                                    "router_topk_weights_last_cpu_ref",
                                    &expected_topk_weights,
                                );
                                let topk_summary = self.trace_emit_compare_summary(
                                    0,
                                    last_pos,
                                    0,
                                    Some(layer_idx),
                                    "prefill_layer",
                                    "router_topk_weights",
                                    "router_topk_weights_last_vendor",
                                    "router_topk_weights_last_cpu_ref",
                                    &actual_topk_weights,
                                    &expected_topk_weights,
                                );
                                let ids_match = actual_topk_ids == expected_topk_ids;
                                trace_emit_prefill_mark(
                                    self.trace.as_ref(),
                                    0,
                                    last_pos,
                                    0,
                                    Some(layer_idx),
                                    "prefill_layer",
                                    &format!(
                                        "phase=router_topk_ids actual=[{}] expected=[{}] match={} logits_max_abs={:.6} topk_w_max_abs={:.6} scoring_func={} gate_bias_present={} e_score_corr_present={}",
                                        format_i32_sample(&actual_topk_ids),
                                        format_i32_sample(&expected_topk_ids),
                                        ids_match,
                                        logits_summary.max_abs,
                                        topk_summary.max_abs,
                                        scoring_func,
                                        gate_bias.is_some(),
                                        e_score_corr.is_some(),
                                    ),
                                );
                            }
                            Err(err) => {
                                trace_emit_prefill_mark(
                                    self.trace.as_ref(),
                                    0,
                                    last_pos,
                                    0,
                                    Some(layer_idx),
                                    "prefill_layer",
                                    &format!("phase=router_topk_cpu_ref_failed error={}", err),
                                );
                            }
                        }
                    }
                    Err(err) => {
                        trace_emit_prefill_mark(
                            self.trace.as_ref(),
                            0,
                            last_pos,
                            0,
                            Some(layer_idx),
                            "prefill_layer",
                            &format!("phase=router_logits_cpu_ref_failed error={}", err),
                        );
                    }
                }
            }
            (Err(err), _, _, _)
            | (_, Err(err), _, _)
            | (_, _, Err(err), _)
            | (_, _, _, Err(err)) => {
                trace_emit_prefill_mark(
                    self.trace.as_ref(),
                    0,
                    last_pos,
                    0,
                    Some(layer_idx),
                    "prefill_layer",
                    &format!("phase=router_trace_download_failed error={}", err),
                );
            }
        }
    }

    fn trace_emit_f32_row(
        &self,
        step: usize,
        position: usize,
        token_id: usize,
        layer: Option<usize>,
        component: &str,
        tensor: &str,
        base_ptr: u64,
        row_idx: usize,
        row_elems: usize,
    ) {
        if row_elems == 0 {
            return;
        }
        let row_ptr = base_ptr + (row_idx * row_elems * 4) as u64;
        self.trace_emit_f32(
            step, position, token_id, layer, component, tensor, row_ptr, row_elems,
        );
    }

    fn trace_emit_f32_position_blocks(
        &self,
        step: usize,
        position: usize,
        token_id: usize,
        layer: Option<usize>,
        component: &str,
        tensor: &str,
        base_ptr: u64,
        pos_idx: usize,
        block_count: usize,
        block_stride_elems: usize,
        block_elems: usize,
    ) {
        let Some(trace) = self.trace.as_ref() else {
            return;
        };
        if !trace.should_emit(step, layer, component) || block_count == 0 || block_elems == 0 {
            return;
        }
        let max_blocks = (trace.max_elems / block_elems).max(1);
        let use_blocks = block_count.min(max_blocks);
        let count = use_blocks * block_elems;
        let _ = self.stream_sync();
        let mut values = vec![0.0f32; count];
        unsafe {
            for block in 0..use_blocks {
                let src_ptr = base_ptr
                    + (((block * block_stride_elems) + (pos_idx * block_elems)) * 4) as u64;
                let dst_ptr = values[block * block_elems..].as_mut_ptr() as *mut std::ffi::c_void;
                let _ = cuda_sys::lib().cuMemcpyDtoH_v2(dst_ptr, src_ptr, block_elems * 4);
            }
        }
        let mut min_v = f32::INFINITY;
        let mut max_v = f32::NEG_INFINITY;
        let mut sum = 0.0f64;
        let mut l2 = 0.0f64;
        let mut nan = 0usize;
        let mut inf = 0usize;
        for &v in &values {
            if v.is_nan() {
                nan += 1;
                continue;
            }
            if v.is_infinite() {
                inf += 1;
                continue;
            }
            min_v = min_v.min(v);
            max_v = max_v.max(v);
            let vf = v as f64;
            sum += vf;
            l2 += vf * vf;
        }
        let finite = count.saturating_sub(nan + inf).max(1);
        let sample = trace_format_sample(&values[..values.len().min(trace.sample_values)]);
        let layer_s = layer
            .map(|v| v.to_string())
            .unwrap_or_else(|| "-".to_string());
        eprintln!(
            "[KRASIS-TRACE] event=tensor step={} pos={} tok={} layer={} component={} tensor={} dtype=f32 n={} sample=[{}] l2={:.6} mean={:.6} min={:.6} max={:.6} nan={} inf={}",
            step,
            position,
            token_id,
            layer_s,
            component,
            tensor,
            count,
            sample,
            l2.sqrt(),
            sum / finite as f64,
            min_v,
            max_v,
            nan,
            inf,
        );
    }

    fn trace_prefill_layer_enabled(&self, step: usize, layer_idx: usize) -> bool {
        self.trace.as_ref().map_or(false, |t| {
            t.should_emit(step, Some(layer_idx), "prefill_layer")
        })
    }

    fn trace_emit_gqa_weight_surfaces(
        &self,
        step: usize,
        position: usize,
        layer_idx: usize,
        lw: &PrefillLayerWeights,
    ) {
        if !self.trace_prefill_layer_enabled(step, layer_idx) {
            return;
        }
        let backend = if lw.hqq_gqa.is_some() {
            "hqq4_dequant_bf16"
        } else {
            "bf16"
        };
        trace_emit_prefill_mark(
            self.trace.as_ref(),
            step,
            position,
            0,
            Some(layer_idx),
            "prefill_layer",
            &format!(
                "phase=gqa_attention_diag backend={} gated={} q_norm={} k_norm={}",
                backend,
                lw.gqa_gated,
                lw.q_norm_ptr != 0,
                lw.k_norm_ptr != 0,
            ),
        );
        if let Some(weight) = lw.q_proj_bf16.as_ref() {
            self.trace_emit_bf16(
                step,
                position,
                0,
                Some(layer_idx),
                "prefill_layer",
                "q_proj_weight_bf16",
                weight.ptr,
                weight.n * weight.k,
            );
        }
        if let Some(weight) = lw.k_proj_bf16.as_ref() {
            self.trace_emit_bf16(
                step,
                position,
                0,
                Some(layer_idx),
                "prefill_layer",
                "k_proj_weight_bf16",
                weight.ptr,
                weight.n * weight.k,
            );
        }
        if let Some(weight) = lw.v_proj_bf16.as_ref() {
            self.trace_emit_bf16(
                step,
                position,
                0,
                Some(layer_idx),
                "prefill_layer",
                "v_proj_weight_bf16",
                weight.ptr,
                weight.n * weight.k,
            );
        }
        if let Some(weight) = lw.o_proj_bf16.as_ref() {
            self.trace_emit_bf16(
                step,
                position,
                0,
                Some(layer_idx),
                "prefill_layer",
                "o_proj_weight_bf16",
                weight.ptr,
                weight.n * weight.k,
            );
        }
        if lw.q_norm_ptr != 0 {
            self.trace_emit_f32(
                step,
                position,
                0,
                Some(layer_idx),
                "prefill_layer",
                "q_norm_weight_f32",
                lw.q_norm_ptr,
                self.config.head_dim,
            );
        }
        if lw.k_norm_ptr != 0 {
            self.trace_emit_f32(
                step,
                position,
                0,
                Some(layer_idx),
                "prefill_layer",
                "k_norm_weight_f32",
                lw.k_norm_ptr,
                self.config.head_dim,
            );
        }
    }

    fn trace_emit_gqa_attention_cpu_diag(
        &self,
        step: usize,
        position: usize,
        layer_idx: usize,
        q_ptr: u64,
        k_ptr: u64,
        v_ptr: u64,
        attn_out_ptr: u64,
        m: usize,
        start_pos: usize,
    ) {
        if !self.trace_prefill_layer_enabled(step, layer_idx) {
            return;
        }
        let cfg = &self.config;
        if start_pos != 0 {
            trace_emit_prefill_mark(
                self.trace.as_ref(),
                step,
                position,
                0,
                Some(layer_idx),
                "prefill_layer",
                &format!(
                    "phase=gqa_attention_cpu_diag_skipped reason=cross_chunk start_pos={} m={}",
                    start_pos, m
                ),
            );
            return;
        }
        if m == 0 || cfg.num_q_heads == 0 || cfg.num_kv_heads == 0 || cfg.head_dim == 0 {
            return;
        }

        let _ = self.stream_sync();
        let last_pos = m - 1;
        let q_head = 0usize;
        let kv_head = q_head * cfg.num_kv_heads / cfg.num_q_heads;
        let q_stride = cfg.num_q_heads * cfg.head_dim;
        let kv_stride = cfg.num_kv_heads * cfg.head_dim;
        let q_offset = last_pos * q_stride + q_head * cfg.head_dim;
        let context_offset = last_pos * q_stride + q_head * cfg.head_dim;

        let q_bits = match download_device_u16(q_ptr + (q_offset * 2) as u64, cfg.head_dim) {
            Ok(v) => v,
            Err(err) => {
                trace_emit_prefill_mark(
                    self.trace.as_ref(),
                    step,
                    position,
                    0,
                    Some(layer_idx),
                    "prefill_layer",
                    &format!("phase=gqa_attention_cpu_diag_failed tensor=q error={}", err),
                );
                return;
            }
        };
        let context_bits =
            match download_device_u16(attn_out_ptr + (context_offset * 2) as u64, cfg.head_dim) {
                Ok(v) => v,
                Err(err) => {
                    trace_emit_prefill_mark(
                        self.trace.as_ref(),
                        step,
                        position,
                        0,
                        Some(layer_idx),
                        "prefill_layer",
                        &format!(
                            "phase=gqa_attention_cpu_diag_failed tensor=context error={}",
                            err
                        ),
                    );
                    return;
                }
            };

        let q = q_bits
            .iter()
            .map(|&bits| bf16_to_f32(bits))
            .collect::<Vec<_>>();
        let context_vendor = context_bits
            .iter()
            .map(|&bits| bf16_to_f32(bits))
            .collect::<Vec<_>>();
        let mut scores = vec![0.0f32; m];
        let mut v_rows = vec![0.0f32; m * cfg.head_dim];
        let scale = 1.0f32 / (cfg.head_dim as f32).sqrt();

        for pos in 0..m {
            let kv_offset = pos * kv_stride + kv_head * cfg.head_dim;
            let k_bits = match download_device_u16(k_ptr + (kv_offset * 2) as u64, cfg.head_dim) {
                Ok(v) => v,
                Err(err) => {
                    trace_emit_prefill_mark(
                        self.trace.as_ref(),
                        step,
                        position,
                        0,
                        Some(layer_idx),
                        "prefill_layer",
                        &format!("phase=gqa_attention_cpu_diag_failed tensor=k error={}", err),
                    );
                    return;
                }
            };
            let v_bits = match download_device_u16(v_ptr + (kv_offset * 2) as u64, cfg.head_dim) {
                Ok(v) => v,
                Err(err) => {
                    trace_emit_prefill_mark(
                        self.trace.as_ref(),
                        step,
                        position,
                        0,
                        Some(layer_idx),
                        "prefill_layer",
                        &format!("phase=gqa_attention_cpu_diag_failed tensor=v error={}", err),
                    );
                    return;
                }
            };
            let mut dot = 0.0f32;
            for dim in 0..cfg.head_dim {
                dot += q[dim] * bf16_to_f32(k_bits[dim]);
                v_rows[pos * cfg.head_dim + dim] = bf16_to_f32(v_bits[dim]);
            }
            scores[pos] = dot * scale;
        }

        let max_score = scores
            .iter()
            .copied()
            .fold(f32::NEG_INFINITY, |acc, v| acc.max(v));
        let mut probs = vec![0.0f32; m];
        let mut sum_exp = 0.0f32;
        for pos in 0..m {
            let value = (scores[pos] - max_score).exp();
            probs[pos] = value;
            sum_exp += value;
        }
        if sum_exp > 0.0 {
            for prob in &mut probs {
                *prob /= sum_exp;
            }
        }

        let mut context_cpu = vec![0.0f32; cfg.head_dim];
        for pos in 0..m {
            let prob = probs[pos];
            for dim in 0..cfg.head_dim {
                context_cpu[dim] += prob * v_rows[pos * cfg.head_dim + dim];
            }
        }

        self.trace_emit_f32_values(
            step,
            position,
            0,
            Some(layer_idx),
            "prefill_layer",
            "attention_scores_last_head0_cpu",
            &scores,
        );
        self.trace_emit_f32_values(
            step,
            position,
            0,
            Some(layer_idx),
            "prefill_layer",
            "attention_probs_last_head0_cpu",
            &probs,
        );
        self.trace_emit_f32_values(
            step,
            position,
            0,
            Some(layer_idx),
            "prefill_layer",
            "attention_context_last_head0_cpu",
            &context_cpu,
        );
        self.trace_emit_f32_values(
            step,
            position,
            0,
            Some(layer_idx),
            "prefill_layer",
            "attention_context_last_head0_vendor",
            &context_vendor,
        );
        self.trace_emit_compare_summary(
            step,
            position,
            0,
            Some(layer_idx),
            "prefill_layer",
            "attention_context_head0",
            "attention_context_last_head0_vendor",
            "attention_context_last_head0_cpu",
            &context_vendor,
            &context_cpu,
        );
    }

    /// Update HCS snapshot from the decode store's current HCS state.
    /// Must be called before each prefill so we know which experts are GPU-resident.
    pub fn update_hcs_snapshot(&mut self, cache_fast: &[[u64; 4]], num_experts_per_layer: usize) {
        self.hcs_cache_fast = cache_fast.to_vec();
        self.hcs_num_experts_per_layer = num_experts_per_layer;
    }

    pub fn set_prefill_pinning_disabled(&mut self, disabled: bool) {
        self.prefill_pinning_disabled = disabled;
        if disabled {
            self.optional_pinning_budget_mb = Some(0);
        }
    }

    pub fn set_optional_pinning_budget_mb(&mut self, budget_mb: Option<usize>) {
        self.optional_pinning_budget_mb = budget_mb;
    }

    pub fn set_external_prefill_inputs(
        &mut self,
        embeddings_ptr: u64,
        mrope_cos_ptr: u64,
        mrope_sin_ptr: u64,
        mrope_half_dim: usize,
        vision_block_ids_ptr: u64,
        vision_visible_left_ptr: u64,
        vision_visible_right_ptr: u64,
        vision_max_tokens: usize,
    ) {
        self.external_prefill_embeddings_ptr = embeddings_ptr;
        self.external_mrope_cos_ptr = mrope_cos_ptr;
        self.external_mrope_sin_ptr = mrope_sin_ptr;
        self.external_mrope_half_dim = mrope_half_dim;
        self.external_vision_block_ids_ptr = vision_block_ids_ptr;
        self.external_vision_visible_left_ptr = vision_visible_left_ptr;
        self.external_vision_visible_right_ptr = vision_visible_right_ptr;
        self.config.deepseek_v4_vision_max_tokens = vision_max_tokens;
    }

    pub fn clear_external_prefill_inputs(&mut self) {
        self.external_prefill_embeddings_ptr = 0;
        self.external_mrope_cos_ptr = 0;
        self.external_mrope_sin_ptr = 0;
        self.external_mrope_half_dim = 0;
        self.external_vision_block_ids_ptr = 0;
        self.external_vision_visible_left_ptr = 0;
        self.external_vision_visible_right_ptr = 0;
        self.config.deepseek_v4_vision_max_tokens = 0;
    }

    pub fn last_prepare_post_alloc_free_mb(&self) -> usize {
        self.last_prepare_post_alloc_free_mb
    }

    pub fn update_measured_prefill_runtime_overhead_mb(
        &mut self,
        post_alloc_free_mb: usize,
        min_free_mb: usize,
    ) {
        let observed_mb = post_alloc_free_mb.saturating_sub(min_free_mb);
        let observed_bytes = observed_mb.saturating_mul(1024 * 1024);
        if observed_bytes > self.measured_prefill_runtime_overhead_bytes {
            self.measured_prefill_runtime_overhead_bytes = observed_bytes;
        }
    }

    pub fn set_prefill_runtime_chunk_cap(&mut self, cap: Option<usize>) {
        self.prefill_runtime_chunk_cap = cap.map(|v| v.max(128));
    }

    pub fn clear_prefill_runtime_chunk_cap(&mut self) {
        self.prefill_runtime_chunk_cap = None;
    }

    pub fn cold_staging_retry_chunk_cap(&self) -> Option<usize> {
        let failure = self.last_cold_staging_failure?;
        if failure.requested_slots == 0
            || failure.max_safe_slots == 0
            || failure.chunk_tokens <= 128
        {
            return None;
        }
        let proportional =
            failure.chunk_tokens.saturating_mul(failure.max_safe_slots) / failure.requested_slots;
        let next_cap = proportional
            .min(failure.chunk_tokens.saturating_sub(1))
            .max(128);
        Some(clean_runtime_chunk_tokens(failure.prompt_tokens, next_cap))
    }

    fn all_expert_cold_staging_bytes(&self) -> usize {
        if self.cold_expert_bytes == 0 || self.config.n_routed_experts == 0 {
            return 0;
        }
        self.config
            .n_routed_experts
            .saturating_mul(self.cold_expert_bytes)
    }

    fn measured_post_scratch_runtime_reserve_bytes(&self, tokens: usize) -> usize {
        project_prefill_runtime_reserve_bytes(
            self.prefill_runtime_reserve_calibration.as_deref(),
            self.measured_prefill_runtime_overhead_bytes,
            tokens,
        )
    }

    pub fn minimum_prefill_entry_free_bytes(&self, prompt_tokens: usize) -> usize {
        let safety_margin_mb = self.safety_margin_mb.max(PREFILL_SAFETY_MARGIN_MB);
        let safety_bytes = safety_margin_mb.saturating_mul(1024 * 1024);
        let scratch_tokens = clean_runtime_chunk_tokens(prompt_tokens, 128);
        let scratch_bytes =
            estimate_scratch_vram_for_prompt(&self.config, scratch_tokens, prompt_tokens)
                .saturating_add(self.measured_scratch_alloc_overhead_bytes);
        let mut post_scratch_runtime_reserve_bytes =
            self.measured_post_scratch_runtime_reserve_bytes(prompt_tokens);
        let mamba2_runtime_reserve_bytes =
            estimate_mamba2_ssd_runtime_temp_bytes(&self.config, prompt_tokens);
        let combined_runtime_reserve_bytes = self
            .all_expert_cold_staging_bytes()
            .saturating_add(mamba2_runtime_reserve_bytes);
        if combined_runtime_reserve_bytes > post_scratch_runtime_reserve_bytes {
            post_scratch_runtime_reserve_bytes = combined_runtime_reserve_bytes;
        }
        scratch_bytes
            .saturating_add(post_scratch_runtime_reserve_bytes)
            .saturating_add(safety_bytes)
    }

    fn measured_cold_slots_from_prescan(&self) -> usize {
        if self.cold_expert_bytes == 0 || self.config.n_routed_experts == 0 {
            return 0;
        }
        let mut max_cold = 0usize;
        for (mi, layer_chunks) in self.prescan_active_experts.iter().enumerate() {
            let hcs_layer_idx = self.model_layer_for_moe_ordinal(mi).unwrap_or(mi);
            for active in layer_chunks {
                let mut cold = 0usize;
                for &eid in active {
                    if self.expert_lookup(hcs_layer_idx, eid).is_some() {
                        continue;
                    }
                    let pinned = self.pinning_active
                        && mi < self.pinned_expert_offsets.len()
                        && eid < self.pinned_expert_offsets[mi].len()
                        && self.pinned_expert_offsets[mi][eid].is_some();
                    if !pinned {
                        cold += 1;
                    }
                }
                max_cold = max_cold.max(cold);
            }
        }
        max_cold
    }

    fn hcs_cached_expert_count(&self) -> usize {
        self.hcs_cache_fast
            .iter()
            .filter(|ptrs| ptrs[0] != 0 || ptrs[1] != 0 || ptrs[2] != 0 || ptrs[3] != 0)
            .count()
    }

    fn record_gqa_kv_cross_stage(
        &self,
        elapsed_ms: f64,
        current_tokens: usize,
        total_kv_tokens: usize,
    ) {
        self.t_gqa_kv_prep
            .set(self.t_gqa_kv_prep.get() + elapsed_ms);
        self.t_gqa_kv_cross_stage
            .set(self.t_gqa_kv_cross_stage.get() + elapsed_ms);
        self.gqa_kv_cross_stage_calls
            .set(self.gqa_kv_cross_stage_calls.get() + 1);
        self.gqa_kv_cross_current_tokens
            .set(self.gqa_kv_cross_current_tokens.get() + current_tokens as u64);
        self.gqa_kv_cross_total_tokens
            .set(self.gqa_kv_cross_total_tokens.get() + total_kv_tokens as u64);
    }

    fn record_gqa_kv_append(&self, elapsed_ms: f64, kernel_ms: Option<f64>, sync_ms: f64) {
        self.t_gqa_kv_prep
            .set(self.t_gqa_kv_prep.get() + elapsed_ms);
        self.t_gqa_kv_append
            .set(self.t_gqa_kv_append.get() + elapsed_ms);
        self.gqa_kv_append_calls
            .set(self.gqa_kv_append_calls.get() + 1);
        self.t_gqa_kv_append_sync
            .set(self.t_gqa_kv_append_sync.get() + sync_ms);
        if let Some(ms) = kernel_ms {
            self.t_gqa_kv_append_kernel
                .set(self.t_gqa_kv_append_kernel.get() + ms);
            self.gqa_kv_append_kernel_calls
                .set(self.gqa_kv_append_kernel_calls.get() + 1);
        }
    }

    fn gqa_timing_event_start(&self, label: &str) -> Result<bool, String> {
        if !self.gqa_timing_enabled.get()
            || self.gqa_timing_start_event.is_null()
            || self.gqa_timing_stop_event.is_null()
        {
            return Ok(false);
        }
        unsafe {
            let err = cuda_sys::lib().cuEventRecord(self.gqa_timing_start_event, self.stream);
            if err != cuda_sys::CUresult::CUDA_SUCCESS {
                return Err(format!("record {label} timing start event: {:?}", err));
            }
        }
        Ok(true)
    }

    fn gqa_timing_event_stop(&self, active: bool, label: &str) -> Result<(), String> {
        if !active {
            return Ok(());
        }
        unsafe {
            let err = cuda_sys::lib().cuEventRecord(self.gqa_timing_stop_event, self.stream);
            if err != cuda_sys::CUresult::CUDA_SUCCESS {
                return Err(format!("record {label} timing stop event: {:?}", err));
            }
        }
        Ok(())
    }

    fn gqa_timing_event_elapsed_ms(
        &self,
        active: bool,
        label: &str,
    ) -> Result<Option<f64>, String> {
        if !active {
            return Ok(None);
        }
        let mut elapsed_ms: f32 = 0.0;
        unsafe {
            let err = cuda_sys::lib().cuEventElapsedTime(
                &mut elapsed_ms,
                self.gqa_timing_start_event,
                self.gqa_timing_stop_event,
            );
            if err != cuda_sys::CUresult::CUDA_SUCCESS {
                return Err(format!("elapsed {label} timing event: {:?}", err));
            }
        }
        Ok(Some(elapsed_ms as f64))
    }

    fn stream_sync_timed(&self) -> Result<f64, String> {
        let t0 = Instant::now();
        self.stream_sync()?;
        Ok(t0.elapsed().as_secs_f64() * 1000.0)
    }

    fn mamba2_prefill_timing_enabled(&self) -> bool {
        self.gqa_timing_enabled.get() || prefill_liveness_timing_enabled()
    }

    fn mamba2_timing_start(&self, label: &str) -> Result<Option<(Instant, bool)>, String> {
        if !self.mamba2_prefill_timing_enabled() {
            return Ok(None);
        }
        let event_active = if self.gqa_timing_enabled.get() {
            self.gqa_timing_event_start(label)?
        } else {
            false
        };
        Ok(Some((Instant::now(), event_active)))
    }

    fn mamba2_timing_finish(
        &self,
        stage_idx: usize,
        label: &str,
        started: Option<(Instant, bool)>,
    ) -> Result<f64, String> {
        let Some((t0, event_active)) = started else {
            return Ok(0.0);
        };
        if self.gqa_timing_enabled.get() {
            self.gqa_timing_event_stop(event_active, label)?;
        }
        let sync_ms = self.stream_sync_timed()?;
        let event_ms = if self.gqa_timing_enabled.get() {
            self.gqa_timing_event_elapsed_ms(event_active, label)?
        } else {
            None
        };
        let wall_ms = t0.elapsed().as_secs_f64() * 1000.0;
        self.record_mamba2_stage_timing(stage_idx, wall_ms, event_ms, sync_ms);
        Ok(wall_ms)
    }

    fn record_mamba2_stage_timing(
        &self,
        stage_idx: usize,
        wall_ms: f64,
        event_ms: Option<f64>,
        sync_ms: f64,
    ) {
        if stage_idx >= MAMBA2_PREFILL_TIMING_STAGES {
            return;
        }
        self.t_mamba2_stage_wall[stage_idx]
            .set(self.t_mamba2_stage_wall[stage_idx].get() + wall_ms);
        if let Some(ms) = event_ms {
            self.t_mamba2_stage_event[stage_idx]
                .set(self.t_mamba2_stage_event[stage_idx].get() + ms);
        }
        self.t_mamba2_stage_sync[stage_idx]
            .set(self.t_mamba2_stage_sync[stage_idx].get() + sync_ms);
        self.mamba2_stage_calls[stage_idx].set(self.mamba2_stage_calls[stage_idx].get() + 1);
    }

    fn glm5_timing_start(&self, label: &str) -> Result<Option<(Instant, bool)>, String> {
        if !self.gqa_timing_enabled.get() {
            return Ok(None);
        }
        let event_active = self.gqa_timing_event_start(label)?;
        Ok(Some((Instant::now(), event_active)))
    }

    fn glm5_timing_finish(
        &self,
        stage_idx: usize,
        label: &str,
        started: Option<(Instant, bool)>,
    ) -> Result<(), String> {
        let Some((t0, event_active)) = started else {
            return Ok(());
        };
        self.gqa_timing_event_stop(event_active, label)?;
        let sync_ms = self.stream_sync_timed()?;
        let event_ms = self
            .gqa_timing_event_elapsed_ms(event_active, label)?
            .unwrap_or(0.0);
        if stage_idx < GLM5_PREFILL_TIMING_STAGES {
            self.t_glm5_stage_wall[stage_idx]
                .set(self.t_glm5_stage_wall[stage_idx].get() + t0.elapsed().as_secs_f64() * 1000.0);
            self.t_glm5_stage_event[stage_idx]
                .set(self.t_glm5_stage_event[stage_idx].get() + event_ms);
            self.t_glm5_stage_sync[stage_idx]
                .set(self.t_glm5_stage_sync[stage_idx].get() + sync_ms);
            self.glm5_stage_calls[stage_idx].set(self.glm5_stage_calls[stage_idx].get() + 1);
        }
        Ok(())
    }

