/// Find a vendored .so file built by the sidecar build step.
/// Searches: 1) env var, 2) installed package, 3) next to executable.
fn find_vendor_so(name: &str) -> Option<String> {
    // 1. Look in env var (uppercase, dots/hyphens → underscore)
    for candidate_name in sidecar_name_candidates(name) {
        let env_name = candidate_name
            .replace('.', "_")
            .replace('-', "_")
            .to_uppercase();
        let env_key = format!("KRASIS_{}", env_name);
        if let Ok(p) = std::env::var(&env_key) {
            if std::path::Path::new(&p).exists() {
                return Some(p);
            }
        }
    }

    for candidate_name in sidecar_name_candidates(name) {
        if let Some(p) = installed_package_sidecar(&candidate_name) {
            return Some(p);
        }
    }

    // 2. Look next to the current executable
    if let Ok(exe) = std::env::current_exe() {
        if let Some(dir) = exe.parent() {
            for candidate_name in sidecar_name_candidates(name) {
                let p = dir.join(candidate_name);
                if p.exists() {
                    return Some(p.to_string_lossy().to_string());
                }
            }
        }
    }

    None
}

/// Load vendored FLA (Flash Linear Attention) kernels from libkrasis_fla.so.
/// For LA models this is required unless the user explicitly opted out with
/// KRASIS_NO_FLA, because silently falling back to the older custom LA path
/// hides packaging/runtime regressions and degrades performance.
pub fn load_fla(require_for_la_model: bool, nv: usize) -> Result<Option<FlaKernels>, String> {
    let fail_or_warn = |message: String| -> Result<Option<FlaKernels>, String> {
        if require_for_la_model {
            Err(format!(
                "{message}. Refusing to fall back to custom LA kernels for a linear-attention model. \
Set KRASIS_NO_FLA=1 only if you explicitly want the slower custom LA path."
            ))
        } else {
            log::warn!("{message} — FLA disabled");
            Ok(None)
        }
    };

    if std::env::var("KRASIS_NO_FLA").is_ok() {
        log::info!("KRASIS_NO_FLA set — FLA disabled, using custom LA kernels");
        return Ok(None);
    }

    // Detect GPU compute capability and load the best-matching FLA .so.
    // We ship pre-compiled cubins for multiple GPU architectures (sm_80, sm_89,
    // sm_90, sm_120).  Selection priority:
    //   1. Exact arch match (e.g. sm_120 on a 5090)
    //   2. Same-generation base arch (e.g. sm_80 on an sm_86 RTX 3090)
    //   3. Highest available .so if the GPU is newer than anything we compiled
    //      for (forward compat — cubins from the latest gen we ship are the
    //      best chance of working on a future GPU)
    // Pre-Ampere (sm_75 and below) is not supported — Marlin INT4 kernels
    // require Ampere or newer.
    let path = {
        // Query GPU compute capability via CUDA driver API
        let mut cc_major: i32 = 0;
        let mut cc_minor: i32 = 0;
        unsafe {
            cuda_sys::lib().cuDeviceGetAttribute(
                &mut cc_major,
                cuda_sys::CUdevice_attribute_enum::CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MAJOR,
                0,
            );
            cuda_sys::lib().cuDeviceGetAttribute(
                &mut cc_minor,
                cuda_sys::CUdevice_attribute_enum::CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MINOR,
                0,
            );
        }
        let arch = cc_major * 10 + cc_minor;

        if arch > 0 && arch < 80 {
            return fail_or_warn(format!(
                "GPU sm_{} (pre-Ampere) is not supported. \
                 Krasis requires an Ampere (sm_80) or newer GPU.",
                arch
            ));
        }

        let mut found: Option<String> = None;

        if arch > 0 {
            // 1. Exact arch match (e.g. libkrasis_fla_sm120.so)
            let arch_name = format!("libkrasis_fla_sm{}.so", arch);
            if let Some(p) = find_vendor_so(&arch_name) {
                log::info!(
                    "Found arch-specific FLA library: {} (GPU sm_{})",
                    arch_name,
                    arch
                );
                found = Some(p);
            }

            // 2. Same-generation base arch (sm_X0 cubins run on sm_XY via
            //    CUDA binary compatibility within the same major version)
            if found.is_none() {
                let base_arch = cc_major * 10;
                if base_arch != arch {
                    let fallback_name = format!("libkrasis_fla_sm{}.so", base_arch);
                    if let Some(p) = find_vendor_so(&fallback_name) {
                        log::info!(
                            "GPU sm_{} — using compatible FLA library: {} (base arch sm_{})",
                            arch,
                            fallback_name,
                            base_arch
                        );
                        found = Some(p);
                    }
                }
            }

            // 3. Forward compatibility: if the GPU is newer than anything we
            //    compiled for, try the highest available arch .so.  This is
            //    best-effort — it may work (especially within the same CUDA
            //    generation) or fail at kernel launch with a clear error.
            if found.is_none() {
                let mut best: Option<(u32, String)> = None;
                for candidate_arch in [120, 90, 89, 80] {
                    let name = format!("libkrasis_fla_sm{}.so", candidate_arch);
                    if let Some(p) = find_vendor_so(&name) {
                        match best {
                            None => best = Some((candidate_arch, p)),
                            Some((prev, _)) if candidate_arch > prev => {
                                best = Some((candidate_arch, p));
                            }
                            _ => {}
                        }
                        break; // list is descending, first hit is highest
                    }
                }
                if let Some((best_arch, p)) = best {
                    log::warn!(
                        "GPU sm_{} is newer than any pre-compiled FLA library. \
                         Using sm_{} as best-effort forward compatibility. \
                         If FLA kernels fail, rebuild with ./dev build on this GPU.",
                        arch,
                        best_arch
                    );
                    found = Some(p);
                }
            }
        }

        match found {
            Some(p) => p,
            None => {
                let msg = if arch > 0 {
                    format!(
                        "No FLA library found for GPU sm_{}. \
                         Rebuild with ./dev build or reinstall from a release wheel.",
                        arch
                    )
                } else {
                    "FLA library not found (could not detect GPU compute capability)".to_string()
                };
                return fail_or_warn(msg);
            }
        }
    };
    unsafe {
        let lib = match open_sidecar_library(&path, "FLA") {
            Some(lib) => lib,
            None => return fail_or_warn(format!("loading FLA sidecar failed: {}", path)),
        };

        // Initialize FLA modules (loads cubins into CUDA context)
        let init_fn = match sidecar_symbol::<FlaInitFn>(lib, b"krasis_fla_init\0") {
            Some(sym) => sym,
            None => return fail_or_warn(format!("krasis_fla_init not found in {}", path)),
        };
        let rc = init_fn();
        if rc != 0 {
            return fail_or_warn(format!("krasis_fla_init() failed with rc={}", rc));
        }

        // Load all 6 kernel function pointers.
        // FLA kernels have H (num_v_heads) baked in as a Triton constexpr.
        // Try H-specific symbols first (e.g. _h64), fall back to generic.
        eprintln!("[FLA] Loading kernels for H={} from {}", nv, path);
        macro_rules! load_fla_sym {
            ($name:expr, $ty:ty) => {{
                match sidecar_symbol_for_h::<$ty>(lib, $name, nv, &path) {
                    Ok(sym) => sym,
                    Err(msg) => {
                        return fail_or_warn(msg);
                    }
                }
            }};
        }

        let use_state_bv64 = std::env::var("KRASIS_FLA_STATE_BV64").ok().as_deref() == Some("1");
        let state_recurrence_bv64 = if use_state_bv64 {
            let sym = match sidecar_symbol_for_h::<FlaStateRecurrenceFn>(
                lib,
                "krasis_fla_chunk_gated_delta_rule_fwd_kernel_h_blockdim64_bv64",
                nv,
                &path,
            ) {
                Ok(sym) => sym,
                Err(msg) => {
                    return fail_or_warn(format!(
                        "{msg}; KRASIS_FLA_STATE_BV64=1 requires the BV64 FLA sidecar variant"
                    ));
                }
            };
            Some(sym)
        } else {
            None
        };

        let kernels = FlaKernels {
            cumsum: load_fla_sym!(
                "krasis_fla_chunk_local_cumsum_scalar_kernel",
                FlaScalarKernelFn
            ),
            kkt: load_fla_sym!("krasis_fla_chunk_scaled_dot_kkt_fwd_kernel", FlaKktKernelFn),
            solve_tril: load_fla_sym!(
                "krasis_fla_merge_16x16_to_64x64_inverse_kernel",
                FlaSolveTrilFn
            ),
            wy_repr: load_fla_sym!("krasis_fla_recompute_w_u_fwd_kernel", FlaWyReprFn),
            state_recurrence: load_fla_sym!(
                "krasis_fla_chunk_gated_delta_rule_fwd_kernel_h_blockdim64",
                FlaStateRecurrenceFn
            ),
            state_recurrence_bv64,
            state_recurrence_bv64_enabled: use_state_bv64,
            output: load_fla_sym!("krasis_fla_chunk_fwd_kernel_o", FlaOutputFn),
            kda_gate_cumsum: load_fla_sym!(
                "krasis_fla_kda_gate_chunk_cumsum_vector_kernel",
                FlaKdaGateCumsumFn
            ),
            kda_intra: load_fla_sym!(
                "krasis_fla_chunk_kda_fwd_kernel_intra_sub_chunk",
                FlaKdaIntraFn
            ),
            kda_inter_solve: load_fla_sym!(
                "krasis_fla_chunk_kda_fwd_kernel_inter_solve_fused",
                FlaKdaInterSolveFn
            ),
            kda_wy_repr: load_fla_sym!("krasis_fla_recompute_w_u_fwd_kda_kernel", FlaKdaWyReprFn),
            kda_state_recurrence: load_fla_sym!(
                "krasis_fla_chunk_kda_state_recurrence",
                FlaStateRecurrenceFn
            ),
            kda_output: load_fla_sym!("krasis_fla_chunk_gla_fwd_kernel_o_kda", FlaKdaOutputFn),
        };

        log::info!("Loaded FLA (Flash Linear Attention) kernels from {}", path);
        Ok(Some(kernels))
    }
}

// ════════════════════════════════════════════════════════════════════════
//  Kernel Unit Tests
// ════════════════════════════════════════════════════════════════════════
//
// These tests are compiled ONLY by `cargo test` (#[cfg(test)]).
// They are completely absent from the release binary.
// Test data lives in tests/kernel_test_data/ (raw .bin + meta.json).
// See feature-unit-test.md for architecture and rationale.
//
#[cfg(test)]
mod chunk_plan_tests {
    use super::{
        build_balanced_prefill_chunk_plan, build_balanced_prefill_chunk_plan_at_boundary,
        build_image_aware_prefill_chunk_plan, build_prefill_chunk_plan,
        build_prefill_chunk_plan_at_boundary, glm5_hc_temp_state_elements_from_geometry,
        kimi_delta_state_elements_from_geometry, portable_predicted_w1_requires_exact_resize,
        prefill_chunk_guard_prompt_tokens, project_prefill_runtime_reserve_bytes,
        shared_moe_inter_scratch_elements, stage_exact_export_launch_scalars,
        stage_exact_export_range, PortablePredictedW1Policy,
    };

    #[test]
    fn glm5_hc_temp_state_is_checkpoint_geometry_derived() {
        assert_eq!(
            glm5_hc_temp_state_elements_from_geometry(4, 4096, &[5, 5, 0], 300),
            300 * 4 * 4096
        );
        assert_eq!(
            glm5_hc_temp_state_elements_from_geometry(4, 4096, &[4, 4, 4], 300),
            0
        );
        assert_eq!(
            glm5_hc_temp_state_elements_from_geometry(0, 4096, &[5, 5, 0], 300),
            0
        );
    }

    #[test]
    fn kimi_delta_state_reset_is_checkpoint_geometry_derived() {
        assert_eq!(
            kimi_delta_state_elements_from_geometry(64, 128, 4).unwrap(),
            (3 * 64 * 128 * 3, 64 * 128 * 128)
        );
        assert!(kimi_delta_state_elements_from_geometry(0, 128, 4).is_err());
        assert!(kimi_delta_state_elements_from_geometry(64, 0, 4).is_err());
        assert!(kimi_delta_state_elements_from_geometry(64, 128, 1).is_err());
    }

    #[test]
    fn uses_single_chunk_when_prompt_fits() {
        assert_eq!(build_prefill_chunk_plan(5_000, 16_000), vec![5_000]);
    }

    #[test]
    fn deepseek_v4_image_chunk_plan_keeps_each_sentinel_block_whole() {
        let vocab = 100u32;
        let mut tokens = vec![1u32; 110];
        tokens.extend([100u32; 40]);
        tokens.extend([2u32; 150]);
        let plan = build_image_aware_prefill_chunk_plan(&tokens, vocab as usize, 128).unwrap();
        assert_eq!(plan.iter().sum::<usize>(), tokens.len());
        let image_start = 110usize;
        let image_end = 150usize;
        let boundaries = plan
            .iter()
            .scan(0usize, |sum, &chunk| {
                *sum += chunk;
                Some(*sum)
            })
            .collect::<Vec<_>>();
        assert!(boundaries
            .iter()
            .all(|&boundary| boundary <= image_start || boundary >= image_end));

        let oversized = vec![100u32; 129];
        assert!(
            build_image_aware_prefill_chunk_plan(&oversized, vocab as usize, 128)
                .unwrap_err()
                .contains("image span has 129 tokens")
        );
    }

    #[test]
    fn portable_predicted_w1_auto_threshold_uses_computed_suffix_length() {
        let policy = PortablePredictedW1Policy::AutoThreshold(4_200);
        let restored_prefix_tokens = 40_000;
        let computed_suffix_tokens = 50;
        assert!(!policy.active(computed_suffix_tokens));
        assert!(policy.active(restored_prefix_tokens + computed_suffix_tokens));
        assert!(!policy.active(4_199));
        assert!(policy.active(4_200));
        assert!(policy.active(40_000));
    }

    #[test]
    fn portable_predicted_w1_uncalibrated_and_disabled_auto_are_fail_closed() {
        assert!(!PortablePredictedW1Policy::AutoUncalibrated.active(40_000));
        assert!(!PortablePredictedW1Policy::AutoDisabled.active(40_000));
        assert!(!PortablePredictedW1Policy::Off.active(40_000));
        assert!(PortablePredictedW1Policy::AutoCalibration(true).active(1));
        assert!(!PortablePredictedW1Policy::AutoCalibration(false).active(40_000));
    }

    #[test]
    fn portable_predicted_w1_cancels_only_when_exact_route_outgrows_staging() {
        assert!(!portable_predicted_w1_requires_exact_resize(false, 9, 8));
        assert!(!portable_predicted_w1_requires_exact_resize(true, 8, 8));
        assert!(portable_predicted_w1_requires_exact_resize(true, 9, 8));
    }

    #[test]
    fn keeps_normal_tail_as_max_safe_plus_remainder() {
        assert_eq!(
            build_prefill_chunk_plan(20_000, 17_053),
            vec![17_053, 2_947]
        );
    }

    #[test]
    fn smooths_pathological_tiny_tail_without_adding_passes() {
        let plan = build_prefill_chunk_plan(50_000, 16_640);
        assert_eq!(plan, vec![12_500, 12_500, 12_500, 12_500]);
        assert_eq!(plan.iter().sum::<usize>(), 50_000);
        assert!(plan.iter().all(|&chunk| chunk <= 16_640));
    }

    #[test]
    fn balances_cross_chunk_attention_work_without_adding_passes() {
        let plan = build_balanced_prefill_chunk_plan(39_920, 31_265);
        assert_eq!(plan, vec![19_960, 19_960]);
        assert_eq!(plan.iter().sum::<usize>(), 39_920);
        assert!(plan.iter().all(|&chunk| chunk <= 31_265));
    }

    #[test]
    fn preserves_exact_session_boundary() {
        let plan = build_prefill_chunk_plan_at_boundary(50_000, 16_640, Some(23_417)).unwrap();
        assert_eq!(plan.iter().sum::<usize>(), 50_000);
        assert!(plan.iter().all(|&chunk| chunk <= 16_640));
        let ends: Vec<_> = plan
            .iter()
            .scan(0usize, |sum, &chunk| {
                *sum += chunk;
                Some(*sum)
            })
            .collect();
        assert!(ends.contains(&23_417));
    }

    #[test]
    fn balanced_plan_preserves_exact_session_boundary() {
        let plan =
            build_balanced_prefill_chunk_plan_at_boundary(50_000, 16_640, Some(23_417)).unwrap();
        assert_eq!(plan.iter().sum::<usize>(), 50_000);
        assert!(plan.iter().all(|&chunk| chunk <= 16_640));
        let ends: Vec<_> = plan
            .iter()
            .scan(0usize, |sum, &chunk| {
                *sum += chunk;
                Some(*sum)
            })
            .collect();
        assert!(ends.contains(&23_417));
    }

    #[test]
    fn multichunk_hcs_guard_uses_complete_logical_prompt() {
        assert_eq!(
            prefill_chunk_guard_prompt_tokens(62_403, 31_202).unwrap(),
            62_403
        );
    }

    #[test]
    fn continuation_hcs_guard_preserves_restored_prefix_length() {
        assert_eq!(
            prefill_chunk_guard_prompt_tokens(62_403, 8_000).unwrap(),
            62_403
        );
    }

    #[test]
    fn hcs_guard_rejects_missing_or_impossible_lengths() {
        assert!(prefill_chunk_guard_prompt_tokens(0, 128).is_err());
        assert!(prefill_chunk_guard_prompt_tokens(1_000, 0).is_err());
        assert!(prefill_chunk_guard_prompt_tokens(1_000, 1_001).is_err());
    }

    #[test]
    fn runtime_reserve_projection_cannot_discard_measured_high_water() {
        let short_bytes = 3_264usize * 1024 * 1024;
        let long_bytes = 3_198usize * 1024 * 1024;
        let points = [(500, short_bytes), (39_920, long_bytes)];
        assert_eq!(
            project_prefill_runtime_reserve_bytes(Some(&points), short_bytes, 62_403,),
            short_bytes,
        );
    }

    #[test]
    fn runtime_reserve_projection_still_extrapolates_positive_growth() {
        let short_bytes = 100usize * 1024 * 1024;
        let long_bytes = 200usize * 1024 * 1024;
        let points = [(100, short_bytes), (200, long_bytes)];
        assert_eq!(
            project_prefill_runtime_reserve_bytes(Some(&points), long_bytes, 100,),
            short_bytes,
        );
        assert_eq!(
            project_prefill_runtime_reserve_bytes(Some(&points), long_bytes, 150,),
            long_bytes,
        );
        assert_eq!(
            project_prefill_runtime_reserve_bytes(Some(&points), long_bytes, 300,),
            300usize * 1024 * 1024,
        );
    }

    #[test]
    fn runtime_reserve_uses_next_probe_for_concave_interval_growth() {
        let mb = 1024usize * 1024;
        let points = [(500, 3_524 * mb), (4_000, 3_624 * mb)];
        assert_eq!(
            project_prefill_runtime_reserve_bytes(Some(&points), 3_624 * mb, 1_000),
            3_624 * mb,
        );
    }

    #[test]
    fn runtime_reserve_projection_retains_interior_high_water() {
        let mb = 1024usize * 1024;
        let points = [(500, 3_500 * mb), (4_000, 3_660 * mb), (40_000, 3_660 * mb)];
        assert_eq!(
            project_prefill_runtime_reserve_bytes(Some(&points), 3_660 * mb, 5_000),
            3_660 * mb,
        );
    }

    #[test]
    fn rejects_non_internal_session_boundary() {
        assert!(build_prefill_chunk_plan_at_boundary(100, 128, Some(0)).is_err());
        assert!(build_prefill_chunk_plan_at_boundary(100, 128, Some(100)).is_err());
    }

    #[test]
    fn continuation_stage_export_preserves_restored_prefix() {
        assert_eq!(
            stage_exact_export_range(8_000, 6_000, 16_000).unwrap(),
            (6_000, 2_000)
        );
        assert_eq!(
            stage_exact_export_range(20_000, 10_000, 8_000).unwrap(),
            (12_000, 8_000)
        );
        assert_eq!(
            stage_exact_export_range(8_000, 0, 16_000).unwrap(),
            (0, 8_000)
        );
    }

    #[test]
    fn incremental_stage_export_passes_nonzero_start_before_norm_mode() {
        assert_eq!(
            stage_exact_export_launch_scalars(31, 512, 262_144, 3_729, 2),
            (31, 512, 262_144, 3_729, 2)
        );
    }

    #[test]
    fn shared_intermediate_scratch_covers_split_dense_geometry() {
        let tokens = 4_699usize;
        let fused_sorted_count = tokens * 4 + 64 * 64;
        assert_eq!(
            shared_moe_inter_scratch_elements(tokens, 10_240, fused_sorted_count, 1_536),
            48_117_760
        );
    }

    #[test]
    fn shared_intermediate_scratch_preserves_larger_routed_geometry() {
        let tokens = 4_699usize;
        let fused_sorted_count = tokens * 8 + 64 * 64;
        assert_eq!(
            shared_moe_inter_scratch_elements(tokens, 12_288, fused_sorted_count, 2_048),
            fused_sorted_count * 2_048
        );
    }
}

