    #[test]
    fn expert_hqq_first_token_margin_projection_json_projects_target_row_difference() {
        let target = FirstTokenMarginProjectionTarget {
            token_a: 0,
            token_b: 1,
            top_n: 2,
        };
        let hidden = vec![bf16_bits(1.0), bf16_bits(2.0)];
        let token_a_row = vec![bf16_bits(3.0), bf16_bits(4.0)];
        let token_b_row = vec![bf16_bits(1.0), bf16_bits(1.0)];
        let layer_delta = FirstTokenMarginProjectionLayerDelta {
            layer_idx: 51,
            trace_row: 1022,
            hidden_size: 2,
            total_active: 4,
            routed_delta: vec![0.5, -1.0],
            expert_contributions: vec![FirstTokenMarginProjectionExpertDelta {
                row: 3,
                expert: Some(60),
                is_cached: Some(true),
                gather_weight: 0.25,
                delta: vec![1.0, 0.0],
            }],
        };
        let json = first_token_margin_projection_trace_json_from_rows(
            target,
            &hidden,
            &token_a_row,
            &token_b_row,
            &[7.0, -1.0],
            0,
            0.0,
            &[layer_delta],
        )
        .unwrap();
        assert_eq!(json["available"], serde_json::json!(true));
        assert_eq!(
            json["final_hidden_projection"]["raw_margin_from_projection"]
                .as_f64()
                .unwrap(),
            8.0
        );
        assert_eq!(
            json["final_hidden_projection"]["downloaded_margin_after_softcap"]
                .as_f64()
                .unwrap(),
            8.0
        );
        assert_eq!(
            json["layer_delta_projections"]["rows"][0]["raw_margin_projection"]
                .as_f64()
                .unwrap(),
            -2.0
        );
        assert_eq!(
            json["layer_delta_projections"]["rows"][0]["expert_contributions"][0]
                ["raw_margin_projection"]
                .as_f64()
                .unwrap(),
            2.0
        );
        assert_eq!(
            json["selected_hidden_before_lm_head_full"]["bf16_bits_u16"]
                .as_array()
                .unwrap()
                .len(),
            2
        );
        assert_eq!(
            json["target_lm_head_row_difference"]["f32_values"]
                .as_array()
                .unwrap()
                .len(),
            2
        );
    }

