    #[test]
    fn test_read_only_checkpoint_gate_and_hashes() {
        assert!(
            !read_only_checkpoint_config_for_scope(false, false, Some("1"))
                .unwrap()
                .enabled
        );
        assert!(
            read_only_checkpoint_config_for_scope(true, false, Some("1"))
                .unwrap_err()
                .contains("debug_reference_trace=true")
        );
        assert!(
            read_only_checkpoint_config_for_scope(true, true, Some("1"))
                .unwrap()
                .enabled
        );

        let bf16_bits = |value: f32| half::bf16::from_f32(value).to_bits();
        let capture = ExpertHqqConsumeBoundaryCapture {
            layer_idx: 1,
            trace_row: 2,
            total_active: 2,
            hidden_size: 2,
            top_n: 2,
            bf16_expert_out: vec![
                bf16_bits(1.0),
                bf16_bits(2.0),
                bf16_bits(3.0),
                bf16_bits(4.0),
            ],
            hqq_expert_out: None,
            gather_src: vec![2, 2],
            gather_weights: vec![0.75, 0.25],
            topk_ids_selected_row: vec![4, 5],
            topk_weights_selected_row: vec![0.75, 0.25],
            expert_ranges: vec![
                ExpertHqqConsumeBoundaryExpertRange {
                    expert: 4,
                    start: 0,
                    end: 1,
                    is_cached: true,
                },
                ExpertHqqConsumeBoundaryExpertRange {
                    expert: 5,
                    start: 1,
                    end: 2,
                    is_cached: false,
                },
            ],
            sync_before_download_success: true,
        };
        let hqq_expert_out = vec![
            bf16_bits(1.5),
            bf16_bits(2.5),
            bf16_bits(2.0),
            bf16_bits(5.0),
        ];
        let before = read_only_checkpoint_layer_delta_state_hashes_json(
            &capture,
            &[1.5, 2.5],
            &[1.625, 3.125],
            &hqq_expert_out,
            "before",
        )
        .unwrap();
        let _ = first_token_margin_projection_layer_delta_from_consume_capture(
            &capture,
            &[1.5, 2.5],
            &[1.625, 3.125],
            &hqq_expert_out,
        )
        .unwrap();
        let after = read_only_checkpoint_layer_delta_state_hashes_json(
            &capture,
            &[1.5, 2.5],
            &[1.625, 3.125],
            &hqq_expert_out,
            "after",
        )
        .unwrap();
        assert_eq!(
            before["route_topk_gather_hashes"],
            after["route_topk_gather_hashes"]
        );
        assert_eq!(
            before["selected_expert_output_state_hashes"],
            after["selected_expert_output_state_hashes"]
        );
    }

    /// Metadata for a test case (parsed from meta.json).
    #[derive(serde::Deserialize)]
    struct TestMeta {
        atol: f64,
        rtol: f64,
        #[allow(dead_code)]
        note: String,
        inputs: std::collections::HashMap<String, TensorMeta>,
        outputs: std::collections::HashMap<String, TensorMeta>,
    }

    #[derive(serde::Deserialize)]
    struct TensorMeta {
        file: String,
        shape: Vec<usize>,
        dtype: String,
    }

    /// Loaded test data: raw bytes + metadata.
    struct TestData {
        meta: TestMeta,
        dir: PathBuf,
    }

    impl TestData {
        fn load(name: &str) -> Self {
            let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
                .join("tests")
                .join("kernel_test_data")
                .join(name);
            assert!(
                dir.exists(),
                "Test data not found: {}. Run: python tests/generate_kernel_test_data.py",
                dir.display()
            );
            let meta_path = dir.join("meta.json");
            let meta_str = std::fs::read_to_string(&meta_path)
                .unwrap_or_else(|e| panic!("Failed to read {}: {}", meta_path.display(), e));
            let meta: TestMeta = serde_json::from_str(&meta_str)
                .unwrap_or_else(|e| panic!("Failed to parse {}: {}", meta_path.display(), e));
            TestData { meta, dir }
        }

        fn input_bytes(&self, name: &str) -> Vec<u8> {
            let tm = &self.meta.inputs[name];
            std::fs::read(self.dir.join(&tm.file)).unwrap()
        }

        fn expected_bytes(&self, name: &str) -> Vec<u8> {
            let tm = &self.meta.outputs[name];
            std::fs::read(self.dir.join(&tm.file)).unwrap()
        }

        fn input_shape(&self, name: &str) -> &[usize] {
            &self.meta.inputs[name].shape
        }

        fn output_shape(&self, name: &str) -> &[usize] {
            &self.meta.outputs[name].shape
        }

        fn numel(shape: &[usize]) -> usize {
            shape.iter().product::<usize>().max(1)
        }
    }

